def obtenir_totaux_match_fiables(m):
    """Calcule et renvoie toujours les totaux fiables (tot_rec, tot_vis) d'un match à partir de la somme réelle des 9 manches si disponible."""
    if not isinstance(m, dict):
        return 0, 0
    matchs_d = m.get("matchs")
    if isinstance(matchs_d, dict) and matchs_d:
        somme_a = 0
        somme_b = 0
        manches_trouvees = False
        for i in range(1, 10):
            m_info = matchs_d.get(str(i))
            if isinstance(m_info, dict) and ("score_a" in m_info or "score_b" in m_info):
                manches_trouvees = True
                try:
                    somme_a += int(m_info.get("score_a", 0) or 0)
                except (ValueError, TypeError):
                    pass
                try:
                    somme_b += int(m_info.get("score_b", 0) or 0)
                except (ValueError, TypeError):
                    pass
        if manches_trouvees and (somme_a > 0 or somme_b > 0 or (m.get("total_receveur") is None and m.get("total_visiteur") is None)):
            m["total_receveur"] = somme_a
            m["total_visiteur"] = somme_b
            return somme_a, somme_b
    try:
        tr = int(m.get("total_receveur") or 0)
    except (ValueError, TypeError):
        tr = 0
    try:
        tv = int(m.get("total_visiteur") or 0)
    except (ValueError, TypeError):
        tv = 0
    return tr, tv


def _cle_match_unique(m):
    """Génère une clé unique pour un match (receveur, visiteur, date normalisée) afin d'éviter les doublons lors des rectifications et synchronisations."""
    if not isinstance(m, dict):
        return ""
    r = str(m.get("receveur") or m.get("equipe_receveur") or "").strip().lower()
    v = str(m.get("visiteur") or m.get("equipe_visiteur") or "").strip().lower()
    d = str(m.get("date_match") or m.get("date") or m.get("date_enregistrement") or "").strip()
    m_dmy = re.match(r"^(\d{2})/(\d{2})/(\d{4})", d)
    m_ymd = re.match(r"^(\d{4})-(\d{2})-(\d{2})", d)
    if m_dmy:
        d_clean = f"{m_dmy.group(3)}{m_dmy.group(2)}{m_dmy.group(1)}"
    elif m_ymd:
        d_clean = f"{m_ymd.group(1)}{m_ymd.group(2)}{m_ymd.group(3)}"
    else:
        d_clean = "".join(c for c in d[:10] if c.isdigit())
    return f"{r}|{v}|{d_clean}"


def _fusionner_listes_matchs(liste_base, liste_complement):
    """Fusionne deux listes de matchs sans doublon en privilégiant la version rectifiée ou la plus récente et en synchronisant les totaux avec les 9 manches."""
    resultat = []
    index_par_cle = {}
    for src in (liste_base or [], liste_complement or []):
        if not isinstance(src, list):
            continue
        for m in src:
            if not isinstance(m, dict):
                continue
            obtenir_totaux_match_fiables(m)
            cle = _cle_match_unique(m)
            if not cle:
                resultat.append(m)
                continue
            if cle not in index_par_cle:
                index_par_cle[cle] = len(resultat)
                resultat.append(m)
            else:
                idx_ex = index_par_cle[cle]
                ex = resultat[idx_ex]
                # Privilégier la version rectifiée ou modifiée le plus récemment
                m_rect = bool(m.get("date_rectification"))
                ex_rect = bool(ex.get("date_rectification"))
                m_ts = float(m.get("ts_modif") or 0)
                ex_ts = float(ex.get("ts_modif") or 0)
                if (m_rect and not ex_rect) or (m_ts > ex_ts):
                    resultat[idx_ex] = m
    return resultat



@st.cache_data

def charger_armoiries_base64(max_taille=(160, 160)):

    """Charge l'image des armoiries, la redimensionne proprement et la renvoie en data URI base64."""

    img_path = find_armoiries_path()

    if not os.path.isfile(img_path):

        return ""

    try:

        from PIL import Image

        import io

        import base64

        im = Image.open(img_path)

        resample_filter = getattr(getattr(Image, "Resampling", Image), "LANCZOS", getattr(Image, "ANTIALIAS", 1))

        im.thumbnail(max_taille, resample_filter)

        buf = io.BytesIO()

        im.save(buf, format="PNG", optimize=True)

        b64 = base64.b64encode(buf.getvalue()).decode("utf-8")

        return f"data:image/png;base64,{b64}"

    except Exception:

        try:

            import base64

            with open(img_path, "rb") as f:

                b64 = base64.b64encode(f.read()).decode("utf-8")

            return f"data:image/png;base64,{b64}"

        except Exception:

            return ""



def injecter_meta_icones_mobiles():

    """Injecte les balises d'icônes mobiles (Apple Touch Icon et Android PWA) dans le DOM pour remplacer la couronne Streamlit sur mobile et tablette."""

    b64_icone = charger_armoiries_base64(max_taille=(192, 192))

    if not b64_icone:

        return



    code_js = f"""

    <script>

    (function() {{

        try {{

            var head = window.parent.document.head;

            if (!head) return;

            var iconUri = "{b64_icone}";



            // 1. apple-touch-icon pour iOS Safari (iPhone & iPad)

            var rels = ["apple-touch-icon", "apple-touch-icon-precomposed"];

            rels.forEach(function(r) {{

                var el = window.parent.document.querySelector("link[rel='" + r + "']");

                if (!el) {{

                    el = window.parent.document.createElement("link");

                    el.rel = r;

                    head.appendChild(el);

                }}

                el.href = iconUri;

            }});



            // 2. Icônes pour Android / Chrome (192x192 & 512x512)

            var sizes = ["192x192", "512x512", "180x180", "32x32"];

            sizes.forEach(function(s) {{

                var el = window.parent.document.querySelector("link[rel='icon'][sizes='" + s + "']");

                if (!el) {{

                    el = window.parent.document.createElement("link");

                    el.rel = "icon";

                    el.sizes = s;

                    head.appendChild(el);

                }}

                el.href = iconUri;

            }});



            // 3. Titre mobile et capacité plein écran

            var metaApp = window.parent.document.querySelector("meta[name='apple-mobile-web-app-title']");

            if (!metaApp) {{

                metaApp = window.parent.document.createElement("meta");

                metaApp.name = "apple-mobile-web-app-title";

                head.appendChild(metaApp);

            }}

            metaApp.content = "Billard Saphir";



            var metaCap = window.parent.document.querySelector("meta[name='apple-mobile-web-app-capable']");

            if (!metaCap) {{

                metaCap = window.parent.document.createElement("meta");

                metaCap.name = "apple-mobile-web-app-capable";

                head.appendChild(metaCap);

            }}

            metaCap.content = "yes";



            // 4. Manifeste PWA

            var linkMan = window.parent.document.querySelector("link[rel='manifest']");

            if (!linkMan) {{

                linkMan = window.parent.document.createElement("link");

                linkMan.rel = "manifest";

                linkMan.href = "/app/static/manifest.json";

                head.appendChild(linkMan);

            }}

        }} catch(e) {{}}

    }})();

    </script>

    """

    st.components.v1.html(code_js, height=0)



