# MOTEUR CLOUD HYBRIDE : SUPABASE POSTGRESQL & GITHUB

# ==============================================================================

SUPABASE_URL_DEFAULT = "https://ueikhwdfmtnavqqscdoe.supabase.co"

SUPABASE_KEY_DEFAULT = ""



def obtenir_parametres_supabase():

    """Récupère les paramètres de connexion Supabase (URL, clé API, mode actif) avec tolérance maximale aux formats et alias."""

    from collections.abc import Mapping

    url = SUPABASE_URL_DEFAULT or "https://ueikhwdfmtnavqqscdoe.supabase.co"

    key = SUPABASE_KEY_DEFAULT or ""

    mode = "supabase"  # Mode 1 par défaut : Supabase prioritaire



    # 1. Lecture depuis config_admin.json

    try:

        cfg_adm = charger_config_admin()

        if isinstance(cfg_adm, dict):

            for k, v in cfg_adm.items():

                if not v:

                    continue

                v_str = str(v).strip()

                k_l = str(k).lower().replace("-", "_").replace(" ", "_")

                if k_l in ("supabase_url", "sb_url", "url_supabase", "supabase_endpoint"):

                    url = v_str

                elif k_l in ("supabase_key", "sb_key", "sb_secret", "supabase_secret", "supabase_api_key", "service_role_key", "cle_supabase", "cle_secrete_supabase"):

                    key = v_str

                elif k_l in ("cloud_mode", "cloud_storage_mode", "mode_cloud"):

                    mode = v_str

    except Exception:

        pass



    # 2. Variables d'environnement

    for env_k, env_v in os.environ.items():

        if not env_v:

            continue

        v_str = str(env_v).strip()

        k_l = str(env_k).lower().replace("-", "_")

        if k_l in ("supabase_url", "sb_url", "url_supabase"):

            url = v_str

        elif k_l in ("supabase_key", "sb_key", "sb_secret", "supabase_secret", "service_role_key"):

            key = v_str

        elif k_l in ("cloud_mode", "cloud_storage_mode", "mode_cloud"):

            mode = v_str



    # 3. Streamlit secrets (st.secrets) - Balayage récursif intelligent et tolérant

    try:

        if hasattr(st, "secrets") and st.secrets is not None:

            def _extraire_secrets_sb(obj, prefix=""):

                res = []

                try:

                    if isinstance(obj, (dict, Mapping)) or hasattr(obj, "items"):

                        for k, v in obj.items():

                            res.extend(_extraire_secrets_sb(v, f"{prefix}.{k}" if prefix else str(k)))

                    elif hasattr(obj, "keys"):

                        for k in obj.keys():

                            res.extend(_extraire_secrets_sb(obj[k], f"{prefix}.{k}" if prefix else str(k)))

                    else:

                        res.append((prefix, str(obj).strip()))

                except Exception:

                    pass

                return res



            tous_secrets = _extraire_secrets_sb(st.secrets)



            for k_path, v_val in tous_secrets:

                if not v_val:

                    continue

                # Détection par valeur caractéristique

                if v_val.startswith("sb_secret_") or v_val.startswith("sb_publishable_"):

                    key = v_val

                elif v_val.startswith("https://") and "supabase.co" in v_val and "/rest" not in v_val:

                    url = v_val



                # Détection par nom de clé ou chemin

                k_full = k_path.lower().replace("-", "_").replace(" ", "_")

                k_simple = k_full.split(".")[-1]

                if any(x in k_full for x in ("supabase_url", "sb_url", "url_supabase", "supabase.url")):

                    url = v_val

                elif any(x in k_full for x in ("supabase_key", "sb_key", "supabase_secret", "supabase.key", "service_role_key")):

                    key = v_val

                elif k_simple in ("cloud_mode", "cloud_storage_mode", "mode_cloud"):

                    mode = v_val

    except Exception:

        pass



    return url, key, mode



def sauvegarder_parametres_supabase(url, key, mode="supabase"):

    """Enregistre les paramètres Supabase dans config_admin.json."""

    try:

        data = charger_config_admin()

        data["supabase_url"] = (url or SUPABASE_URL_DEFAULT or "https://ueikhwdfmtnavqqscdoe.supabase.co").strip()

        data["supabase_key"] = (key or "").strip()

        data["cloud_mode"] = (mode or "supabase").strip()

        with open(ADMIN_CONFIG_FILE, "w", encoding="utf-8") as f:

            json.dump(data, f, ensure_ascii=False, indent=4)

        return True

    except Exception:

        return False



def tester_connexion_supabase(url=None, key=None):

    """Teste la connexion directe avec la table public.saphir_files dans Supabase PostgreSQL."""

    u_def, k_def, _ = obtenir_parametres_supabase()

    u = (url or u_def or "").strip()

    k = (key or k_def or "").strip()

    if not u or not k:

        return False, f"URL ou clé API Supabase manquante (URL: {'présente' if u else 'manquante'}, Clé: {'présente' if k else 'manquante'})."

    try:

        import urllib.request

        req = urllib.request.Request(

            f"{u.rstrip('/')}/rest/v1/saphir_files?select=filename&limit=1",

            headers={

                "apikey": k,

                "Authorization": f"Bearer {k}"

            }

        )

        with urllib.request.urlopen(req, timeout=7) as resp:

            if resp.status == 200:

                return True, "Connexion établie avec succès à la base Supabase PostgreSQL !"

            return False, f"Réponse HTTP inattendue : {resp.status}"

    except Exception as e:

        return False, f"Impossible de joindre Supabase : {e}"



def diffuser_evenement_pubsub_sms(action="CHECK_NOW", details=None):

    """

    Diffuse un événement en direct via l'infrastructure Pub/Sub Supabase Realtime Broadcast.

    Permet à l'application mobile Android SaphirSMS (connectée en direct via WebSocket)

    de réagir instantanément (< 1 sec) en temps réel dès la diffusion du signal.

    """

    url_sb, key_sb, _ = obtenir_parametres_supabase()

    if not url_sb or not key_sb:

        return False, "Supabase non configuré."



    try:

        import urllib.request

        base_url = url_sb.rstrip("/")

        headers = {

            "apikey": key_sb,

            "Authorization": f"Bearer {key_sb}",

            "Content-Type": "application/json"

        }



        payload_data = {

            "action": action,

            "timestamp": int(time.time()),

            "details": details or {}

        }



        # 1. Envoi direct via URL Supabase Realtime Broadcast

        direct_url = f"{base_url}/realtime/v1/api/broadcast/saphir_sms/events/sms_trigger"

        direct_req = urllib.request.Request(

            direct_url,

            data=json.dumps(payload_data, ensure_ascii=False).encode("utf-8"),

            headers=headers,

            method="POST"

        )

        try:

            with urllib.request.urlopen(direct_req, timeout=4) as resp_d:

                if resp_d.status in (200, 201, 202, 204):

                    pass

        except Exception:

            pass



        # 2. Envoi au format batch (topic = 'saphir_sms')

        batch_body = {

            "messages": [

                {

                    "topic": "saphir_sms",

                    "event": "sms_trigger",

                    "payload": payload_data

                }

            ]

        }

        batch_req = urllib.request.Request(

            f"{base_url}/realtime/v1/api/broadcast",

            data=json.dumps(batch_body, ensure_ascii=False).encode("utf-8"),

            headers=headers,

            method="POST"

        )

        try:

            with urllib.request.urlopen(batch_req, timeout=4) as resp_b:

                if resp_b.status in (200, 201, 202, 204):

                    return True, "Notification Pub/Sub diffusée en direct."

        except Exception:

            pass



        return True, "Diffusion Pub/Sub transmise."

    except Exception as e:

        return False, f"Diffusion Pub/Sub ignorée : {e}"



def synchroniser_fichier_supabase(filepath, commit_message=None, forcer=False):

    """Pousse un fichier local (.json ou .csv) vers la table public.saphir_files de Supabase (upsert)."""

    if not filepath or not os.path.exists(filepath):

        return False, "Fichier local introuvable."

    filename = os.path.basename(filepath)

    url_sb, key_sb, _ = obtenir_parametres_supabase()

    if not url_sb or not key_sb:

        return False, "Paramètres Supabase non configurés."



    try:

        import urllib.request

        import hashlib

        from datetime import datetime, timezone



        with open(filepath, "r", encoding="utf-8") as f:

            content = f.read()



        # Nettoyage sécurité pour config_admin.json

        if filename == "config_admin.json":

            try:

                d_sec = json.loads(content)

                d_sec["github_token"] = ""

                d_sec["gemini_api_key"] = ""

                d_sec["supabase_key"] = ""

                content = json.dumps(d_sec, indent=4, ensure_ascii=False)

            except Exception:

                pass



        sha1_initial = hashlib.sha1(content.encode("utf-8")).hexdigest()
        if not forcer and _LAST_SYNCED_SHA_SUPABASE.get(filename) == sha1_initial:
            return True, f"Fichier {filename} déjà strictement à jour sur Supabase (cache SHA1)."

        # Protection anti-perte de matchs pour historique_matchs.json

        if filename == "historique_matchs.json":

            try:

                raw_ex = telecharger_fichier_supabase("historique_matchs.json")

                if raw_ex:

                    sb_ex_list = json.loads(raw_ex)

                    if isinstance(sb_ex_list, list) and len(sb_ex_list) > 0:

                        cur_m_list = json.loads(content)

                        if isinstance(cur_m_list, list):

                            cles_loc = {_cle_match_unique(m) for m in cur_m_list if isinstance(m, dict)}

                            sb_a_garder = [m for m in sb_ex_list if isinstance(m, dict) and _cle_match_unique(m) not in cles_loc]

                            if sb_a_garder:

                                cur_m_list.extend(sb_a_garder)

                                content = json.dumps(cur_m_list, ensure_ascii=False, indent=4)

                                with open(filepath, "w", encoding="utf-8") as f_rew:

                                    f_rew.write(content)

                                _FILE_MEM_CACHE.pop("historique_matchs", None)

            except Exception:

                pass



        sha1_val = hashlib.sha1(content.encode("utf-8")).hexdigest()

        payload = {

            "filename": filename,

            "content": content,

            "sha1": sha1_val,

            "commit_message": commit_message or f"Sauvegarde {filename} ({datetime.now().strftime('%H:%M:%S')})",

            "updated_at": datetime.now(timezone.utc).isoformat()

        }



        req = urllib.request.Request(

            f"{url_sb.rstrip('/')}/rest/v1/saphir_files",

            data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),

            headers={

                "apikey": key_sb,

                "Authorization": f"Bearer {key_sb}",

                "Content-Type": "application/json",

                "Prefer": "resolution=merge-duplicates"

            },

            method="POST"

        )

        with urllib.request.urlopen(req, timeout=8) as resp:

            if resp.status in (200, 201, 204):

                _LAST_SYNCED_SHA_SUPABASE[filename] = sha1_val

                try:

                    st.session_state["dernier_sync_cloud"] = f"✅ {filename} synchronisé sur Supabase ({datetime.now().strftime('%H:%M:%S')})"

                except Exception:

                    pass

                if filename in ("historique_matchs.json", "config_sms.json"):

                    try:

                        diffuser_evenement_pubsub_sms(action="FICHIER_MAJ", details={"filename": filename})

                    except Exception:

                        pass

                return True, f"Fichier {filename} sauvegardé sur Supabase PostgreSQL."

            return False, f"Erreur HTTP {resp.status} Supabase."

    except Exception as e:

        return False, f"Erreur synchronisation Supabase ({filename}) : {e}"



def telecharger_fichier_supabase(filename):

    """Télécharge le contenu brut d'un fichier stocké dans la table public.saphir_files de Supabase."""

    url_sb, key_sb, _ = obtenir_parametres_supabase()

    if not url_sb or not key_sb:

        return None

    try:

        import urllib.request

        import urllib.parse

        q_fn = urllib.parse.quote(filename)

        req = urllib.request.Request(

            f"{url_sb.rstrip('/')}/rest/v1/saphir_files?filename=eq.{q_fn}&select=content,sha1,updated_at",

            headers={

                "apikey": key_sb,

                "Authorization": f"Bearer {key_sb}"

            }

        )

        with urllib.request.urlopen(req, timeout=8) as resp:

            if resp.status == 200:

                rows = json.loads(resp.read().decode("utf-8"))

                if rows and isinstance(rows, list) and len(rows) > 0:

                    return rows[0].get("content")

    except Exception:

        pass

    return None



def synchroniser_tous_les_fichiers_supabase(commit_prefix=None):

    """Pousse tous les fichiers locaux .json et .csv vers Supabase PostgreSQL."""

    fichiers = lister_fichiers_locaux_donnees()

    succes = []

    erreurs = []

    prefix = (commit_prefix or "Sauvegarde automatique").strip()

    date_str = datetime.now().strftime("%d/%m/%Y %H:%M:%S")



    for fp in fichiers:

        fn = os.path.basename(fp)

        msg = f"{prefix} {fn} ({date_str})"

        ok, info = synchroniser_fichier_supabase(fp, msg)

        if ok:

            succes.append(fn)

        else:

            erreurs.append(f"{fn} ({info})")



    return len(succes), succes, erreurs



def synchroniser_fichiers_cibles_cloud(filepaths, commit_prefix=None):
    """Synchronise uniquement une liste ciblée de fichiers modifiés vers le Cloud actif."""
    if not filepaths:
        return 0, [], []
    succes_list = []
    erreurs_list = []
    prefix = (commit_prefix or "Sauvegarde automatique").strip()
    date_str = datetime.now().strftime("%d/%m/%Y %H:%M:%S")
    vus = set()
    for fp in filepaths:
        if not fp or not os.path.exists(fp):
            continue
        fp_abs = os.path.abspath(fp)
        if fp_abs in vus:
            continue
        vus.add(fp_abs)
        fn = os.path.basename(fp)
        msg = f"{prefix} {fn} ({date_str})"
        ok, info = synchroniser_fichier_cloud(fp, msg)
        if ok:
            succes_list.append(fn)
        else:
            erreurs_list.append(f"{fn} ({info})")
    return len(succes_list), succes_list, erreurs_list


def synchroniser_fichier_cloud(filepath, commit_message=None):

    """Route la synchronisation du fichier selon le mode Cloud Hybride configuré (Mode 1 Supabase, Mode 2 Hybride, Mode 3 GitHub)."""

    _, _, mode = obtenir_parametres_supabase()

    if mode == "supabase":

        return synchroniser_fichier_supabase(filepath, commit_message)

    elif mode == "supabase_github":

        ok_sb, msg_sb = synchroniser_fichier_supabase(filepath, commit_message)

        ok_gh, msg_gh = synchroniser_fichier_github(filepath, commit_message)

        return (ok_sb or ok_gh), f"Supabase: {msg_sb} | GitHub: {msg_gh}"

    else:

        return synchroniser_fichier_github(filepath, commit_message)



def synchroniser_tous_les_fichiers_cloud(commit_prefix=None):

    """Synchronise tous les fichiers de données selon le mode Cloud Hybride configuré."""

    _, _, mode = obtenir_parametres_supabase()

    if mode == "supabase":

        return synchroniser_tous_les_fichiers_supabase(commit_prefix)

    elif mode == "supabase_github":

        nb_sb, ok_sb, err_sb = synchroniser_tous_les_fichiers_supabase(commit_prefix)

        nb_gh, ok_gh, err_gh = synchroniser_tous_les_fichiers_github_brut(commit_prefix)

        return max(nb_sb, nb_gh), list(set(ok_sb + ok_gh)), err_sb + err_gh

    else:

        return synchroniser_tous_les_fichiers_github_brut(commit_prefix)



def synchroniser_tous_les_fichiers_github(commit_prefix=None):

    """Route automatiquement toutes les sauvegardes vers le moteur Cloud actif (Supabase ou GitHub)."""

    return synchroniser_tous_les_fichiers_cloud(commit_prefix=commit_prefix)



def restaurer_tout_depuis_supabase(forcer=False):

    """Restaure l'ensemble des donnees officielles (.json et .csv) depuis la table public.saphir_files de Supabase PostgreSQL avec fusion securisee."""

    try:

        nb_maj_sb = 0

        details_sb = []



        # 1. Historique des matchs (fusion securisee anti-perte)

        raw_hm = telecharger_fichier_supabase("historique_matchs.json")

        if raw_hm:

            sb_matchs = json.loads(raw_hm)

            if isinstance(sb_matchs, list) and len(sb_matchs) > 0:

                loc_matchs = []

                if os.path.exists(HISTORIQUE_FILE):

                    try:

                        with open(HISTORIQUE_FILE, "r", encoding="utf-8") as f_r:

                            loc_matchs = json.load(f_r)

                        if not isinstance(loc_matchs, list):

                            loc_matchs = []

                    except Exception:

                        loc_matchs = []



                cles_sb = {_cle_match_unique(m) for m in sb_matchs if _cle_match_unique(m)}

                matchs_fusionnes = _fusionner_listes_matchs(sb_matchs, loc_matchs)



                tmp_p = f"{HISTORIQUE_FILE}.tmp"

                with open(tmp_p, "w", encoding="utf-8") as f_tmp:

                    json.dump(matchs_fusionnes, f_tmp, ensure_ascii=False, indent=4)

                try:

                    os.replace(tmp_p, HISTORIQUE_FILE)

                except Exception:

                    with open(HISTORIQUE_FILE, "w", encoding="utf-8") as f_w:

                        json.dump(matchs_fusionnes, f_w, ensure_ascii=False, indent=4)

                    if os.path.exists(tmp_p):

                        try:

                            os.remove(tmp_p)

                        except Exception:

                            pass

                try:

                    _FILE_MEM_CACHE.pop("historique_matchs", None)

                except Exception:

                    pass

                nb_maj_sb += 1

                details_sb.append(f"historique_matchs.json ({len(matchs_fusionnes)} matchs)")



        # 2. Historique des tournois

        raw_ht = telecharger_fichier_supabase("historique_tournois.json")

        if raw_ht:

            sb_tournois = json.loads(raw_ht)

            if isinstance(sb_tournois, list) and len(sb_tournois) > 0:

                with open(HISTORIQUE_TOURNOIS_FILE, "w", encoding="utf-8") as f_wt:

                    json.dump(sb_tournois, f_wt, ensure_ascii=False, indent=4)

                try:

                    _FILE_MEM_CACHE.pop("historique_tournois", None)

                except Exception:

                    pass

                nb_maj_sb += 1

                details_sb.append(f"historique_tournois.json ({len(sb_tournois)} tournois)")



        # 3. Donnees des tournois actifs

        raw_td = telecharger_fichier_supabase("tournois_data.json")

        if raw_td:

            try:

                sb_td = json.loads(raw_td)

                if isinstance(sb_td, dict) and sb_td:

                    loc_td_obj = charger_tournois_data()

                    for m_ch in ["simple", "double"]:

                        t_loc = loc_td_obj.get(m_ch)

                        t_sb = sb_td.get(m_ch)

                        if t_loc and isinstance(t_loc, dict) and t_loc.get("statut") in ("en_cours", "termine"):

                            if not t_sb or not isinstance(t_sb, dict):

                                sb_td[m_ch] = t_loc

                    with open(TOURNOIS_FILE, "w", encoding="utf-8") as f_wtd:

                        json.dump(sb_td, f_wtd, ensure_ascii=False, indent=4)

                try:

                    _FILE_MEM_CACHE.pop("tournois_data", None)

                except Exception:

                    pass

                nb_maj_sb += 1

                details_sb.append("tournois_data.json")

            except Exception:

                pass



        # 4. Equipes CSV

        raw_eq = telecharger_fichier_supabase("equipes-saphir.csv")

        if raw_eq and len(raw_eq.strip()) > 10:

            with open(EQUIPES_CSV_FILE, "w", encoding="utf-8") as f_weq:

                f_weq.write(raw_eq)

            try:

                _FILE_MEM_CACHE.pop("equipes_csv", None)

            except Exception:

                pass

            nb_maj_sb += 1

            details_sb.append("equipes-saphir.csv")



        # 5. Autres fichiers

        for fn_autre, fp_autre in [

            ("horaire_saphir.json", HORAIRE_SAPHIR_FILE),

            ("joueurs_stats.csv", JOUEURS_CSV_FILE),

            ("config_email.json", CONFIG_EMAIL_FILE),

            ("joueurs_sms.json", JOUEURS_SMS_FILE),

            ("config_sms.json", CONFIG_SMS_FILE),

            ("commandes_sms.json", COMMANDES_SMS_FILE)

        ]:

            raw_autre = telecharger_fichier_supabase(fn_autre)

            if raw_autre and len(raw_autre.strip()) > 0:

                with open(fp_autre, "w", encoding="utf-8") as f_wa:

                    f_wa.write(raw_autre)

                try:

                    _FILE_MEM_CACHE.pop(fn_autre.replace(".", "_"), None)

                except Exception:

                    pass

                nb_maj_sb += 1

                details_sb.append(fn_autre)



        if nb_maj_sb > 0:

            return True, f"Donnees restaurees depuis Supabase PostgreSQL : {', '.join(details_sb)}."

        return False, "Aucun fichier mis a jour depuis Supabase."

    except Exception as e_sb_rst:

        return False, f"Erreur lors de la restauration Supabase : {e_sb_rst}"



def restaurer_depuis_cloud_au_reveil(forcer=False):

    """Au reveil de l'application ou sur demande, restaure les donnees les plus recentes depuis Supabase (Mode 1/2) ou GitHub (Mode 3)."""

    try:

        if not forcer and st.session_state.get("cloud_wake_sync_done", False):

            return False, "Deja synchronise pour cette session."

    except Exception:

        pass



    _, _, mode = obtenir_parametres_supabase()



    # Si Mode 1 ou Mode 2 : Restauration depuis Supabase prioritaire

    if mode in ("supabase", "supabase_github"):

        ok_sb, msg_sb = restaurer_tout_depuis_supabase(forcer=forcer)

        if ok_sb:

            try:

                st.session_state["cloud_wake_sync_done"] = True

            except Exception:

                pass

            return True, msg_sb



    # En repli ou en Mode 3 : Restauration depuis GitHub

    res_gh, msg_gh = restaurer_depuis_github_au_reveil(forcer=forcer)

    try:

        st.session_state["cloud_wake_sync_done"] = True

    except Exception:

        pass

    return res_gh, msg_gh



import copy

import threading



_FILE_MEM_CACHE = {}

_SYNC_GITHUB_LOCK = threading.Lock()

_SYNC_GITHUB_TIMER = None

_PENDING_SYNC_FILES = {}  # {filepath_ou_ALL: (commit_prefix, nb_tentatives)}



def _lire_cache_fichier(cle_cache, filepath):

    """Retourne une copie des données en cache mémoire si le fichier sur disque n'a pas changé (mtime + taille)."""

    try:

        if os.path.exists(filepath):

            st_stat = os.stat(filepath)

            sig = (st_stat.st_mtime_ns, st_stat.st_size)

            entree = _FILE_MEM_CACHE.get(cle_cache)

            if entree and entree[0] == sig:

                return True, copy.deepcopy(entree[1])

    except Exception:

        pass

    return False, None



def _ecrire_cache_fichier(cle_cache, filepath, data):

    """Mémorise les données associées à l'empreinte actuelle (mtime + taille) du fichier."""

    try:

        if os.path.exists(filepath):

            st_stat = os.stat(filepath)

            sig = (st_stat.st_mtime_ns, st_stat.st_size)

            _FILE_MEM_CACHE[cle_cache] = (sig, copy.deepcopy(data))

    except Exception:

        pass



def declencher_sync_github_arriere_plan(delai=1.5, commit_prefix=None, filepath=None, filepaths=None):

    """Déclenche la synchronisation Cloud en arrière-plan avec file d'attente persistante (Dirty Queue) et reprise automatique.

    Accumule tous les fichiers modifiés sans jamais annuler un fichier en attente lorsqu'une nouvelle sauvegarde survient.

    """

    global _SYNC_GITHUB_TIMER

    delai_effectif = max(float(delai or 1.5), 1.5)

    def _planifier_timer(secondes):
        global _SYNC_GITHUB_TIMER
        if _SYNC_GITHUB_TIMER is not None:
            try:
                _SYNC_GITHUB_TIMER.cancel()
            except Exception:
                pass
        _SYNC_GITHUB_TIMER = threading.Timer(secondes, _worker)
        _SYNC_GITHUB_TIMER.daemon = True
        _SYNC_GITHUB_TIMER.start()

    def _worker():
        with _SYNC_GITHUB_LOCK:
            if not _PENDING_SYNC_FILES:
                return
            lot_courant = dict(_PENDING_SYNC_FILES)
            _PENDING_SYNC_FILES.clear()

        echecs = {}
        try:
            if "__ALL__" in lot_courant:
                pref_all, tentatives = lot_courant["__ALL__"]
                nb_ok, _, errs = synchroniser_tous_les_fichiers_github(commit_prefix=pref_all)
                if errs and tentatives < 3:
                    echecs["__ALL__"] = (pref_all, tentatives + 1)
            else:
                for fp_item, (pref_item, tentatives) in lot_courant.items():
                    try:
                        ok_f, _ = synchroniser_fichier_cloud(fp_item, pref_item)
                        if not ok_f and tentatives < 3:
                            echecs[fp_item] = (pref_item, tentatives + 1)
                    except Exception:
                        if tentatives < 3:
                            echecs[fp_item] = (pref_item, tentatives + 1)
        except Exception:
            pass

        if echecs:
            with _SYNC_GITHUB_LOCK:
                for k_e, v_e in echecs.items():
                    if k_e not in _PENDING_SYNC_FILES:
                        _PENDING_SYNC_FILES[k_e] = v_e
                _planifier_timer(6.0)

    with _SYNC_GITHUB_LOCK:
        cibles = []
        if filepaths:
            cibles.extend([f for f in filepaths if f])
        if filepath:
            cibles.append(filepath)

        if cibles:
            for c_fp in cibles:
                fp_norm = os.path.abspath(c_fp)
                _PENDING_SYNC_FILES[fp_norm] = (commit_prefix, 0)
        else:
            _PENDING_SYNC_FILES["__ALL__"] = (commit_prefix, 0)

        _planifier_timer(delai_effectif)



def charger_equipes_csv():

    """Charge la liste des équipes et joueurs depuis le fichier CSV (avec cache mémoire instantané sur mtime)."""

    ok_c, val_c = _lire_cache_fichier("equipes_csv", EQUIPES_CSV_FILE)

    if ok_c and val_c:

        return val_c

    equipes = {}

    if os.path.exists(EQUIPES_CSV_FILE):

        try:

            with open(EQUIPES_CSV_FILE, "r", encoding="utf-8") as f:

                for line in f:

                    parts = [p.strip() for p in line.strip().split(",") if p.strip()]

                    if len(parts) >= 2:

                        nom_eq = parts[0]

                        joueurs = parts[1:]

                        while len(joueurs) < 3:

                            joueurs.append(f"Joueur {len(joueurs)+1}")

                        equipes[nom_eq] = joueurs[:3]

            if equipes:

                _ecrire_cache_fichier("equipes_csv", EQUIPES_CSV_FILE, equipes)

        except Exception as e:

            st.error(f"Erreur lors de la lecture du fichier {EQUIPES_CSV_FILE} : {e}")

    return equipes



def sauvegarder_equipes_csv(equipes_df_ou_dict):

    """Sauvegarde les équipes et leurs 3 joueurs dans le fichier equipes-saphir.csv.

    Format par ligne : Equipe,Joueur 1,Joueur 2,Joueur 3

    """

    try:

        lignes = []

        if isinstance(equipes_df_ou_dict, pd.DataFrame):

            for _, row in equipes_df_ou_dict.iterrows():

                eq = str(row.get("Equipe", "")).strip()

                if not eq:

                    continue

                j1 = str(row.get("Joueur 1", "")).strip()

                j2 = str(row.get("Joueur 2", "")).strip()

                j3 = str(row.get("Joueur 3", "")).strip()

                lignes.append(f"{eq},{j1},{j2},{j3}\n")

        elif isinstance(equipes_df_ou_dict, dict):

            for eq, joueurs in equipes_df_ou_dict.items():

                eq_clean = str(eq).strip()

                if not eq_clean:

                    continue

                j1 = str(joueurs[0]).strip() if len(joueurs) > 0 else ""

                j2 = str(joueurs[1]).strip() if len(joueurs) > 1 else ""

                j3 = str(joueurs[2]).strip() if len(joueurs) > 2 else ""

                lignes.append(f"{eq_clean},{j1},{j2},{j3}\n")

        elif isinstance(equipes_df_ou_dict, list):

            for row in equipes_df_ou_dict:

                if isinstance(row, dict):

                    eq = str(row.get("Equipe", "")).strip()

                    if not eq:

                        continue

                    j1 = str(row.get("Joueur 1", "")).strip()

                    j2 = str(row.get("Joueur 2", "")).strip()

                    j3 = str(row.get("Joueur 3", "")).strip()

                    lignes.append(f"{eq},{j1},{j2},{j3}\n")

                elif isinstance(row, (list, tuple)) and len(row) >= 4:

                    eq = str(row[0]).strip()

                    if not eq:

                        continue

                    lignes.append(f"{eq},{str(row[1]).strip()},{str(row[2]).strip()},{str(row[3]).strip()}\n")



        # Sauvegarde d'une copie de secours .bak

        if os.path.exists(EQUIPES_CSV_FILE):

            try:

                import shutil

                shutil.copyfile(EQUIPES_CSV_FILE, EQUIPES_CSV_FILE + ".bak")

            except Exception:

                pass



        with open(EQUIPES_CSV_FILE, "w", encoding="utf-8") as f:

            f.writelines(lignes)



        synchroniser_tous_les_fichiers_github(commit_prefix=f"Mise a jour equipes-saphir.csv ({len(lignes)} equipes)")

        return True, f"{len(lignes)} équipe(s) enregistrée(s) avec succès dans equipes-saphir.csv."

    except Exception as e:

        return False, f"Erreur lors de la sauvegarde du fichier equipes-saphir.csv : {e}"



def charger_sauvegarde():

    """Lit le fichier de sauvegarde de secours sans jamais lever d'erreur."""

    if os.path.exists(BACKUP_FILE):

        try:

            with open(BACKUP_FILE, "r", encoding="utf-8") as f:

                data = json.load(f)

                if isinstance(data, dict):

                    return data

        except Exception:

            return {}

    return {}



def sauvegarder_donnees(data):

    """Écrit atomiquement la sauvegarde uniquement lorsque les données utiles ont changé et regroupe la synchronisation GitHub."""

    try:

        empreinte = json.dumps({

            "receveur": data.get("receveur"),

            "visiteur": data.get("visiteur"),

            "joueurs": data.get("joueurs"),

            "matchs": data.get("matchs")

        }, sort_keys=True, ensure_ascii=False)

        if _FILE_MEM_CACHE.get("last_backup_sig") == empreinte and os.path.exists(BACKUP_FILE):

            return

        _FILE_MEM_CACHE["last_backup_sig"] = empreinte

        data["derniere_mise_a_jour"] = datetime.now().strftime("%H:%M:%S")

        data["ts_modif"] = time.time()

        with open(BACKUP_FILE, "w", encoding="utf-8") as f:

            json.dump(data, f, ensure_ascii=False, indent=4)

        declencher_sync_github_arriere_plan(delai=6.0, commit_prefix="Sauvegarde saisie secours", filepath=BACKUP_FILE)

    except Exception as e:

        st.error(f"Erreur lors de la sauvegarde automatique : {e}")



def charger_config_email():

    """Charge la configuration SMTP au démarrage de l'application depuis config_email.json, st.secrets et l'environnement."""

    from collections.abc import Mapping

    defaut = {

        "destinataires": "",

        "smtp_serveur": "smtp.gmail.com",

        "smtp_port": 587,

        "smtp_expediteur": "",

        "smtp_mdp": "",

        "smtp_ssl": False

    }

    sources = {}



    if os.path.exists(CONFIG_EMAIL_FILE):

        try:

            with open(CONFIG_EMAIL_FILE, "r", encoding="utf-8") as f:

                d = json.load(f)

                if isinstance(d, dict):

                    d_norm = normaliser_donnees_email(d)

                    defaut.update(d_norm)

                    for k in d_norm:

                        sources[k] = "config_email.json"

        except Exception:

            pass



    # Prise en compte de st.secrets (Streamlit Secrets / Cloud)

    try:

        if hasattr(st, "secrets"):

            for sec_em in ["email", "Email", "EMAIL", "smtp", "Smtp", "SMTP", "mail", "Mail"]:

                if sec_em in st.secrets:

                    sec_val = st.secrets[sec_em]

                    if isinstance(sec_val, (dict, Mapping)) or hasattr(sec_val, "items"):

                        norm_em = normaliser_donnees_email(dict(sec_val))

                        for k, v in norm_em.items():

                            defaut[k] = v

                            sources[k] = f"st.secrets [{sec_em}]"



            # Clés directes à la racine

            try:

                racine_em = {}

                for r_k in st.secrets.keys():

                    r_v = st.secrets[r_k]

                    if not isinstance(r_v, (dict, Mapping)) and not hasattr(r_v, "items"):

                        racine_em[r_k] = r_v

                norm_root_em = normaliser_donnees_email(racine_em)

                for k, v in norm_root_em.items():

                    defaut[k] = v

                    sources[k] = "st.secrets [racine]"

            except Exception:

                pass

    except Exception:

        pass



    # Prise en compte de os.environ

    for env_k, def_k in [

        ("SMTP_SERVEUR", "smtp_serveur"),

        ("SMTP_EXPEDITEUR", "smtp_expediteur"),

        ("SMTP_MDP", "smtp_mdp"),

        ("DESTINATAIRES", "destinataires"),

    ]:

        if os.environ.get(env_k):

            defaut[def_k] = os.environ.get(env_k, "").strip()

            sources[def_k] = f"os.environ ({env_k})"



    try:

        st.session_state["sources_config_email"] = sources

    except Exception:

        pass



    return defaut



def sauvegarder_config_email(cfg):

    try:

        with open(CONFIG_EMAIL_FILE, "w", encoding="utf-8") as f:

            json.dump(cfg, f, ensure_ascii=False, indent=4)

        synchroniser_tous_les_fichiers_github(commit_prefix="Mise a jour config_email.json")

        return True

    except Exception:

        return False



# ==============================================================================

# GESTION DU VERROU DE SESSION EXCLUSIF (UN SEUL MARQUEUR À LA FOIS)

# ==============================================================================

def gerer_verrou_session(my_session_id, veut_etre_editeur=True):

    """Vérifie si la session actuelle détient le verrou d'édition ou l'acquiert."""

    maintenant = time.time()

    lock_existant = {}

    if os.path.exists(LOCK_FILE):

        try:

            with open(LOCK_FILE, "r", encoding="utf-8") as f:

                lock_existant = json.load(f)

        except Exception:

            lock_existant = {}



    detenteur = lock_existant.get("session_id")

    dernier_acces = lock_existant.get("dernier_acces", 0)

    expire = (maintenant - dernier_acces) > LOCK_TIMEOUT



    # Si l'utilisateur est volontairement en mode lecture / consultation

    if not veut_etre_editeur:

        if detenteur and not expire and detenteur != my_session_id:

            temps_restant = int(LOCK_TIMEOUT - (maintenant - dernier_acces))

            return False, max(0, temps_restant), True

        return False, 0, False



    if not detenteur or expire or detenteur == my_session_id:

        nouveau_lock = {

            "session_id": my_session_id,

            "dernier_acces": maintenant,

            "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S")

        }

        try:

            with open(LOCK_FILE, "w", encoding="utf-8") as f:

                json.dump(nouveau_lock, f, indent=4)

        except Exception:

            pass

        return True, 0, False

    else:

        temps_restant = int(LOCK_TIMEOUT - (maintenant - dernier_acces))

        return False, max(0, temps_restant), True



def liberer_verrou(my_session_id):

    """Libère le verrou de session si détenu par cette session."""

    if os.path.exists(LOCK_FILE):

        try:

            with open(LOCK_FILE, "r", encoding="utf-8") as f:

                data = json.load(f)

            if data.get("session_id") == my_session_id:

                os.remove(LOCK_FILE)

        except Exception:

            pass



def forcer_prise_de_main(my_session_id):

    """Force l'acquisition du verrou (si l'utilisateur précédent a quitté sans libérer)."""

    nouveau_lock = {

        "session_id": my_session_id,

        "dernier_acces": time.time(),

        "date": datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    }

    try:

        with open(LOCK_FILE, "w", encoding="utf-8") as f:

            json.dump(nouveau_lock, f, indent=4)

    except Exception:

        pass



def calculer_score_absent(moyenne_val):

    """

    Calcule le score de manche d'un joueur absent :

    moyenne * 24 / 3, arrondi à l'entier le plus proche, plafonné à 7 maximum.

    Prend en compte la saisie sous forme ratio (ex: 0.650) ou pourcentage (ex: 65).

    """

    if moyenne_val is None:

        return 0

    try:

        val = float(moyenne_val)

    except (ValueError, TypeError):

        return 0

    ratio = val / 100.0 if val > 1.0 else val

    pts = int(round((ratio * 24.0) / 3.0))

    return min(7, max(0, pts))



def restaurer_session(data):

    """Restaure l'intégralité de la session (équipes, sélections, présences, scores défaut et points) dans st.session_state."""

    if not data or not isinstance(data, dict):

        return False



    def safe_set(key, val):

        try:

            st.session_state[key] = val

        except Exception:

            pass



    # 1. Équipes

    if "choix_rec" in data:

        safe_set("sel_equipe_rec", data["choix_rec"])

    elif "receveur" in data:

        safe_set("sel_equipe_rec", data["receveur"])



    if "choix_vis" in data:

        safe_set("sel_equipe_vis", data["choix_vis"])

    elif "visiteur" in data:

        safe_set("sel_equipe_vis", data["visiteur"])



    if "input_custom_rec" in data:

        safe_set("input_custom_rec", data["input_custom_rec"])

    if "input_custom_vis" in data:

        safe_set("input_custom_vis", data["input_custom_vis"])



    # 2. Sélections Joueurs

    for k in ["sel_j1_rec", "sel_j2_rec", "sel_j3_rec", "sel_j1_vis", "sel_j2_vis", "sel_j3_vis"]:

        if k in data:

            safe_set(k, data[k])



    # 3. Données des joueurs (présence, score absent, nom remplaçant)

    joueurs = data.get("joueurs", {})

    for p_id in ["j1_rec", "j2_rec", "j3_rec", "j1_vis", "j2_vis", "j3_vis"]:

        if p_id in joueurs:

            p_data = joueurs[p_id]

            pres = p_data.get("present", True)

            pts = int(p_data.get("pts_absent", 0))

            moy = float(p_data.get("moyenne", 0.625))

            nom = p_data.get("nom", "")



            safe_set(f"pres_{p_id}", pres)

            safe_set(f"pts_{p_id}", pts)

            safe_set(f"moy_{p_id}", moy)

            safe_set(f"prev_state_{p_id}", pres)

            safe_set(f"prev_pts_{p_id}", pts)

            safe_set(f"cust_{p_id}", nom)



    # 4. Scores des 9 manches

    matchs = data.get("matchs", {})

    for num in range(1, 10):

        m = matchs.get(str(num), {})

        if "score_a" in m:

            safe_set(f"s_a_{num}", int(m["score_a"]))

        if "score_b" in m:

            safe_set(f"s_b_{num}", int(m["score_b"]))



    return True



