import csv

import unicodedata



def normaliser_nom_joueur(nom):

    """Normalise un nom pour recherche insensible à la casse, aux accents et à la ponctuation."""

    if not nom:

        return ""

    n = ''.join(c for c in unicodedata.normalize('NFD', nom) if unicodedata.category(c) != 'Mn').lower()

    return re.sub(r'[^a-z0-9]', '', n)



def inverser_nom_prenom_saphir(nom_brut):

    """Convertit 'Derasp, Sylvain' en 'Sylvain Derasp'."""

    if not nom_brut:

        return ""

    if "," in nom_brut:

        parts = nom_brut.split(",")

        return f"{parts[1].strip()} {parts[0].strip()}"

    return nom_brut.strip()



def sauvegarder_joueurs_stats_csv(joueurs_raw, equipes_raw, filepath=JOUEURS_CSV_FILE):

    """Sauvegarde la liste des joueurs extraite du site avec Points, Moyenne, Semaines, Rang et Équipe dans joueurs_stats.csv."""

    joueur_equipe_map = {}

    for eq in (equipes_raw or []):

        nom_e = eq.get("equipe", "")

        for p in eq.get("joueurs", []):

            joueur_equipe_map[normaliser_nom_joueur(p)] = nom_e



    lignes = []

    for j in (joueurs_raw or []):

        nom_aff = inverser_nom_prenom_saphir(j.get("nom", ""))

        pts_str = j.get("points", "").replace("*", "").strip()

        moy_str = j.get("moyenne", "0.625").strip()

        sem_str = j.get("semaines", "0").strip()

        rang_str = j.get("rang", "").strip()

        eq_str = joueur_equipe_map.get(normaliser_nom_joueur(nom_aff), "")

        lignes.append({

            "Nom": nom_aff,

            "Points": pts_str,

            "Moyenne": moy_str,

            "Semaines": sem_str,

            "Rang": rang_str,

            "Equipe": eq_str

        })



    try:

        with open(filepath, "w", encoding="utf-8", newline="") as f:

            writer = csv.DictWriter(f, fieldnames=["Nom", "Points", "Moyenne", "Semaines", "Rang", "Equipe"])

            writer.writeheader()

            writer.writerows(lignes)

        declencher_sync_github_arriere_plan(delai=1.0, commit_prefix=f"Sauvegarde joueurs_stats.csv ({len(lignes)} joueurs)", filepath=JOUEURS_CSV_FILE)

        return True

    except Exception:

        return False



@st.cache_data(ttl=300)

def charger_joueurs_stats_csv(filepath=JOUEURS_CSV_FILE):

    """Charge le dictionnaire des statistiques officielles des joueurs depuis joueurs_stats.csv."""

    stats = {}

    if os.path.exists(filepath):

        try:

            with open(filepath, "r", encoding="utf-8") as f:

                reader = csv.DictReader(f)

                for row in reader:

                    nom = row.get("Nom", "").strip()

                    try:

                        moy = float(row.get("Moyenne", "0.625"))

                    except Exception:

                        moy = 0.625

                    info = {

                        "nom": nom,

                        "points": row.get("Points", "0"),

                        "moyenne": moy,

                        "semaines": row.get("Semaines", "0"),

                        "rang": row.get("Rang", ""),

                        "equipe": row.get("Equipe", "")

                    }

                    stats[normaliser_nom_joueur(nom)] = info

                    if " " in nom:

                        parts = nom.split()

                        nom_inv = f"{parts[-1]} {' '.join(parts[:-1])}"

                        stats[normaliser_nom_joueur(nom_inv)] = info

        except Exception:

            pass

    return stats



def obtenir_moyenne_joueur(nom_joueur):

    """Retourne la moyenne officielle du joueur (extraite de saphirbillard.com / joueurs_stats.csv), ou 0.625 par défaut."""

    if not nom_joueur:

        return 0.625

    stats = charger_joueurs_stats_csv()

    cle = normaliser_nom_joueur(nom_joueur)

    if cle in stats:

        return float(stats[cle].get("moyenne", 0.625))

    return 0.625



def parser_ligne_horaire_match(cell_text):

    """Parse une cellule d'horaire comme '29 octobre Delta Hotel'."""

    mois_map = {

        'janvier': 1, 'fevrier': 2, 'mars': 3, 'avril': 4, 'mai': 5, 'juin': 6,

        'juillet': 7, 'aout': 8, 'septembre': 9, 'octobre': 10, 'novembre': 11, 'decembre': 12

    }

    m = re.search(r'(\d{1,2})\s+([a-zA-ZÀ-ſ�]+)\s+([a-zA-Z]+)\s+([a-zA-Z]+)', cell_text)

    if m:

        jour = int(m.group(1))

        mois_raw = ''.join(c for c in unicodedata.normalize('NFD', m.group(2)) if unicodedata.category(c) != 'Mn').lower().replace('�', 'e')

        mois_num = None

        for k, v in mois_map.items():

            if k in mois_raw or mois_raw in k:

                mois_num = v

                break

        return {

            "jour": jour,

            "mois": mois_num,

            "receveur": m.group(3).capitalize(),

            "visiteur": m.group(4).capitalize(),

            "texte": cell_text.strip()

        }

    return None



def obtenir_chemin_horaire_saison(num_saison=None):
    """Retourne le chemin du fichier horaire pour une saison donnée (ex: horaire_saison_1.json ou horaire_saphir.json)."""
    if num_saison is None:
        return HORAIRE_SAPHIR_FILE
    try:
        ns = int(num_saison)
        return get_data_path(f"horaire_saison_{ns}.json")
    except Exception:
        return HORAIRE_SAPHIR_FILE


def lister_horaires_saisons_disponibles():
    """Détecte et liste tous les fichiers d'horaires disponibles (horaire_saphir.json et horaire_saison_X.json).
    Retourne une liste de dicts triés par numéro de saison : [{'num': int, 'label': str, 'chemin': str, 'nb_semaines': int}].
    """
    res = []
    base_dirs = [BASE_DIR, os.getcwd()]
    vus = set()

    for b_dir in base_dirs:
        if not b_dir or not os.path.exists(b_dir):
            continue
        try:
            for nom_f in os.listdir(b_dir):
                if not nom_f.lower().startswith("horaire") or not nom_f.lower().endswith(".json"):
                    continue
                full_p = os.path.abspath(os.path.join(b_dir, nom_f))
                if full_p in vus:
                    continue
                vus.add(full_p)

                num_s = None
                m_s = re.search(r"saison[_-]?(\d+)", nom_f, re.IGNORECASE)
                if m_s:
                    num_s = int(m_s.group(1))

                # Charger un échantillon pour compter les semaines
                nb_sem = 0
                try:
                    with open(full_p, "r", encoding="utf-8") as f:
                        d = json.load(f)
                        if isinstance(d, list):
                            nb_sem = len(d)
                except Exception:
                    nb_sem = 0

                if num_s is not None:
                    lbl = f"Saison {num_s} ({nom_f}) — {nb_sem} semaine(s)"
                else:
                    num_s = 1
                    lbl = f"Horaire officiel ({nom_f}) — {nb_sem} semaine(s)"

                res.append({
                    "num": num_s,
                    "nom_fichier": nom_f,
                    "label": lbl,
                    "chemin": full_p,
                    "nb_semaines": nb_sem
                })
        except Exception:
            pass

    # Trier par numéro de saison
    res.sort(key=lambda x: (x["num"], x["nom_fichier"]))
    return res


def charger_horaire_json(num_saison=None):
    """Charge le calendrier des rencontres depuis le fichier local horaire_saphir.json ou horaire_saison_X.json
    (avec cache mémoire sur mtime). Au démarrage, charge la saison en cours si num_saison n'est pas spécifié.
    """
    fichier_cible = HORAIRE_SAPHIR_FILE
    if num_saison is not None:
        fichier_cible = obtenir_chemin_horaire_saison(num_saison)
    elif "saison_active_selectionnee" in st.session_state and st.session_state["saison_active_selectionnee"]:
        fichier_cible = obtenir_chemin_horaire_saison(st.session_state["saison_active_selectionnee"])

    # Si le fichier de saison spécifique n'existe pas encore mais que horaire_saphir.json existe, utiliser horaire_saphir.json
    if not os.path.exists(fichier_cible) and os.path.exists(HORAIRE_SAPHIR_FILE):
        fichier_cible = HORAIRE_SAPHIR_FILE

    cle_cache = f"horaire_json_{os.path.basename(fichier_cible)}"
    ok_c, val_c = _lire_cache_fichier(cle_cache, fichier_cible)
    if ok_c and val_c:
        return val_c

    if os.path.exists(fichier_cible):
        try:
            with open(fichier_cible, "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, list) and data:
                    _ecrire_cache_fichier(cle_cache, fichier_cible, data)
                    return data
        except Exception:
            pass

    return []


def sauvegarder_horaire_json(lignes_horaire, num_saison=None):
    """Enregistre le calendrier des rencontres dans horaire_saphir.json et horaire_saison_X.json, et synchronise sur GitHub."""
    if not lignes_horaire:
        return False

    if num_saison is None:
        try:
            cfg_s = charger_config_saison()
            d_deb_str = str(cfg_s.get("date_debut_saison", "") or "").strip()
            if d_deb_str:
                d_obj = datetime.strptime(d_deb_str, "%Y-%m-%d").date()
                num_saison, _ = calculer_numero_saison(d_obj)
            else:
                num_saison, _ = calculer_numero_saison(datetime.today().date())
        except Exception:
            num_saison = 1

    fichier_saison = obtenir_chemin_horaire_saison(num_saison)
    fichiers_a_ecrire = [HORAIRE_SAPHIR_FILE]
    if fichier_saison != HORAIRE_SAPHIR_FILE:
        fichiers_a_ecrire.append(fichier_saison)

    succes = True
    try:
        for f_p in fichiers_a_ecrire:
            with open(f_p, "w", encoding="utf-8") as f:
                json.dump(lignes_horaire, f, indent=2, ensure_ascii=False)
            cle_cache = f"horaire_json_{os.path.basename(f_p)}"
            _ecrire_cache_fichier(cle_cache, f_p, lignes_horaire)
            declencher_sync_github_arriere_plan(
                delai=1.0,
                commit_prefix=f"Sauvegarde {os.path.basename(f_p)} ({len(lignes_horaire)} rencontres - Saison {num_saison})",
                filepath=f_p
            )
        return True
    except Exception:
        return False



def deduire_date_debut_saison_depuis_horaire(lignes_horaire=None):
    """Déduit la date de début de la saison (Lundi de la Semaine 1) à partir de horaire_saphir.json."""
    if not lignes_horaire:
        lignes_horaire = charger_horaire_json()
    annee_courante = datetime.today().year
    for idx_r, row in enumerate(lignes_horaire or []):
        if not isinstance(row, list) or len(row) < 2:
            continue
        sem_txt = str(row[0]).strip()
        m_sem = re.search(r"(\d+)", sem_txt)
        num_sem = int(m_sem.group(1)) if m_sem else (idx_r + 1)
        for slot_idx, cell in enumerate(row[1:5]):
            res = parser_ligne_horaire_match(str(cell))
            if res and res.get("mois") and res.get("jour"):
                try:
                    d_match = date(annee_courante, int(res["mois"]), int(res["jour"]))
                    d_sem1 = d_match - timedelta(days=(num_sem - 1) * 7 + slot_idx)
                    return d_sem1
                except Exception:
                    pass
    if datetime.today().month >= 7:
        return date(annee_courante, 9, 7)
    return date(annee_courante, 1, 5)


def charger_config_saison():
    """Charge la configuration de début de saison (date de début, joueurs inscrits, équipes et contraintes)."""
    ok_c, val_c = _lire_cache_fichier("config_saison", CONFIG_SAISON_FILE)
    if ok_c and isinstance(val_c, dict) and val_c:
        return val_c

    cfg = {}
    if os.path.exists(CONFIG_SAISON_FILE):
        try:
            with open(CONFIG_SAISON_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, dict):
                    cfg = data
        except Exception:
            cfg = {}

    equipes_csv = charger_equipes_csv()
    d_def = deduire_date_debut_saison_depuis_horaire()
    if not cfg.get("date_debut_saison"):
        cfg["date_debut_saison"] = d_def.strftime("%Y-%m-%d")
    if not cfg.get("nb_semaines"):
        cfg["nb_semaines"] = 14

    # Synchroniser les joueurs inscrits avec equipes-saphir.csv tout en préservant les contraintes existantes
    joueurs_existants = {}
    for item_j in cfg.get("joueurs_inscrits", []):
        if isinstance(item_j, dict) and str(item_j.get("joueur", "")).strip():
            cle_j = str(item_j["joueur"]).strip().lower()
            joueurs_existants[cle_j] = item_j

    liste_joueurs_finale = []
    vus_j = set()
    for eq_nom, j_liste in (equipes_csv or {}).items():
        for j_nom in j_liste:
            j_clean = str(j_nom).strip()
            if not j_clean:
                continue
            cle_j = j_clean.lower()
            vus_j.add(cle_j)
            ex = joueurs_existants.get(cle_j, {})
            liste_joueurs_finale.append({
                "joueur": j_clean,
                "equipe": str(ex.get("equipe") or eq_nom).strip(),
                "lundi": bool(ex.get("lundi", True)),
                "mardi": bool(ex.get("mardi", True)),
                "mercredi": bool(ex.get("mercredi", True)),
                "jeudi": bool(ex.get("jeudi", True)),
                "contraintes": str(ex.get("contraintes", "") or "").strip(),
            })

    # Conserver aussi les joueurs inscrits supplémentaires non encore dans equipes_csv
    for cle_j, ex in joueurs_existants.items():
        if cle_j not in vus_j:
            liste_joueurs_finale.append({
                "joueur": str(ex.get("joueur", "")).strip(),
                "equipe": str(ex.get("equipe", "")).strip(),
                "lundi": bool(ex.get("lundi", True)),
                "mardi": bool(ex.get("mardi", True)),
                "mercredi": bool(ex.get("mercredi", True)),
                "jeudi": bool(ex.get("jeudi", True)),
                "contraintes": str(ex.get("contraintes", "") or "").strip(),
            })

    cfg["joueurs_inscrits"] = liste_joueurs_finale
    cfg["equipes"] = equipes_csv
    if os.path.exists(CONFIG_SAISON_FILE):
        _ecrire_cache_fichier("config_saison", CONFIG_SAISON_FILE, cfg)
    return cfg


def sauvegarder_config_saison(cfg):
    """Sauvegarde la configuration de saison dans config_saison.json et synchronise sur GitHub."""
    if not isinstance(cfg, dict):
        return False
    try:
        with open(CONFIG_SAISON_FILE, "w", encoding="utf-8") as f:
            json.dump(cfg, f, indent=2, ensure_ascii=False)
        _ecrire_cache_fichier("config_saison", CONFIG_SAISON_FILE, cfg)
        declencher_sync_github_arriere_plan(delai=1.0, commit_prefix="Sauvegarde config_saison.json", filepath=CONFIG_SAISON_FILE)
        return True
    except Exception:
        return False


def obtenir_jours_disponibles_equipes(equipes_dict, joueurs_inscrits):
    """Calcule pour chaque équipe les jours disponibles (0=Lundi, 1=Mardi, 2=Mercredi, 3=Jeudi) selon les contraintes de ses joueurs."""
    dispo_eq = {eq: {0, 1, 2, 3} for eq in (equipes_dict or {}).keys()}
    for j_info in (joueurs_inscrits or []):
        if not isinstance(j_info, dict):
            continue
        eq = str(j_info.get("equipe", "")).strip()
        if not eq:
            continue
        if eq not in dispo_eq:
            dispo_eq[eq] = {0, 1, 2, 3}
        note_c = str(j_info.get("contraintes", "") or "").lower()
        if not bool(j_info.get("lundi", True)) or "pas lundi" in note_c or "indispo lundi" in note_c or "sauf lundi" in note_c:
            dispo_eq[eq].discard(0)
        if not bool(j_info.get("mardi", True)) or "pas mardi" in note_c or "indispo mardi" in note_c or "sauf mardi" in note_c:
            dispo_eq[eq].discard(1)
        if not bool(j_info.get("mercredi", True)) or "pas mercredi" in note_c or "indispo mercredi" in note_c or "sauf mercredi" in note_c:
            dispo_eq[eq].discard(2)
        if not bool(j_info.get("jeudi", True)) or "pas jeudi" in note_c or "indispo jeudi" in note_c or "sauf jeudi" in note_c:
            dispo_eq[eq].discard(3)
    return dispo_eq


def calculer_absences_joueurs_pour_match(rec, vis, jour_semaine, joueurs_inscrits, equipes_dict):
    """Calcule le nombre de joueurs absents/indisponibles pour une rencontre donnée un jour précis (0=Lundi, 1=Mardi, 2=Mercredi, 3=Jeudi).
    Retourne (nb_absents_total, liste_noms_absents).
    """
    cles_jours = ["lundi", "mardi", "mercredi", "jeudi"]
    cle_j = cles_jours[jour_semaine] if 0 <= jour_semaine < 4 else "lundi"
    eq_match = {str(rec).strip(), str(vis).strip()}
    absents = []

    for j_info in (joueurs_inscrits or []):
        if not isinstance(j_info, dict):
            continue
        eq_j = str(j_info.get("equipe", "")).strip()
        if eq_j in eq_match:
            nom_j = str(j_info.get("joueur", "")).strip()
            note_c = str(j_info.get("contraintes", "") or "").lower()
            dispo = bool(j_info.get(cle_j, True))
            if f"pas {cle_j}" in note_c or f"indispo {cle_j}" in note_c or f"sauf {cle_j}" in note_c:
                dispo = False
            if not dispo:
                absents.append(f"{nom_j} ({eq_j})")

    return len(absents), absents


def recalculer_dates_horaire_depuis_debut(date_debut_saison, lignes_horaire=None, nb_semaines=14):
    """Recalcule toutes les dates de l'horaire à partir de la date de début de la saison (Semaine 1 = Lundi..Jeudi)."""
    if isinstance(date_debut_saison, str):
        try:
            date_debut_saison = datetime.strptime(date_debut_saison.strip(), "%Y-%m-%d").date()
        except Exception:
            date_debut_saison = deduire_date_debut_saison_depuis_horaire(lignes_horaire)
    elif isinstance(date_debut_saison, datetime):
        date_debut_saison = date_debut_saison.date()

    mois_fr_map = {
        1: "janvier", 2: "février", 3: "mars", 4: "avril", 5: "mai", 6: "juin",
        7: "juillet", 8: "août", 9: "septembre", 10: "octobre", 11: "novembre", 12: "décembre"
    }

    if not lignes_horaire:
        lignes_horaire = charger_horaire_json()

    # Indexer les lignes existantes par numéro de semaine
    par_semaine = {}
    for idx_r, row in enumerate(lignes_horaire or []):
        if not isinstance(row, list) or not row:
            continue
        m_sem = re.search(r"(\d+)", str(row[0]))
        num_s = int(m_sem.group(1)) if m_sem else (idx_r + 1)
        par_semaine[num_s] = list(row)

    total_sem = max(nb_semaines, max(par_semaine.keys()) if par_semaine else nb_semaines)
    nouvelles_lignes = []
    for num_s in range(1, total_sem + 1):
        row_orig = par_semaine.get(num_s, [f"Semaine {num_s}", "—", "—", "—", "—", "—", "—"])
        while len(row_orig) < 7:
            row_orig.append("—")
        nouv_row = [f"Semaine {num_s}"]
        for slot_idx in range(4):
            cell_orig = str(row_orig[slot_idx + 1] or "—").strip()
            d_slot = date_debut_saison + timedelta(days=(num_s - 1) * 7 + slot_idx)
            date_str_fr = f"{d_slot.day} {mois_fr_map.get(d_slot.month, 'janvier')}"
            parsed = parser_ligne_horaire_match(cell_orig)
            if parsed and parsed.get("receveur") and parsed.get("visiteur"):
                nouv_row.append(f"{date_str_fr} {parsed['receveur']} {parsed['visiteur']}")
            else:
                nouv_row.append(cell_orig if cell_orig else "—")
        nouv_row.append(str(row_orig[5] or "—"))
        nouv_row.append(str(row_orig[6] or "—"))
        nouvelles_lignes.append(nouv_row)
    return nouvelles_lignes


def generer_horaire_saison_selon_prerequis(date_debut_saison, equipes_dict, joueurs_inscrits, nb_semaines=14):
    """Génère un horaire complet en respectant la date de début et les équipes.
    Dans le cas d'un nombre impair d'équipes, génère un calendrier équilibré incluant
    des semaines vacantes (BYE) réparties de manière à ce que TOUTES les équipes
    jouent exactement le même nombre de matchs.
    En cas de conflits de calendrier, optimise l'affectation des soirs (Lundi à Jeudi)
    pour minimiser strictement le nombre total d'absences de joueurs.
    """
    if isinstance(date_debut_saison, str):
        try:
            date_debut_saison = datetime.strptime(date_debut_saison.strip(), "%Y-%m-%d").date()
        except Exception:
            date_debut_saison = datetime.today().date()
    elif isinstance(date_debut_saison, datetime):
        date_debut_saison = date_debut_saison.date()

    mois_fr_map = {
        1: "janvier", 2: "février", 3: "mars", 4: "avril", 5: "mai", 6: "juin",
        7: "juillet", 8: "août", 9: "septembre", 10: "octobre", 11: "novembre", 12: "décembre"
    }

    noms_equipes = [str(e).strip() for e in (equipes_dict or {}).keys() if str(e).strip()]
    if len(noms_equipes) < 2:
        noms_equipes = ["Alpha", "Bravo", "Charlie", "Delta", "Echo", "Foxtrot", "Golf", "Hotel"]

    est_nb_impair = (len(noms_equipes) % 2 == 1)
    n_eq_reel = len(noms_equipes)

    conflits = []

    # Si nombre impair d'équipes : calibrer le nombre de semaines pour compléter des cycles entiers
    # de sorte que chaque équipe reçoive exactement le même nombre de semaines vacantes et joue le même nombre de matchs.
    if est_nb_impair:
        if nb_semaines % n_eq_reel != 0:
            nb_cycles = max(1, round(nb_semaines / n_eq_reel))
            nb_semaines_ajuste = nb_cycles * n_eq_reel
            conflits.append(
                f"ℹ️ Saison à nombre impair d'équipes ({n_eq_reel}) : l'horaire a été calibré sur {nb_semaines_ajuste} semaines "
                f"({nb_cycles} cycles complets de {n_eq_reel} semaines) pour garantir que chaque équipe joue exactement "
                f"{nb_cycles * (n_eq_reel - 1)} matchs et bénéficie d'exactement {nb_cycles} semaine(s) vacante(s)."
            )
        else:
            nb_cycles = max(1, nb_semaines // n_eq_reel)
            nb_semaines_ajuste = nb_semaines
            conflits.append(
                f"ℹ️ Calendrier équilibré ({n_eq_reel} équipes, {nb_semaines_ajuste} semaines) : chaque équipe joue "
                f"exactement {nb_cycles * (n_eq_reel - 1)} matchs et bénéficie de {nb_cycles} semaine(s) vacante(s) équitablement réparties."
            )
    else:
        nb_semaines_ajuste = nb_semaines

    # Algorithme Round-Robin (méthode du cercle)
    eq_rr = list(noms_equipes)
    if est_nb_impair:
        eq_rr.append("BYE")
    n_eq = len(eq_rr)
    nb_rondes_cycle = max(1, n_eq - 1)

    rondes_base = []
    byes_base = []
    rotation = list(eq_rr)
    for r_idx in range(nb_rondes_cycle):
        matchs_ronde = []
        bye_team = None
        for i in range(n_eq // 2):
            e1 = rotation[i]
            e2 = rotation[n_eq - 1 - i]
            if e1 == "BYE":
                bye_team = e2
            elif e2 == "BYE":
                bye_team = e1
            else:
                if (r_idx + i) % 2 == 0:
                    matchs_ronde.append((e1, e2))
                else:
                    matchs_ronde.append((e2, e1))
        rondes_base.append(matchs_ronde)
        byes_base.append(bye_team)
        rotation = [rotation[0]] + [rotation[-1]] + rotation[1:-1]

    nouvelles_lignes = []
    jours_noms = ["Lundi", "Mardi", "Mercredi", "Jeudi"]
    import itertools

    for sem_idx in range(nb_semaines_ajuste):
        num_sem = sem_idx + 1
        cycle_num = sem_idx // nb_rondes_cycle
        ronde_base_idx = sem_idx % nb_rondes_cycle
        matchs_sem = []
        for rec, vis in rondes_base[ronde_base_idx]:
            if cycle_num % 2 == 1:
                matchs_sem.append((vis, rec))
            else:
                matchs_sem.append((rec, vis))

        bye_team_sem = byes_base[ronde_base_idx] if est_nb_impair else None
        nb_m = min(4, len(matchs_sem))

        # Évaluer toutes les permutations de créneaux (0..3) pour minimiser les absences
        meilleure_perm = None
        min_absences = 999999
        detail_meilleure_perm = []

        if nb_m > 0:
            for perm_slots in itertools.permutations(range(4), nb_m):
                total_abs_perm = 0
                detail_abs_perm = []
                for m_i in range(nb_m):
                    rec_m, vis_m = matchs_sem[m_i]
                    jour_slot = perm_slots[m_i]
                    nb_abs, liste_abs = calculer_absences_joueurs_pour_match(
                        rec_m, vis_m, jour_slot, joueurs_inscrits, equipes_dict
                    )
                    total_abs_perm += nb_abs
                    if nb_abs > 0:
                        detail_abs_perm.append(
                            f"Semaine {num_sem} ({jours_noms[jour_slot]}) : {rec_m} vs {vis_m} ({', '.join(liste_abs)})"
                        )

                if total_abs_perm < min_absences:
                    min_absences = total_abs_perm
                    meilleure_perm = perm_slots
                    detail_meilleure_perm = detail_abs_perm
                    if total_abs_perm == 0:
                        break

        slots_assignes = ["—", "—", "—", "—"]
        for m_i in range(nb_m):
            rec_m, vis_m = matchs_sem[m_i]
            jour_slot = meilleure_perm[m_i] if meilleure_perm else m_i
            d_match = date_debut_saison + timedelta(days=sem_idx * 7 + jour_slot)
            slots_assignes[jour_slot] = f"{d_match.day} {mois_fr_map.get(d_match.month, 'janvier')} {rec_m} {vis_m}"

        if detail_meilleure_perm:
            conflits.extend(detail_meilleure_perm)

        col_vacante = f"Semaine vacante : {bye_team_sem}" if bye_team_sem else "—"

        nouvelles_lignes.append([
            f"Semaine {num_sem}",
            slots_assignes[0],
            slots_assignes[1],
            slots_assignes[2],
            slots_assignes[3],
            col_vacante,
            "—",
        ])

    return nouvelles_lignes, conflits



def obtenir_date_debut_ligue():

    """Récupère la date de début de la ligue (Saison 1) depuis st.secrets ou l'environnement."""

    from collections.abc import Mapping

    val = None

    try:

        if hasattr(st, "secrets"):

            for sec_lig in ["ligue", "Ligue", "LIGUE", "league"]:

                if sec_lig in st.secrets:

                    sec_val = st.secrets[sec_lig]

                    if isinstance(sec_val, (dict, Mapping)) or hasattr(sec_val, "items"):

                        val = sec_val.get("date_debut") or sec_val.get("date_debut_saison_1")

                        if val:

                            break

            if not val and "date_debut_ligue" in st.secrets:

                val = st.secrets["date_debut_ligue"]

            if not val and "date_debut_saison_1" in st.secrets:

                val = st.secrets["date_debut_saison_1"]

            if not val and "date_debut" in st.secrets:

                val = st.secrets["date_debut"]

    except Exception:

        pass



    if not val and os.environ.get("DATE_DEBUT_LIGUE"):

        val = os.environ.get("DATE_DEBUT_LIGUE", "").strip()



    if val:

        try:

            return datetime.strptime(str(val).strip(), "%Y-%m-%d").date()

        except Exception:

            pass

    return None



def calculer_numero_saison(date_match, date_debut_saison_1=None):

    """Calcule le numéro et le type de saison (Hiver / Automne) à partir de la date d'un match.

    Chaque saison dure 14 semaines.

    Deux saisons par année :

      - Saison 1 : Hiver / Printemps (début d'année à mi-avril/mai)

      - Seconde saison : Fin été / début automne (septembre à mi-décembre).

    """

    if date_debut_saison_1 is None:

        date_debut_saison_1 = obtenir_date_debut_ligue()

        

    if isinstance(date_match, datetime):

        date_match = date_match.date()

    elif not isinstance(date_match, (date, datetime)):

        date_match = datetime.today().date()

        

    if not date_debut_saison_1:

        date_debut_saison_1 = date(2025, 1, 6)

        

    if isinstance(date_debut_saison_1, datetime):

        date_debut_saison_1 = date_debut_saison_1.date()

        

    if date_match < date_debut_saison_1:

        typ_init = "Hiver" if date_debut_saison_1.month < 7 else "Automne"

        return 1, typ_init

        

    y_deb = date_debut_saison_1.year

    y_m = date_match.year

    m_deb = date_debut_saison_1.month

    m_m = date_match.month

    

    est_saison1_automne = (m_deb >= 7)

    est_match_automne = (m_m >= 7)

    type_saison = "Automne" if est_match_automne else "Hiver"

    

    if est_saison1_automne:

        if est_match_automne:

            num = 2 * (y_m - y_deb) + 1

        else:

            num = 2 * (y_m - y_deb)

    else:

        if est_match_automne:

            num = 2 * (y_m - y_deb) + 2

        else:

            num = 2 * (y_m - y_deb) + 1

            

    return max(1, num), type_saison



def deduire_saison_match(m, date_debut_saison_1=None):
    """Détermine le numéro de saison d'un match de l'historique (champ 'saison' ou calcul à partir de date_match)."""
    if not isinstance(m, dict):
        return 1
    if m.get("saison") is not None:
        try:
            return int(m["saison"])
        except Exception:
            pass
    if m.get("numero_saison") is not None:
        try:
            return int(m["numero_saison"])
        except Exception:
            pass

    # Déduire à partir de la date du match
    d_raw = m.get("date_match") or m.get("date") or m.get("date_enregistrement") or ""
    d_obj = None
    if isinstance(d_raw, str):
        for fmt in ("%Y-%m-%d %H:%M", "%Y-%m-%d", "%d/%m/%Y à %H:%M", "%d/%m/%Y", "%Y/%m/%d"):
            try:
                d_obj = datetime.strptime(d_raw.strip(), fmt).date()
                break
            except Exception:
                pass
    elif isinstance(d_raw, (date, datetime)):
        d_obj = d_raw if isinstance(d_raw, date) else d_raw.date()

    if d_obj:
        num_s, _ = calculer_numero_saison(d_obj, date_debut_saison_1=date_debut_saison_1)
        return num_s
    return 1


def filtrer_matchs_par_saison(historique, num_saison=None):
    """Filtre une liste de matchs pour ne conserver que ceux de la saison spécifiée (par défaut la saison courante)."""
    if not historique:
        return []
    if num_saison is None:
        num_saison = st.session_state.get("saison_active_selectionnee", 1)
    try:
        ns_cible = int(num_saison)
    except Exception:
        ns_cible = 1

    filtres = []
    for m in historique:
        if isinstance(m, dict) and deduire_saison_match(m) == ns_cible:
            filtres.append(m)
    return filtres


def trouver_match_par_date(date_cible, lignes_horaire=None):
    """Recherche un match dans l'horaire officiel correspondant au jour et mois de date_cible.
    Retourne un dict avec receveur, visiteur, saison_int, semaine_int, texte ou None si aucun match.
    """

    if not lignes_horaire:

        lignes_horaire = charger_horaire_json()

    if isinstance(date_cible, datetime):

        date_cible = date_cible.date()

    elif not isinstance(date_cible, date):

        return None



    for row in (lignes_horaire or []):

        if not row:

            continue

        semaine_label = str(row[0]).strip() if len(row) > 0 else ""

        for cell in row[1:]:

            res = parser_ligne_horaire_match(cell)

            if res and res.get("jour") == date_cible.day and res.get("mois") == date_cible.month:

                m_sem = re.search(r'\d+', semaine_label)

                if m_sem:

                    no_semaine = int(m_sem.group())

                else:

                    no_semaine = calculer_semaine_saison(date_cible)

                

                no_saison, type_saison = calculer_numero_saison(date_cible)

                res["semaine_int"] = no_semaine

                res["semaine_str"] = semaine_label or f"Semaine {no_semaine}"

                res["saison_int"] = no_saison

                res["saison_type"] = type_saison

                res["date_match"] = date_cible

                return res

    return None



def trouver_date_match_dans_horaire(receveur, visiteur, date_ref=None, lignes_horaire=None):
    """Recherche dans horaire_saphir.json la date programmée (format dd/mm/YYYY) pour la rencontre receveur vs visiteur."""
    r_cible = str(receveur or "").strip().lower()
    v_cible = str(visiteur or "").strip().lower()
    if not r_cible or not v_cible:
        return None
    if not lignes_horaire:
        lignes_horaire = charger_horaire_json()
    if not lignes_horaire:
        return None
    if date_ref is None:
        date_ref = datetime.today().date()
    elif isinstance(date_ref, datetime):
        date_ref = date_ref.date()

    candidats = []
    for row in lignes_horaire:
        if not row or not isinstance(row, list):
            continue
        for cell in row[1:]:
            res = parser_ligne_horaire_match(str(cell))
            if res and res.get("mois") and res.get("jour"):
                r_h = str(res.get("receveur", "")).strip().lower()
                v_h = str(res.get("visiteur", "")).strip().lower()
                if r_h == r_cible and v_h == v_cible:
                    annee_m = date_ref.year
                    if date_ref.month >= 11 and res["mois"] <= 2:
                        annee_m = date_ref.year + 1
                    elif date_ref.month <= 2 and res["mois"] >= 11:
                        annee_m = date_ref.year - 1
                    try:
                        d_obj = date(annee_m, int(res["mois"]), int(res["jour"]))
                        candidats.append(d_obj)
                    except Exception:
                        pass
    if not candidats:
        return None
    candidats.sort(key=lambda d: abs((d - date_ref).days))
    return candidats[0].strftime("%d/%m/%Y")


def extraire_dates_match_historique(m):
    """Extrait (date_du_match, date_enregistrement) d'un dictionnaire de match de l'historique."""
    if not isinstance(m, dict):
        return ("Date inconnue", "Date inconnue")
    rec = m.get("receveur", m.get("equipe_receveur", ""))
    vis = m.get("visiteur", m.get("equipe_visiteur", ""))
    d_match = str(m.get("date_match") or m.get("date") or "").strip()
    d_enreg = str(m.get("date_enregistrement") or "").strip()
    d_horaire = trouver_date_match_dans_horaire(rec, vis)
    if not d_match:
        d_match = d_horaire or d_enreg or "Date inconnue"
    elif d_enreg and d_match == d_enreg and d_horaire:
        # Si les deux champs avaient la même valeur d'enregistrement mais qu'une date officielle d'horaire existe
        d_match = d_horaire
    if not d_enreg:
        d_enreg = d_match
    return (d_match, d_enreg)


def formater_libelle_dates_match(m, court=False):
    """Formate l'affichage combiné de la date du match et de la date d'enregistrement."""
    d_match, d_enreg = extraire_dates_match_historique(m)
    if court:
        if d_enreg and d_enreg != d_match:
            return f"Match du {d_match} (Enr. {d_enreg})"
        return f"Match du {d_match}"
    if d_enreg:
        return f"Match du {d_match} (Enregistré le {d_enreg})"
    return f"Match du {d_match}"



def calculer_semaine_saison(date_match, date_debut_saison_1=None):

    """Calcule le numéro de semaine (1 à 14) dans la saison active."""

    if isinstance(date_match, datetime):

        date_match = date_match.date()

    elif not isinstance(date_match, date):

        date_match = datetime.today().date()

    debut_saison = None
    try:
        cfg_s = charger_config_saison()
        d_str = str(cfg_s.get("date_debut_saison", "") or "").strip()
        if d_str:
            debut_saison = datetime.strptime(d_str, "%Y-%m-%d").date()
    except Exception:
        debut_saison = None

    if not debut_saison:
        if date_match.month >= 7:
            debut_saison = date(date_match.year, 9, 7)
        else:
            debut_saison = date(date_match.year, 1, 6)

    diff = (date_match - debut_saison).days

    if diff < 0:

        return 1

    return max(1, min(14, (diff // 7) + 1))



def determiner_match_du_jour(lignes_horaire=None, date_ref=None):

    """Identifie la rencontre officielle programmée pour la date du jour selon l'horaire de saphirbillard.com."""

    if not lignes_horaire:

        lignes_horaire = charger_horaire_json()

    if date_ref is None:

        date_ref = datetime.today()



    mois_fr = {1: "janvier", 2: "février", 3: "mars", 4: "avril", 5: "mai", 6: "juin",

               7: "juillet", 8: "août", 9: "septembre", 10: "octobre", 11: "novembre", 12: "décembre"}



    tous_matchs = []

    for row in (lignes_horaire or []):

        if not row:

            continue

        semaine_label = str(row[0]).strip() if (isinstance(row, list) and len(row) > 0 and "Semaine" in str(row[0])) else ""

        for cell in row[1:]:

            res = parser_ligne_horaire_match(cell)

            if res and res.get("mois"):

                res["semaine"] = semaine_label if semaine_label else f"Semaine {calculer_semaine_saison(res.get('date_match', date_ref))}"

                annee_m = date_ref.year

                if date_ref.month >= 11 and res["mois"] <= 2:

                    annee_m = date_ref.year + 1

                elif date_ref.month <= 2 and res["mois"] >= 11:

                    annee_m = date_ref.year - 1

                try:

                    res["date_match"] = date(annee_m, res["mois"], res["jour"])

                except Exception:

                    res["date_match"] = date_ref.date() if isinstance(date_ref, datetime) else date_ref

                num_s, typ_s = calculer_numero_saison(res["date_match"])

                res["saison"] = num_s

                res["saison_type"] = typ_s

                tous_matchs.append(res)



    def _formater_retour(m, est_ajd):

        return {

            "receveur": m["receveur"],

            "visiteur": m["visiteur"],

            "texte": m["texte"],

            "est_aujourdhui": est_ajd,

            "date_texte": f"{m['jour']} {mois_fr.get(m['mois'], '')}",

            "date_match": m.get("date_match"),

            "semaine": m.get("semaine", ""),

            "saison": m.get("saison", 1),

            "saison_type": m.get("saison_type", "")

        }



    # 1. Match exact de la date d'aujourd'hui

    for m in tous_matchs:

        if m["jour"] == date_ref.day and m["mois"] == date_ref.month:

            return _formater_retour(m, True)



    # 2. Sinon, le prochain match dans le calendrier

    prochains = [m for m in tous_matchs if (m["mois"] > date_ref.month) or (m["mois"] == date_ref.month and m["jour"] >= date_ref.day)]

    if prochains:

        return _formater_retour(prochains[0], False)

    elif tous_matchs:

        return _formater_retour(tous_matchs[-1], False)

    return None



def appliquer_match_du_jour(rencontre=None, forcer=False):

    """Configure automatiquement les équipes receveuse et visiteuse ainsi que leurs joueurs, moyennes et fichier de sauvegarde."""

