def charger_tournois_data():

    """Charge les données des tournois depuis le fichier JSON (avec cache mémoire et repli sur .bak si nécessaire)."""
    ok_c, val_c = _lire_cache_fichier("tournois_data", TOURNOIS_FILE)
    if ok_c and isinstance(val_c, dict):
        return val_c

    for chemin in [TOURNOIS_FILE, f"{TOURNOIS_FILE}.bak"]:

        if os.path.exists(chemin):

            try:

                with open(chemin, "r", encoding="utf-8") as f:

                    d = json.load(f)

                    if isinstance(d, dict):
                        if chemin == TOURNOIS_FILE:
                            _ecrire_cache_fichier("tournois_data", TOURNOIS_FILE, d)
                        return d

            except Exception:

                continue

    return {}



def _ecrire_json_atomique(filepath, payload):

    """Écrit un objet JSON sur le disque de manière atomique avec copie de secours .bak et mise à jour du cache mémoire."""

    if os.path.exists(filepath) and os.path.getsize(filepath) > 2:

        try:

            with open(filepath, "r", encoding="utf-8") as f_src:

                ancien = f_src.read()

            with open(f"{filepath}.bak", "w", encoding="utf-8") as f_bak:

                f_bak.write(ancien)

        except Exception:

            pass

    tmp_path = f"{filepath}.tmp"

    with open(tmp_path, "w", encoding="utf-8") as f_tmp:

        json.dump(payload, f_tmp, ensure_ascii=False, indent=4)

    try:

        os.replace(tmp_path, filepath)

    except Exception:

        with open(filepath, "w", encoding="utf-8") as f_direct:

            json.dump(payload, f_direct, ensure_ascii=False, indent=4)

        if os.path.exists(tmp_path):

            try:

                os.remove(tmp_path)

            except Exception:

                pass

    try:
        fp_abs = os.path.abspath(filepath)
        if fp_abs == os.path.abspath(TOURNOIS_FILE):
            _ecrire_cache_fichier("tournois_data", TOURNOIS_FILE, payload)
        elif fp_abs == os.path.abspath(HISTORIQUE_TOURNOIS_FILE):
            _ecrire_cache_fichier("historique_tournois", HISTORIQUE_TOURNOIS_FILE, payload)
    except Exception:
        pass



def sauvegarder_tournois_data(data, marqueur_session=None, action="sauvegarde", synchroniser_historique=True):

    """Enregistre les données des tournois dans tournois_data.json et synchronise automatiquement historique_tournois.json."""

    if not isinstance(data, dict):

        return False

    try:

        import copy

        now_str = datetime.now().strftime("%d/%m/%Y à %H:%M:%S")

        now_short = datetime.now().strftime("%d/%m/%Y à %H:%M")

        data["derniere_sauvegarde"] = {

            "date": now_str,

            "session_id": marqueur_session or "marqueur_actif",

            "action": action

        }



        # Toujours récupérer l'historique le plus récent sur disque pour éviter tout écrasement par une copie en mémoire obsolète

        hist_disque = []

        for ch_h in [HISTORIQUE_TOURNOIS_FILE, f"{HISTORIQUE_TOURNOIS_FILE}.bak"]:

            if os.path.exists(ch_h):

                try:

                    with open(ch_h, "r", encoding="utf-8") as f_h:

                        lu = json.load(f_h)

                        if isinstance(lu, list):

                            hist_disque = [h for h in lu if isinstance(h, dict) and not h.get("est_actif")]

                            break

                except Exception:

                    continue



        if not hist_disque and isinstance(data.get("historique"), list):

            hist_disque = [h for h in data["historique"] if isinstance(h, dict) and not h.get("est_actif")]

        # Si un mode est None dans data (inactif ou annulé), purger tout snapshot orphelin "en_cours" de ce mode dans l'historique
        for m_pur in ["simple", "double"]:
            if data.get(m_pur) is None:
                hist_disque = [
                    h for h in hist_disque
                    if not (isinstance(h, dict) and h.get("mode") == m_pur and h.get("statut") == "en_cours")
                ]

        for m in ["simple", "double"]:

            if m in data and isinstance(data[m], dict):

                t_obj = data[m]

                t_obj["mode"] = m

                t_obj["date_derniere_sauvegarde"] = now_str

                if not t_obj.get("id_archive"):

                    t_obj["id_archive"] = f"TOURNOI_{m.upper()}_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{random.randint(100, 999)}"

                if synchroniser_historique:

                    snap = copy.deepcopy(t_obj)

                    snap.pop("est_actif", None)

                    snap["mode"] = m

                    snap["date_archivage"] = now_short

                    id_a = snap["id_archive"]

                    idx_ex = -1

                    for i, h_it in enumerate(hist_disque):

                        if h_it.get("id_archive") == id_a or (

                            h_it.get("titre") == snap.get("titre") and

                            h_it.get("date_creation") == snap.get("date_creation") and

                            h_it.get("mode") == m

                        ):

                            idx_ex = i

                            break

                    if idx_ex >= 0:

                        hist_disque[idx_ex] = snap

                    else:

                        hist_disque.insert(0, snap)



        data["historique"] = hist_disque

        _ecrire_json_atomique(HISTORIQUE_TOURNOIS_FILE, hist_disque)

        _ecrire_json_atomique(TOURNOIS_FILE, data)

        fichiers_cibles = [TOURNOIS_FILE, HISTORIQUE_TOURNOIS_FILE] if synchroniser_historique else [TOURNOIS_FILE]
        actions_critiques = {"cession_de_main", "cloture_tournoi_termine", "annulation_complete", "finale_terminee"}
        a_tournoi_termine = any(
            isinstance(data.get(m_k), dict) and data[m_k].get("statut") == "termine"
            for m_k in ("simple", "double")
        )
        if action in actions_critiques or a_tournoi_termine:
            synchroniser_fichiers_cibles_cloud(fichiers_cibles, commit_prefix=f"Sauvegarde tournois ({action})")
        else:
            declencher_sync_github_arriere_plan(
                delai=1.5,
                commit_prefix=f"Sauvegarde tournois ({action})",
                filepaths=fichiers_cibles
            )

        return True

    except Exception as e:

        st.error(f"Erreur lors de l'enregistrement du tournoi : {e}")

        return False



def ceder_la_main_avec_sauvegarde(session_id):

    """

    Sauvegarde automatiquement le tournoi et le match en cours sur le disque avant de céder la main,

    puis libère le verrou exclusif.

    """

    now_str = datetime.now().strftime("%d/%m/%Y à %H:%M:%S")

    td = charger_tournois_data()

    tournois_sauvegardes = []

    for mode in ["simple", "double"]:

        t = td.get(mode)

        if t and isinstance(t, dict):

            t_nom = t.get("titre", f"Tournoi {mode}")

            t["date_derniere_sauvegarde"] = now_str

            tournois_sauvegardes.append(t_nom)



    sauvegarder_tournois_data(td, marqueur_session=session_id, action="cession_de_main")



    try:

        donnees_feuille = st.session_state.get("donnees_match_courant")

        if donnees_feuille and isinstance(donnees_feuille, dict):

            sauvegarder_donnees(donnees_feuille)

    except Exception:

        pass



    liberer_verrou(session_id)

    st.session_state["mode_consultation"] = True



    if tournois_sauvegardes:

        t_txt = ", ".join(tournois_sauvegardes)

        st.session_state["msg_cession_main"] = f"✅ La main a été cédée. La sauvegarde du tournoi ({t_txt}) a été enregistrée avec succès sur le disque ({now_str})."

    else:

        st.session_state["msg_cession_main"] = f"✅ La main a été cédée. Les données ont été sauvegardées avec succès ({now_str})."



def prendre_la_main_avec_rechargement(session_id):

    """

    Prend la main pour marquer un tournoi, charge fraîchement la dernière sauvegarde du tournoi

    depuis le disque et vérifie que la sauvegarde faite par le marqueur précédent est récupérée.

    """

    forcer_prise_de_main(session_id)

    st.session_state["mode_consultation"] = False



    td_fraiche = charger_tournois_data()

    infos_sauv = td_fraiche.get("derniere_sauvegarde", {})

    date_sauv_t = infos_sauv.get("date", "")

    action_sauv = infos_sauv.get("action", "")



    # Purge des clés de saisie en session pour que Streamlit prenne les valeurs du disque

    cles_a_purger = [k for k in list(st.session_state.keys()) if k.startswith("rr_a_") or k.startswith("rr_b_") or k.startswith("m_sc_a_") or k.startswith("m_sc_b_")]

    for k in cles_a_purger:

        del st.session_state[k]



    try:

        sauv_match = charger_sauvegarde()

        if sauv_match and "matchs" in sauv_match:

            restaurer_session(sauv_match)

    except Exception:

        pass



    if date_sauv_t:

        if action_sauv == "cession_de_main":

            st.session_state["msg_prise_main"] = (

                f"✅ Prise de main réussie ! La sauvegarde effectuée par le marqueur qui a cédé la main "

                f"({date_sauv_t}) a été chargée avec succès depuis le disque."

            )

        else:

            st.session_state["msg_prise_main"] = (

                f"✅ Prise de main réussie ! La dernière sauvegarde du tournoi sur le disque "

                f"({date_sauv_t}) a été chargée avec succès."

            )

    else:

        st.session_state["msg_prise_main"] = (

            "✅ Prise de main réussie ! Les données du tournoi enregistrées sur le disque ont été chargées avec succès."

        )



def charger_historique_tournois(inclure_actifs=False):

    """Charge l'ensemble des tournois archivés (Simples et Doubles).

    Si inclure_actifs est True, inclut et marque également les tournois actifs sauvegardés dans tournois_data.json."""

    import copy

    historique = []

    ok_c_ht, val_c_ht = _lire_cache_fichier("historique_tournois", HISTORIQUE_TOURNOIS_FILE)
    if ok_c_ht and isinstance(val_c_ht, list) and len(val_c_ht) > 0:
        historique = val_c_ht
    else:
        for ch_h in [HISTORIQUE_TOURNOIS_FILE, f"{HISTORIQUE_TOURNOIS_FILE}.bak"]:

            if os.path.exists(ch_h):

                try:

                    with open(ch_h, "r", encoding="utf-8") as f:

                        data = json.load(f)

                        if isinstance(data, list) and len(data) > 0:

                            historique = data
                            if ch_h == HISTORIQUE_TOURNOIS_FILE:
                                _ecrire_cache_fichier("historique_tournois", HISTORIQUE_TOURNOIS_FILE, data)

                            break

                except Exception:

                    continue



    if not historique:

        try:

            gh_t = telecharger_json_depuis_github("historique_tournois.json")

            if isinstance(gh_t, list) and len(gh_t) > 0:

                with open(HISTORIQUE_TOURNOIS_FILE, "w", encoding="utf-8") as f_wt:

                    json.dump(gh_t, f_wt, ensure_ascii=False, indent=4)

                historique = gh_t

        except Exception:

            pass



    td = charger_tournois_data()

    if isinstance(td, dict) and isinstance(td.get("historique"), list):

        if not historique:

            historique = copy.deepcopy(td["historique"])

        else:

            # Fusionner tout tournoi présent dans td["historique"] qui manquerait dans historique

            ids_connus = {str(h.get("id_archive")) for h in historique if isinstance(h, dict) and h.get("id_archive")}

            for h_td in td["historique"]:

                if isinstance(h_td, dict) and h_td.get("id_archive") and str(h_td.get("id_archive")) not in ids_connus:

                    historique.append(copy.deepcopy(h_td))

    # Nettoyer d'office tout indicateur est_actif résiduel dans l'historique archivé
    for h in historique:
        if isinstance(h, dict):
            h.pop("est_actif", None)

    if inclure_actifs and isinstance(td, dict):

        try:

            actifs = []

            for m in ["simple", "double"]:

                t_act = td.get(m)

                # Un tournoi est actif UNIQUEMENT si statut == "en_cours" ET a des tours ou matchs
                if t_act and isinstance(t_act, dict) and t_act.get("statut") in ("en_cours", "termine") and (t_act.get("tours") or t_act.get("matchs")):

                    id_a = str(t_act.get("id_archive", ""))

                    titre_a = t_act.get("titre")

                    date_c = t_act.get("date_creation")

                    deja_present = False

                    for idx_h, h in enumerate(historique):

                        if not isinstance(h, dict):
                            continue

                        h_id = str(h.get("id_archive", ""))

                        if (id_a and h_id == id_a) or (

                            h.get("titre") == titre_a and h.get("date_creation") == date_c and h.get("mode") == m

                        ):

                            t_cop = copy.deepcopy(t_act)

                            t_cop["mode"] = m

                            t_cop["est_actif"] = True

                            if id_a:

                                t_cop["id_archive"] = id_a

                            elif h.get("id_archive"):

                                t_cop["id_archive"] = h["id_archive"]

                            historique[idx_h] = t_cop

                            deja_present = True

                            break

                    if not deja_present:

                        t_cop = copy.deepcopy(t_act)

                        t_cop["mode"] = m

                        t_cop["est_actif"] = True

                        if not t_cop.get("id_archive"):

                            t_cop["id_archive"] = f"ACTIF_{m.upper()}"

                        actifs.append(t_cop)

            if actifs:

                return actifs + historique

        except Exception:

            pass



    return historique



def sauvegarder_historique_tournois(historique_list):

    """Sauvegarde l'historique des tournois dans historique_tournois.json et synchronise tournois_data.json."""

    try:

        import copy

        liste_a_sauver = []

        if isinstance(historique_list, list):

            for h in historique_list:

                if isinstance(h, dict):

                    h_clean = copy.deepcopy(h)

                    h_clean.pop("est_actif", None)

                    liste_a_sauver.append(h_clean)

        _ecrire_json_atomique(HISTORIQUE_TOURNOIS_FILE, liste_a_sauver)

        td = charger_tournois_data()

        td["historique"] = liste_a_sauver

        try:

            _ecrire_json_atomique(TOURNOIS_FILE, td)

        except Exception:

            pass

        synchroniser_fichiers_cibles_cloud(
            [HISTORIQUE_TOURNOIS_FILE, TOURNOIS_FILE],
            commit_prefix=f"Sauvegarde historique tournois ({len(liste_a_sauver)} tournois)"
        )

        return True

    except Exception as e:

        st.error(f"Erreur lors de la sauvegarde de l'historique des tournois : {e}")

        return False



def envoyer_courriel_arborescence_tournoi(tournoi_obj, mode="simple", destinataires_specifiques=None):

    """Envoie par courriel l'arborescence officielle d'un tournoi avec la page HTML A4 et l'historique_tournois.json en pièces jointes."""

    config_email = charger_config_email()

    destinataires = (destinataires_specifiques or config_email.get("destinataires", "")).strip()



    if not destinataires:

        return False, "Aucune adresse de destinataire spécifiée. Veuillez renseigner un courriel valide."



    if not config_email.get("smtp_serveur") or not config_email.get("smtp_expediteur"):

        return False, "Configuration SMTP incomplète (serveur ou expéditeur manquant dans l'onglet Administration)."



    if not tournoi_obj or not isinstance(tournoi_obj, dict):

        return False, "Données de tournoi introuvables."



    titre_t = tournoi_obj.get("titre", "Tournoi officiel")

    mode_label = "Simple (1 contre 1)" if mode == "simple" else "Double / Équipes (2 contre 2)"

    fmt = tournoi_obj.get("format", "elimination")

    if fmt == "double_elimination":

        fmt_label = "Double élimination (Winner & Loser Bracket — Seconde chance)"

    elif fmt == "elimination":

        fmt_label = "Élimination directe (Préliminaires 2 de 3 • Finale 3 de 5)"

    else:

        fmt_label = "Championnat Round-Robin (2 de 3)"



    statut_t = tournoi_obj.get("statut", "en_cours")

    champion = tournoi_obj.get("vainqueur_final") or tournoi_obj.get("champion") or ""

    finaliste = tournoi_obj.get("finaliste") or ""

    date_now_str = datetime.now().strftime("%d/%m/%Y à %H:%M")

    nb_participants = len(tournoi_obj.get("participants", []))

    nb_tables = tournoi_obj.get("nb_tables", 2)

    h_deb = tournoi_obj.get("heure_debut", "09:00")

