def actualiser_resultats_tournoi(notif_msg=None):

    """Actualise systématiquement l'ensemble des résultats du tournoi depuis le disque."""

    for k in list(st.session_state.keys()):

        if k.startswith("sc_a_") or k.startswith("sc_b_") or k.startswith("rr_a_") or k.startswith("rr_b_"):

            try:

                del st.session_state[k]

            except Exception:

                pass

    if os.path.exists(TOURNOIS_FILE):

        try:

            st.session_state["dernier_mtime_tournois_vu"] = os.path.getmtime(TOURNOIS_FILE)

        except Exception:

            pass

    msg = notif_msg if notif_msg else "🔄 Résultats du tournoi actualisés !"

    try:

        st.toast(msg, icon="🏆")

    except Exception:

        pass

    st.rerun()



def afficher_bandeau_verrou_tournoi():

    """Affiche le bandeau d'état du verrou exclusif et de gestion de prise/cession de main pour les tournois."""

    my_session_id = st.session_state.get("user_session_id", "")

    est_spectateur = st.session_state.get("est_spectateur", False) or not st.session_state.get("authentifie", False)



    if est_spectateur:

        est_editeur = False

        autre_editeur_actif = False

        temps_restant = 0

    else:

        veut_editer = not st.session_state.get("mode_consultation", False)

        est_editeur, temps_restant, autre_editeur_actif = gerer_verrou_session(my_session_id, veut_etre_editeur=veut_editer)



    if "msg_prise_main" in st.session_state:

        st.success(st.session_state.pop("msg_prise_main"))

    if "msg_cession_main" in st.session_state:

        st.info(st.session_state.pop("msg_cession_main"))



    td = charger_tournois_data()

    infos_sauv = td.get("derniere_sauvegarde", {})

    date_sauv = infos_sauv.get("date", "")

    action_sauv = infos_sauv.get("action", "")

    mention_sauv = f" • 💾 Dernière sauvegarde disque : {date_sauv}" if date_sauv else ""



    modes_actifs = [m for m in ["simple", "double"] if td.get(m) and isinstance(td.get(m), dict) and td.get(m).get("statut") in ("en_cours", "termine")]

    tournoi_actif = bool(modes_actifs)



    if est_editeur:

        col_lk1, col_lk2 = st.columns([3.2, 1.2])

        col_lk1.success(f"🟢 **Vous avez la main exclusive pour marquer et configurer le tournoi.**{mention_sauv}")

        with col_lk2:

            if st.button("🔓 Céder la main", key="btn_ceder_main_tournoi", use_container_width=True, help="Sauvegarde automatiquement le tournoi sur le disque et libère la main"):

                with st.spinner("Sauvegarde du tournoi et libération..."):

                    ceder_la_main_avec_sauvegarde(my_session_id)

                st.rerun()

    elif est_spectateur:

        col_lk1, col_lk2 = st.columns([3.2, 1.2] if not tournoi_actif else [1, 0.01])

        texte_spec = "👁️ **Mode spectateur (Lecture seule) :** Consultation en direct du tournoi actif." if tournoi_actif else "👁️ **Mode spectateur (Lecture seule) :** Consultation des tournois. La saisie des scores est réservée au marqueur."

        col_lk1.info(texte_spec)

        col_lk1.caption("🔄 *Veille automatique active : dès que le marqueur met à jour le tournoi, les résultats sont actualisés systématiquement.*")

        if not tournoi_actif:

            with col_lk2:

                if st.button("🔄 Actualiser", key="btn_refresh_t_spec", type="secondary", use_container_width=True, help="Recharge les derniers résultats et scores en direct du tournoi"):

                    actualiser_resultats_tournoi()

    else:

        col_lk1, col_lk2 = st.columns([3.0, 1.2])

        if autre_editeur_actif:

            mins = temps_restant // 60

            secs = temps_restant % 60

            col_lk1.warning(f"🔒 **Mode consultation (Lecture seule) :** Un autre marqueur a actuellement la main sur la saisie. Vos modifications sont verrouillées.{mention_sauv} *(Inactivité restante : {mins}m {secs:02d}s)*")

            col_lk1.caption("🔄 *Veille automatique active : dès que le marqueur met à jour le tournoi, les résultats sont actualisés systématiquement.*")

        else:

            col_lk1.info(f"🔒 **Mode consultation (Lecture seule) :** Vous consultez le tournoi.{mention_sauv}")



        with col_lk2:

            if st.button("⚡ Prendre la main", key="btn_prendre_main_tournoi", use_container_width=True, help="Prend le contrôle de la saisie, charge la dernière sauvegarde du tournoi et active l'édition"):

                with st.spinner("Prise de la main et chargement..."):

                    prendre_la_main_avec_rechargement(my_session_id)

                st.rerun()



    # Veille automatique réactive pour spectateurs et mode consultation

    if not est_editeur:

        @st.fragment(run_every="4s")

        def surveiller_maj_marqueur_tournoi():

            if os.path.exists(TOURNOIS_FILE):

                try:

                    mtime_actuel = os.path.getmtime(TOURNOIS_FILE)

                except Exception:

                    mtime_actuel = 0

                cle_vu = "dernier_mtime_tournois_vu"

                if cle_vu not in st.session_state:

                    st.session_state[cle_vu] = mtime_actuel

                elif mtime_actuel > st.session_state.get(cle_vu, 0):

                    st.session_state[cle_vu] = mtime_actuel

                    time.sleep(0.2)

                    actualiser_resultats_tournoi("🔔 Le marqueur a mis à jour le tournoi ! Actualisation systématique des résultats effectuée.")



        surveiller_maj_marqueur_tournoi()



    return est_editeur



def afficher_formulaire_creation_tournoi(mode="simple", key_suffix="", est_editeur=True):

    """

    Formulaire universel et réutilisable pour la création et la configuration

    d'un nouveau tournoi (en Simple ou en Double / Équipes).

    """

    libelle_mode = "Tournoi en Simple (1 contre 1)" if mode == "simple" else "Tournoi en Double / Équipes (2 contre 2)"

    tournois_data = charger_tournois_data()



    st.caption(f"Configurez les paramètres et inscrivez les participants pour lancer un nouveau {libelle_mode.lower()}.")

    with st.container(border=True):

        col_cfg1, col_cfg2 = st.columns([1.5, 1.5])

        with col_cfg1:

            titre_defaut = f"Tournoi {'Simple' if mode == 'simple' else 'Double'} — {datetime.now().strftime('%d/%m/%Y')}"

            titre_saisi = st.text_input("Nom du tournoi :", value=titre_defaut, key=f"tournoi_titre_{mode}{key_suffix}")

            type_format = st.radio(

                "Format de compétition :",

                [

                    "🏆 Élimination directe (Arbre de tournoi)",

                    "🛡️ Double élimination (Winner & Loser Bracket — Seconde chance)"

                ],

                key=f"tournoi_format_{mode}{key_suffix}"

            )

            is_double_elim_cfg = "Double élimination" in type_format



        with col_cfg2:

            st.markdown("**⚙️ Formule officielle des finales :**")

            if is_double_elim_cfg:

                col_f1, col_f2 = st.columns(2)

                with col_f1:

                    fmt_finale_w = st.selectbox(

                        "Finale Bracket Gagnants :",

                        ["2 de 3", "3 de 5"],

                        index=0,

                        key=f"tournoi_fin_w_{mode}{key_suffix}",

                        help="Format pour la finale du tableau des gagnants (Winner Bracket)"

                    )

                with col_f2:

                    fmt_finale_l = st.selectbox(

                        "Finale Seconde Chance :",

                        ["2 de 3", "3 de 5"],

                        index=0,

                        key=f"tournoi_fin_l_{mode}{key_suffix}",

                        help="Format pour la finale du tableau de seconde chance (Loser Bracket)"

                    )

                fmt_finale_gf = st.selectbox(

                    "Grande Finale Officielle :",

                    ["3 de 5", "2 de 3"],

                    index=0,

                    key=f"tournoi_fin_gf_{mode}{key_suffix}",

                    help="Format pour la Grande Finale (Gagnant Winner vs Gagnant Loser)"

                )

                st.caption(

                    f"ℹ️ *Préliminaires : 2 de 3 • Finales Winner/Loser : {fmt_finale_w} / {fmt_finale_l} • Grande Finale : {fmt_finale_gf}*"

                )

            else:

                fmt_finale_elim = st.selectbox(

                    "Grande Finale :",

                    ["3 de 5", "2 de 3"],

                    index=0,

                    key=f"tournoi_fin_elim_{mode}{key_suffix}",

                    help="Format pour la finale du tournoi"

                )

                st.caption(

                    f"ℹ️ *Préliminaires : 2 de 3 • Grande Finale : {fmt_finale_elim}*"

                )



        st.markdown("##### 📅 Organisation, Disponibilité des tables & Horaires (1 seule journée)")

        st.caption("ℹ️ *Une pause dîner est automatiquement intégrée de 12:00 à 13:00 : aucun match n'est cédulé durant cette période.*")

        col_hor1, col_hor2, col_hor3 = st.columns([1.5, 1.2, 1.3])

        with col_hor1:

            choix_tables = st.radio(

                "Tables de billard disponibles :",

                ["🎱 2 tables (Recommandé - 2 matchs en parallèle)", "🎱 1 table (Matchs en alternance)"],

                index=0,

                key=f"tournoi_tables_{mode}{key_suffix}",

                help="Si 2 tables sont disponibles, 2 matchs se jouent en simultané. Si 1 table, les matchs se déroulent en alternance."

            )

            nb_tables_saisi = 2 if "2 tables" in choix_tables else 1

        with col_hor2:

            heure_debut_str = st.selectbox(

                "Heure de début du tournoi :",

                ["09:00", "08:30", "09:30", "10:00", "13:00"],

                index=0,

                key=f"tournoi_h_deb_{mode}{key_suffix}",

                help="Les tournois se déroulent en une seule journée et débutent à 9h a.m."

            )

        with col_hor3:

            duree_min_saisie = st.selectbox(

                "Durée estimée par match :",

                [30, 25, 35, 40, 45],

                index=0,

                format_func=lambda x: f"{x} minutes",

                key=f"tournoi_duree_{mode}{key_suffix}",

                help="Durée estimée d'un match (30 minutes par défaut)."

            )



        st.divider()



        # Sélection des participants

        joueurs_disponibles = obtenir_tous_les_joueurs_tournoi()



        # Gestion des invités personnalisés

        key_invites = f"invites_tournoi_{mode}{key_suffix}"

        if key_invites not in st.session_state:

            st.session_state[key_invites] = []



        col_inv1, col_inv2 = st.columns([3, 1])

        with col_inv1:

            nouveau_joueur = st.text_input("Ajouter un joueur invité / remplaçant :", key=f"input_invite_{mode}{key_suffix}", placeholder="Ex: Jean Tremblay")

        with col_inv2:

            st.write("")

            if st.button("➕ Ajouter l'invité", key=f"btn_add_invite_{mode}{key_suffix}", use_container_width=True):

                if nouveau_joueur.strip():

                    nom_prop = nouveau_joueur.strip()

                    if nom_prop not in joueurs_disponibles and nom_prop not in st.session_state[key_invites]:

                        st.session_state[key_invites].append(nom_prop)

                        st.rerun()



        tous_candidats = sorted(list(set(joueurs_disponibles + st.session_state[key_invites])))



        participants_finaux = []



        if mode == "simple":

            st.markdown("##### 👤 Liste des joueurs inscrits")

            col_sel_btn1, col_sel_btn2 = st.columns([1.5, 3.5])

            with col_sel_btn1:

                if st.button("👥 Sélectionner tous les inscrits", key=f"btn_all_{mode}{key_suffix}", use_container_width=True):

                    st.session_state[f"sel_participants_{mode}{key_suffix}"] = tous_candidats

                    st.rerun()

            with col_sel_btn2:

                st.caption("ℹ️ Par défaut, **tous les joueurs réguliers inscrits** participent au tournoi.")



            selection_j = st.multiselect(

                "Joueurs participants au tournoi :",

                options=tous_candidats,

                default=st.session_state.get(f"sel_participants_{mode}{key_suffix}", tous_candidats),

                key=f"sel_participants_{mode}{key_suffix}",

                help="Tous les joueurs inscrits sont sélectionnés par défaut."

            )

            participants_finaux = selection_j

            st.caption(f"🎯 **{len(participants_finaux)} joueur(s) inscrit(s)** participant au tournoi.")



        else:

            # Mode DOUBLE : Sélection préalable des joueurs inscrits, puis constitution des duos

            st.markdown("##### 👤 Liste des joueurs inscrits au tournoi en double")

            col_sel_btn1, col_sel_btn2 = st.columns([1.5, 3.5])

            with col_sel_btn1:

                if st.button("👥 Sélectionner tous les inscrits", key=f"btn_all_{mode}{key_suffix}", use_container_width=True):

                    st.session_state[f"sel_participants_{mode}{key_suffix}"] = tous_candidats

                    st.rerun()

            with col_sel_btn2:

                st.caption("ℹ️ Par défaut, **tous les joueurs réguliers inscrits** participent. Retirez les absents si nécessaire.")



            selection_j_double = st.multiselect(

                "Joueurs participants au tournoi en double :",

                options=tous_candidats,

                default=st.session_state.get(f"sel_participants_{mode}{key_suffix}", tous_candidats),

                key=f"sel_participants_{mode}{key_suffix}",

                help="Tous les joueurs inscrits sont sélectionnés par défaut. Retirez les absents avant de constituer les duos."

            )

            candidats_double = [j for j in selection_j_double if j in tous_candidats]

            nb_inscrits_d = len(candidats_double)

            st.caption(f"🎯 **{nb_inscrits_d} joueur(s) inscrit(s)** participant au tournoi en double.")



            st.divider()



            # Sélection des duos de joueurs avec drop boxes

            st.markdown("##### 👥 Sélection des duos de joueurs inscrits (Drop boxes)")

            st.info(

                "⚖️ **Jumelage officiel selon le classement :** Les duos sont automatiquement équilibrés parmi les **joueurs inscrits sélectionnés** : "

                "le **1ᵉʳ** est jumelé au **dernier** (Duo #1), le **2ᵉ** avec l'**avant-dernier** (Duo #2), et ainsi de suite. "

                "Vous pouvez aussi utiliser le bouton de pige au hasard ou ajuster manuellement n'importe quel joueur ci-dessous."

            )



            if nb_inscrits_d < 4:

                st.warning(f"⚠️ Veuillez sélectionner au moins **4 joueurs inscrits** pour constituer des duos (actuellement : **{nb_inscrits_d} joueur(s)**).")

                participants_finaux = []

                doublons = set()

            else:

                max_possibles = nb_inscrits_d // 2

                standard_duos = [16, 14, 12, 11, 10, 9, 8, 7, 6, 5, 4, 3, 2]

                options_nb_duos = [d for d in standard_duos if d <= max_possibles]

                if max_possibles not in options_nb_duos and max_possibles >= 2:

                    options_nb_duos.append(max_possibles)

                    options_nb_duos = sorted(list(set(options_nb_duos)), reverse=True)

                if not options_nb_duos:

                    options_nb_duos = [max_possibles] if max_possibles >= 2 else [2]



                cur_nb_d = st.session_state.get(f"nb_duos_select_{mode}{key_suffix}")

                if cur_nb_d and cur_nb_d not in options_nb_duos:

                    st.session_state[f"nb_duos_select_{mode}{key_suffix}"] = options_nb_duos[0]



                col_nb_d1, col_nb_d2 = st.columns([1.3, 3])

                with col_nb_d1:

                    nb_duos_choisi = st.selectbox(

                        "Nombre de duos participant :",

                        options=options_nb_duos,

                        index=0,

                        key=f"nb_duos_select_{mode}{key_suffix}",

                        help=f"Nombre maximum possible de duos avec les {nb_inscrits_d} joueurs inscrits : {max_possibles} duos."

                    )

                with col_nb_d2:

                    col_btn_class, col_btn_pige, col_btn_reset = st.columns([1.5, 1.1, 1.0])

                    with col_btn_class:

                        st.write("")

                        if st.button("⚖️ Jumeler par classement", key=f"btn_jumelage_class_{mode}{key_suffix}", type="primary", use_container_width=True, help="Jumelle équitablement le 1er avec le dernier, le 2e avec l'avant-dernier parmi les joueurs inscrits (avec tirage au sort aléatoire pour les joueurs à égalité de rang et de points)"):

                            pool_class = obtenir_joueurs_tries_classement(candidats_double, tirage_au_sort_egalites=True)

                            nb_requis = nb_duos_choisi * 2

                            pool_j = pool_class[:nb_requis]

                            len_p = len(pool_j)

                            for d_idx in range(nb_duos_choisi):

                                if d_idx < len_p:

                                    st.session_state[f"duo_{d_idx}_j1_{mode}{key_suffix}"] = pool_j[d_idx]

                                if (len_p - 1 - d_idx) >= 0 and (len_p - 1 - d_idx) < len_p:

                                    st.session_state[f"duo_{d_idx}_j2_{mode}{key_suffix}"] = pool_j[len_p - 1 - d_idx]

                            st.session_state[f"msg_jumelage_{mode}{key_suffix}"] = "⚖️ Duos jumelés selon le classement officiel (avec tirage au sort des rangs à égalité de points) !"

                            st.rerun()



                    with col_btn_pige:

                        st.write("")

                        if st.button("🎲 Piger au hasard", key=f"btn_pige_drop_{mode}{key_suffix}", use_container_width=True, help="Remplit aléatoirement les drop boxes avec les joueurs inscrits"):

                            pool_pige = list(candidats_double)

                            random.shuffle(pool_pige)

                            for d_idx in range(nb_duos_choisi):

                                if len(pool_pige) >= 2:

                                    st.session_state[f"duo_{d_idx}_j1_{mode}{key_suffix}"] = pool_pige.pop(0)

                                    st.session_state[f"duo_{d_idx}_j2_{mode}{key_suffix}"] = pool_pige.pop(0)

                            st.rerun()



                    with col_btn_reset:

                        st.write("")

                        if st.button("🔄 Réinitialiser", key=f"btn_reset_duos_{mode}{key_suffix}", use_container_width=True, help="Restaure le jumelage équilibré officiel selon le classement"):

                            for d_idx in range(20):

                                st.session_state.pop(f"duo_{d_idx}_j1_{mode}{key_suffix}", None)

                                st.session_state.pop(f"duo_{d_idx}_j2_{mode}{key_suffix}", None)

                            st.rerun()



                st.markdown("###### 📋 Composition des duos (équilibrés selon le classement) :")



                msg_jum = st.session_state.pop(f"msg_jumelage_{mode}{key_suffix}", None)

                if msg_jum:

                    st.success(msg_jum)



                pool_class_def = obtenir_joueurs_tries_classement(candidats_double)

                nb_requis_def = nb_duos_choisi * 2

                pool_j_def = pool_class_def[:nb_requis_def] if len(pool_class_def) >= nb_requis_def else pool_class_def

                len_pool_def = len(pool_j_def)



                duos_selectionnes = []

                joueurs_dans_duos = []

                doublons = set()



                cols_duos = st.columns(2)

                for i in range(nb_duos_choisi):

                    with cols_duos[i % 2]:

                        with st.container(border=True):

                            st.markdown(f"**🎯 Duo #{i + 1}**")



                            if len_pool_def >= 2:

                                nom_def1 = pool_j_def[i] if i < len_pool_def else (candidats_double[0] if candidats_double else "")

                                nom_def2 = pool_j_def[len_pool_def - 1 - i] if (len_pool_def - 1 - i) >= 0 else (candidats_double[-1] if candidats_double else "")

                            else:

                                nom_def1 = candidats_double[0] if candidats_double else ""

                                nom_def2 = candidats_double[1] if len(candidats_double) > 1 else nom_def1



                            cur_j1 = st.session_state.get(f"duo_{i}_j1_{mode}{key_suffix}", nom_def1)

                            cur_j2 = st.session_state.get(f"duo_{i}_j2_{mode}{key_suffix}", nom_def2)

                            if cur_j1 not in candidats_double:

                                cur_j1 = nom_def1

                            if cur_j2 not in candidats_double:

                                cur_j2 = nom_def2



                            def_idx1 = candidats_double.index(cur_j1) if cur_j1 in candidats_double else 0

                            def_idx2 = candidats_double.index(cur_j2) if cur_j2 in candidats_double else 0



                            info_j1 = obtenir_info_classement_joueur(cur_j1)

                            info_j2 = obtenir_info_classement_joueur(cur_j2)



                            col_j1, col_j2 = st.columns(2)

                            with col_j1:

                                st.caption(f"Joueur 1 : **{info_j1}**")

                                j1 = st.selectbox(

                                    f"Joueur 1 (Duo {i+1}){key_suffix}",

                                    options=candidats_double,

                                    index=def_idx1,

                                    key=f"duo_{i}_j1_{mode}{key_suffix}",

                                    label_visibility="collapsed"

                                )

                            with col_j2:

                                st.caption(f"Joueur 2 : **{info_j2}**")

                                j2 = st.selectbox(

                                    f"Joueur 2 (Duo {i+1}){key_suffix}",

                                    options=candidats_double,

                                    index=def_idx2,

                                    key=f"duo_{i}_j2_{mode}{key_suffix}",

                                    label_visibility="collapsed"

                                )



                            if j1 == j2:

                                st.error(f"⚠️ Un joueur ne peut pas être jumelé avec lui-même ({j1}).")

                                doublons.add(j1)

                            if j1 in joueurs_dans_duos:

                                doublons.add(j1)

                            joueurs_dans_duos.append(j1)

                            if j2 in joueurs_dans_duos:

                                doublons.add(j2)

                            joueurs_dans_duos.append(j2)



                            moy_j1 = obtenir_moyenne_joueur(j1)

                            moy_j2 = obtenir_moyenne_joueur(j2)

                            moy_comb = (moy_j1 + moy_j2) / 2



                            duo_nom = f"{j1} & {j2}"

                            st.markdown(f"🤝 **Duo #{i+1} :** `{duo_nom}` &nbsp;•&nbsp; 📊 *Moyenne combinée :* **{moy_comb:.3f}**")

                            duos_selectionnes.append(duo_nom)



                participants_finaux = duos_selectionnes



                if doublons:

                    doublons_str = ", ".join(sorted(list(doublons)))

                    st.warning(f"⚠️ **Joueurs sélectionnés en double :** {doublons_str}. Chaque joueur ne doit figurer que dans un seul duo.")

                else:

                    st.success(f"🟢 **{len(participants_finaux)} duos constitués** avec succès ({len(set(joueurs_dans_duos))} joueurs distincts prêts pour le tournoi en double).")



        st.divider()



        nb_p = len(participants_finaux)

        is_double_elim = "Double élimination" in type_format

        is_simple_elim = "Élimination directe" in type_format

        is_elim = is_simple_elim or is_double_elim

        bloquer_lancement = bool(doublons) if (mode == "double" and 'doublons' in locals()) else False

        if not est_editeur:

            bloquer_lancement = True



        promus_selectionnes = []

        if nb_p < 2:

            bloquer_lancement = True

            st.info(f"ℹ️ Sélectionnez au moins 2 {'équipes' if mode == 'double' else 'joueurs'} pour configurer le tournoi.")

        elif is_double_elim and nb_p < 4:

            bloquer_lancement = True

            st.warning("⚠️ **Double élimination :** Un minimum de **4 participants** est requis pour déployer la formule avec tableau des gagnants et tableau de repêchage (seconde chance).")

        elif is_elim:

            nb_promus, nb_m_t1, nb_m_t2, b_pow = calculer_structure_arbre(nb_p)



            if nb_promus > 0:
                st.markdown(
                    f"<div class='saphir-light-card' style='background: #eef7ff; border: 1px solid #90caf9; border-radius: 8px; padding: 12px 16px; margin: 8px 0; color: #0f172a !important;'>"
                    f"<strong class='saphir-primary' style='color: #0b3c5d !important;'>🎟️ Équilibrage officiel de l'arbre ({nb_p} participants)</strong><br>"
                    f"<span style='font-size: 13px; color: #0f172a !important;'>"
                    f"Pour garantir un <strong style='color: #0f172a !important;'>nombre pair de matchs au second tour ({nb_m_t2} matchs)</strong>, "
                    f"<strong style='color: #0f172a !important;'>{nb_promus} participant{'s' if nb_promus > 1 else ''}</strong> {'bénéficient' if nb_promus > 1 else 'bénéficie'} "
                    f"d'un passe-droit et {'sont directement promus' if nb_promus > 1 else 'est directement promu'} au 2ᵉ tour. "
                    f"Les {nb_p - nb_promus} autres participants disputeront le 1ᵉʳ tour ({nb_m_t1} match{'s' if nb_m_t1 > 1 else ''})."
                    f"</span></div>",
                    unsafe_allow_html=True
                )



                key_promus = f"liste_promus_{mode}{key_suffix}"

                cnt_add_key = f"cnt_add_promu_{mode}{key_suffix}"

                cnt_del_key = f"cnt_del_promu_{mode}{key_suffix}"



                if cnt_add_key not in st.session_state:

                    st.session_state[cnt_add_key] = 0

                if cnt_del_key not in st.session_state:

                    st.session_state[cnt_del_key] = 0



                key_last_nb_promus = f"last_nb_promus_{mode}{key_suffix}"

                # Initialisation ou rééquilibrage automatique si le quota de promus change (ex. 24 joueurs -> 8 promus)

                if key_promus not in st.session_state or st.session_state.get(key_last_nb_promus) != nb_promus:

                    existants_valides = [p for p in st.session_state.get(key_promus, []) if p in participants_finaux]

                    if len(existants_valides) > nb_promus:

                        st.session_state[key_promus] = existants_valides[:nb_promus]

                    elif len(existants_valides) < nb_promus:

                        dispos = [p for p in participants_finaux if p not in existants_valides]

                        st.session_state[key_promus] = existants_valides + dispos[:(nb_promus - len(existants_valides))]

                    else:

                        st.session_state[key_promus] = existants_valides

                    st.session_state[key_last_nb_promus] = nb_promus

                else:

                    # Ne conserver que les participants encore présents dans la liste finale

                    st.session_state[key_promus] = [p for p in st.session_state[key_promus] if p in participants_finaux]



                candidats = [p for p in participants_finaux if p not in st.session_state[key_promus]]

                promus = list(st.session_state[key_promus])



                placeholder_add = "➕ Choisir un participant à promouvoir..."

                placeholder_del = "➖ Choisir un promu à replacer..."



                key_add = f"sel_add_{mode}{key_suffix}_{st.session_state[cnt_add_key]}"

                key_del = f"sel_del_{mode}{key_suffix}_{st.session_state[cnt_del_key]}"



                st.markdown(f"###### 🔄 Sélection et transfert des participants promus ({len(promus)} / {nb_promus}) :")

                col_p1, col_p2 = st.columns(2)

                with col_p1:

                    st.markdown(f"**📋 Participants à sélectionner ({len(candidats)}) :**")

                    choix_add = st.selectbox(

                        "Déplacer vers la liste des promus :",

                        options=[placeholder_add] + candidats,

                        index=0,

                        key=key_add,

                        label_visibility="collapsed",

                        help="Sélectionnez un participant dans cette liste pour le promouvoir au 2ᵉ tour (le déplace vers la liste des promus)."

                    )

                    if choix_add != placeholder_add:

                        if choix_add not in st.session_state[key_promus]:

                            st.session_state[key_promus].append(choix_add)

                        st.session_state[cnt_add_key] += 1

                        st.rerun()



                    if not candidats:

                        st.caption("ℹ️ Tous les participants sont actuellement promus.")



                with col_p2:

                    st.markdown(f"**🎟️ Participants promus au 2ᵉ tour ({len(promus)} / {nb_promus}) :**")

                    choix_del = st.selectbox(

                        "Replacer dans la liste à sélectionner :",

                        options=[placeholder_del] + promus,

                        index=0,

                        key=key_del,

                        label_visibility="collapsed",

                        help="Sélectionnez un promu dans cette liste pour le retirer et le replacer dans la liste à sélectionner."

                    )

                    if choix_del != placeholder_del:

                        if choix_del in st.session_state[key_promus]:

                            st.session_state[key_promus].remove(choix_del)

                        st.session_state[cnt_del_key] += 1

                        st.rerun()



                    if not promus:

                        st.caption("ℹ️ Aucun participant n'est encore promu.")



                col_b1, col_b2 = st.columns([1, 1])

                with col_b1:

                    if st.button("🎲 Tirage au sort des promus", key=f"btn_pige_promus_{mode}{key_suffix}", use_container_width=True, help="Tire au sort exactement le nombre requis de promus parmi les participants"):

                        st.session_state[key_promus] = random.sample(participants_finaux, min(nb_promus, len(participants_finaux)))

                        st.session_state[cnt_add_key] += 1

                        st.session_state[cnt_del_key] += 1

                        st.rerun()

                with col_b2:

                    if st.button("🔄 Réinitialiser la liste des promus", key=f"btn_reset_promus_{mode}{key_suffix}", use_container_width=True, help="Remet tous les promus dans la liste des participants à sélectionner"):

                        st.session_state[key_promus] = []

                        st.session_state[cnt_add_key] += 1

                        st.session_state[cnt_del_key] += 1

                        st.rerun()



                promus_selectionnes = list(st.session_state[key_promus])

                nb_actuel = len(promus_selectionnes)



                if nb_actuel == nb_promus:

                    p_pills = " • ".join([f"`🎟️ {p}`" for p in promus_selectionnes])

                    st.success(f"🟢 **Quota atteint ({nb_actuel}/{nb_promus}) :** {p_pills}")

                elif nb_actuel < nb_promus:

                    bloquer_lancement = True

                    p_pills = " • ".join([f"`🎟️ {p}`" for p in promus_selectionnes]) if promus_selectionnes else "*(aucun)*"

                    st.warning(f"⚠️ **Sélection incomplète :** Veuillez encore promouvoir **{nb_promus - nb_actuel} participant(s)** via la liste déroulante ci-dessus (actuellement {nb_actuel}/{nb_promus} promus : {p_pills}).")

                else:

                    bloquer_lancement = True

                    st.error(f"⚠️ **Trop de promus :** Veuillez replacer **{nb_actuel - nb_promus} participant(s)** dans la liste à sélectionner via la liste déroulante de droite ({nb_actuel}/{nb_promus}).")

            elif nb_p in (18, 20, 22, 24):

                g_t1 = nb_p // 2

                m_t2 = g_t1 - 8

                p_t2 = 16 - g_t1

                st.success(

                    f"🟢 **Équilibrage officiel ({nb_p} participants) :** "

                    f"**Tous les {nb_p} participants jouent au 1ᵉʳ tour ({g_t1} matchs)** ! "

                    f"Puis au **2ᵉ tour**, **{2 * m_t2} gagnants** disputent **{m_t2} match{'s' if m_t2 > 1 else ''} d'équilibrage** "

                    f"et **{p_t2} gagnants du 1ᵉʳ tour** bénéficient d'un passe-droit direct pour former les **Quarts de finale (8 joueurs / 4 matchs)**."

                )

            else:

                st.success(

                    f"🟢 **Effectif équilibré ({nb_p} participants) :** "

                    f"Aucun passe-droit requis. Tous les participants débuteront au 1ᵉʳ tour ({nb_m_t1} matchs) "

                    f"et le second tour comportera exactement **{nb_m_t2} matchs (nombre pair)**."

                )





        if not est_editeur:

            st.info("🔒 *Bouton de lancement désactivé en mode consultation (prenez la main ci-dessus pour lancer le tournoi).*")



        btn_lancer = st.button(

            "🚀 Lancer le tournoi et générer le tableau officiel",

            type="primary",

            use_container_width=True,

            disabled=bloquer_lancement,

            key=f"btn_lancer_{mode}{key_suffix}",

            help="Génère l'arbre officiel des rencontres avec promotion automatique pour assurer un nombre pair de matchs au 2e tour."

        )



        if btn_lancer and est_editeur:

            # Recharger systématiquement les données fraîches du disque pour ne jamais écraser l'autre mode actif
            td_current = charger_tournois_data()

            # Archivage automatique si un tournoi existait déjà dans ce mode
            if td_current.get(mode):

                sauvegarder_tournoi_dans_historique(mode, notifier_admin=True)

                td_current = charger_tournois_data()



            if is_double_elim:

                race_w = 3 if st.session_state.get(f"tournoi_fin_w_{mode}{key_suffix}", "2 de 3") == "3 de 5" else 2

                race_l = 3 if st.session_state.get(f"tournoi_fin_l_{mode}{key_suffix}", "2 de 3") == "3 de 5" else 2

                race_gf = 3 if st.session_state.get(f"tournoi_fin_gf_{mode}{key_suffix}", "3 de 5") == "3 de 5" else 2

                t_cree = generer_arbre_double_elimination(

                    participants_finaux,

                    race_prelim=2,

                    race_finale=race_gf,

                    race_finale_winner=race_w,

                    race_finale_loser=race_l,

                    race_grande_finale=race_gf,

                    titre=titre_saisi,

                    heure_debut=heure_debut_str,

                    duree_min=duree_min_saisie,

                    nb_tables=nb_tables_saisi,

                    passes_droits=(promus_selectionnes if (promus_selectionnes and len(promus_selectionnes) == nb_promus) else None)

                )

            else:

                race_elim = 3 if st.session_state.get(f"tournoi_fin_elim_{mode}{key_suffix}", "3 de 5") == "3 de 5" else 2

                t_cree = generer_arbre_elimination(

                    participants_finaux,

                    race_prelim=2,

                    race_finale=race_elim,

                    titre=titre_saisi,

                    heure_debut=heure_debut_str,

                    duree_min=duree_min_saisie,

                    nb_tables=nb_tables_saisi,

                    passes_droits=(promus_selectionnes if (promus_selectionnes and len(promus_selectionnes) == nb_promus) else None)

                )



            if t_cree:

                t_cree["id"] = t_cree.get("id") or f"tournoi_{mode}_{int(time.time())}"

                t_cree["mode"] = mode

                t_cree["sms_tournoi_actif"] = False

                t_cree["convocations_sms_envoyees"] = {}

                td_current[mode] = t_cree

                sauvegarder_tournois_data(td_current)

                st.session_state[f"ouvrir_arborescence_auto_{mode}"] = True

                promus_msg = t_cree.get("promus_second_tour", [])

                if promus_msg:

                    st.success(f"✅ Tournoi généré avec succès ! {len(promus_msg)} participant(s) promu(s) au 2ᵉ tour : {', '.join(promus_msg)}.")

                else:

                    st.success("✅ Tournoi officiel généré avec succès !")

                st.rerun()



def afficher_onglet_nouveau_tournoi():

    """Onglet dédié à la création d'un nouveau tournoi (Simple ou Double)."""

    my_session_id = st.session_state.get("user_session_id", "")

    est_spectateur = st.session_state.get("est_spectateur", False) or not st.session_state.get("authentifie", False)



    if est_spectateur:

        est_editeur = False

    else:

        veut_editer = not st.session_state.get("mode_consultation", False)

        est_editeur, _, _ = gerer_verrou_session(my_session_id, veut_etre_editeur=veut_editer)



    st.markdown("### ➕ Créer un nouveau tournoi officiel")

    st.caption("Configurez et lancez une nouvelle compétition officielle en Simple (1 vs 1) ou en Double / Équipes (2 vs 2).")



    if not est_editeur:

        with st.container(border=True):

            st.warning("🔒 **La création et la configuration des tournois officiels sont réservées au marqueur officiel avec la main active.**")

            col_lck1, col_lck2 = st.columns([2, 1])

            with col_lck1:

                st.info("Prenez la main ci-contre pour configurer les participants, les tables et lancer un nouveau tournoi.")

            with col_lck2:

                if not est_spectateur:

                    if st.button("⚡ Prendre la main pour créer un tournoi", key="btn_take_lock_new_t", type="primary", use_container_width=True):

                        with st.spinner("Prise de la main..."):

                            prendre_la_main_avec_rechargement(my_session_id)

                        st.rerun()

                else:

                    if st.button("🔑 Connexion éditeur / Marqueur", key="btn_login_ed_new_t", type="primary", use_container_width=True):

                        st.session_state["est_spectateur"] = False

                        st.session_state["authentifie"] = False

                        st.rerun()



    recup_nouveau_onglet = obtenir_tournois_recuperables(mode=None)
    if recup_nouveau_onglet:
        with st.container(border=True):
            st.markdown("#### ⚡ Tournoi(s) en cours disponible(s) à la reprise")
            st.caption("Un ou plusieurs tournois non terminés ont été sauvegardés. Vous pouvez reprendre immédiatement l'un de ces tournois plutôt que d'en recréer un nouveau :")
            for t_r in recup_nouveau_onglet:
                t_id = t_r.get("id_archive")
                titre_r = t_r.get("titre", "Tournoi")
                m_r = t_r.get("mode", "simple")
                prog_r = calculer_progression_tournoi(t_r)
                c_rc1, c_rc2 = st.columns([3, 1.2])
                with c_rc1:
                    badge_m = "👤 Simple" if m_r == "simple" else "👥 Double"
                    st.write(f"**{titre_r}** — `{badge_m}` • *{t_r.get('date_creation', '')}*")
                    st.caption(f"Avancement : **{prog_r}** • Format : {t_r.get('format', 'elimination')}")
                with c_rc2:
                    if st.button("⚡ Reprendre ce tournoi", key=f"btn_recup_newtab_{t_id}", type="primary", use_container_width=True):
                        recuperer_tournoi_en_cours(t_id, mode_cible=m_r)

    choix_type = st.radio(

        "Type de tournoi à organiser :",

        ["👤 Tournoi en Simple (1 contre 1 - Joueurs individuels)", "👥 Tournoi en Double / Équipes (2 contre 2 - Duos)"],

        horizontal=True,

        key="rad_choix_type_nouveau_tournoi"

    )



    mode_choisi = "simple" if "Simple" in choix_type else "double"



    td = charger_tournois_data()

    t_existant = td.get(mode_choisi)

    if t_existant and isinstance(t_existant, dict):

        titre_ex = t_existant.get("titre", "Tournoi en cours")

        statut_ex = t_existant.get("statut", "en_cours")

        st.warning(

            f"ℹ️ **Un tournoi {mode_choisi.capitalize()} est actuellement enregistré :** « **{titre_ex}** » ({'🟢 En cours' if statut_ex == 'en_cours' else '🏆 Terminé'}).\n\n"

            f"En lançant un nouveau tournoi, le tournoi actuel sera **automatiquement archivé dans l'historique officiel** pour conserver l'ensemble de ses données et résultats."

        )



    afficher_formulaire_creation_tournoi(mode=mode_choisi, key_suffix="_tab_creer", est_editeur=est_editeur)





def afficher_deroulement_matchs_tournoi(tournoi, mode="simple", est_editeur=True, key_prefix=""):
    """Affiche l'ensemble des rencontres, la saisie des scores et les classements pour un tournoi (Simple ou Double)."""
    if not tournoi or not isinstance(tournoi, dict):
        return

    format_type = tournoi.get("format", "elimination")
    statut = tournoi.get("statut", "en_cours")
    race_to = tournoi.get("race_to", 2)
    tournois_data = charger_tournois_data()

# DÉROULEMENT SELON LE FORMAT

    if format_type in ["elimination", "double_elimination"]:
        st.markdown("""<style>
div[data-testid="stSelectbox"] div[data-baseweb="select"] {
    font-weight: 800 !important;
}
div[data-testid="stSelectbox"] div[data-baseweb="select"] * {
    font-size: 15px !important;
    font-weight: 800 !important;
}
</style>""", unsafe_allow_html=True)

        st.markdown("##### 🎯 Saisie des scores & Déroulement des rencontres")

        if tournoi.get("promus_second_tour"):

            promus_str_view = ", ".join(tournoi["promus_second_tour"])

            st.info(f"🎟️ **Participants promus d'office (Passe-droit) :** {promus_str_view}")



        def afficher_carte_rencontre(m, tour_courant, tour_num, tour_race, tour_fmt):

            m_id = m["id"]

            ea = m["equipe_a"]

            eb = m["equipe_b"]

            termine = m.get("termine", False)

            vainq = m.get("vainqueur")

            sa = m.get("score_a", 0)

            sb = m.get("score_b", 0)

            m_race = m.get("race_to", tour_race)

            m_fmt = m.get("format_label", tour_fmt)

            b_type = m.get("bracket", tour_courant.get("bracket", "winner"))



            if b_type == "loser":

                badge_b = "<span style='background:#fff3e0; color:#e65100; border:1px solid #ffb74d; padding:2px 7px; border-radius:8px; font-size:11px; font-weight:700;'>🟧 Seconde Chance</span>"

            elif b_type == "finale":

                badge_b = "<span style='background:#fff8e1; color:#b45309; border:1px solid #f59e0b; padding:2px 7px; border-radius:8px; font-size:11px; font-weight:700;'>🏆 Grande Finale</span>"

            elif format_type == "double_elimination":

                badge_b = "<span style='background:#e0f2fe; color:#0369a1; border:1px solid #7dd3fc; padding:2px 7px; border-radius:8px; font-size:11px; font-weight:700;'>🟦 Gagnants</span>"

            else:

                badge_b = ""



            m_h = m.get("heure_estimee", "")

            m_tbl = m.get("table", "Table 1")

            badge_horaire = f"<span style='background:#e8f0fe; color:#0b3c5d; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:600;'>⏰ {m_h} • {m_tbl}</span>" if (m_h and m_h != "—") else ""



            with st.container(border=True):

                col_m1, col_m2 = st.columns([1.15, 1.05])

                with col_m1:

                    if termine:

                        st.markdown(f"{badge_b} **{m_id}** : **{ea}** ({sa}) vs ({sb}) **{eb}**", unsafe_allow_html=True)

                        if m.get("passe_droit"):

                            st.success(f"🎟️ **Passe-droit accordé :** {vainq} est promu au tour suivant !")

                        else:

                            st.success(f"🏆 **Qualifié :** {vainq} *(score final {sa}-{sb})*")

                    else:

                        if ea == "À déterminer" or eb == "À déterminer":

                            st.markdown(f"{badge_b} **{m_id}** : `{ea}` vs `{eb}`", unsafe_allow_html=True)

                            st.caption("⏳ En attente des vainqueurs / perdants des tours précédents...")

                        else:

                            st.markdown(f"{badge_b} **{m_id}** : 🎯 **{ea}** vs **{eb}**", unsafe_allow_html=True)

                            st.caption(f"Format officiel : **{m_fmt}** (premier à {m_race} victoires)")



                    if est_editeur:

                        btn_lbl_h = f"🕒 Horaire ({m_h} • {m_tbl})" if (m_h and m_h != "—") else "🕒 Définir l'horaire"

                        with st.popover(btn_lbl_h, use_container_width=False, help="Changer l'heure programmée pour ce match et mettre à jour le tableau"):

                            st.markdown(f"###### ⏰ Horaire du match **{m_id}**")

                            st.caption(f"Rencontre : **{ea}** vs **{eb}**")

                            t_actuel = parse_heure_str_vers_time(m_h)

                            col_pop_h1, col_pop_h2 = st.columns(2)

                            with col_pop_h1:

                                nouv_t = st.time_input("Nouvelle heure :", value=t_actuel, key=f"t_in_{key_prefix}{mode}_{m_id}", step=300)

                            with col_pop_h2:

                                opts_tables = ["Table 1", "Table 2", "Table 3", "Table 4", "Table finale"]

                                cur_tbl = m.get("table", "Table 1")

                                idx_t = opts_tables.index(cur_tbl) if cur_tbl in opts_tables else 0

                                nouv_tbl = st.selectbox("Table :", options=opts_tables, index=idx_t, key=f"tbl_sel_{key_prefix}{mode}_{m_id}")



                            decaler_suivants = st.checkbox("Décaler aussi les matchs suivants de ce décalage", value=False, key=f"chk_shift_{key_prefix}{mode}_{m_id}", help="Si coché, ajuste automatiquement l'horaire des matchs ultérieurs non terminés")



                            if st.button("💾 Mettre à jour le tableau", type="primary", use_container_width=True, key=f"btn_save_hr_{key_prefix}{mode}_{m_id}"):
                                str_h = nouv_t.strftime("%Hh%M")
                                old_h_prec = m.get("heure_estimee", "")
                                old_tbl_prec = m.get("table", "")

                                matchs_decales = []
                                if decaler_suivants and m_h and m_h != "—":
                                    old_t = parse_heure_str_vers_time(m_h)
                                    diff_min = (nouv_t.hour * 60 + nouv_t.minute) - (old_t.hour * 60 + old_t.minute)
                                    if diff_min != 0:
                                        matchs_decales = decaler_horaires_matchs_suivants(tournoi, m_id, diff_min)

                                m["heure_estimee"] = str_h
                                m["table"] = nouv_tbl
                                m["table_courte"] = "T" + nouv_tbl.split(" ")[-1] if " " in nouv_tbl else nouv_tbl[:2].upper()
                                recalculer_heure_fin_tournoi(tournoi)

                                msg_sms_extra = ""
                                if str_h != old_h_prec or nouv_tbl != old_tbl_prec:
                                    nb_av, list_av = envoyer_convocations_changement_heure_match(
                                        tournoi, m, str_h, nouv_tbl, matchs_suivants_decales=matchs_decales
                                    )
                                    if nb_av > 0:
                                        msg_sms_extra = f" et {nb_av} convocation(s) SMS envoyée(s) 📲 !"
                                        st.session_state[f"msg_act_sms_{mode}"] = f"🔔 Convocations SMS envoyées suite au changement d'horaire ({', '.join(list_av)}) !"

                                sauvegarder_tournois_data(tournois_data)
                                st.success(f"✅ Heure du match {m_id} mise à jour à {str_h} ({nouv_tbl}){msg_sms_extra} et tableau actualisé !")
                                time.sleep(0.5)
                                st.rerun()



                with col_m2:

                    if not termine:

                        if est_editeur:

                            ronde_prete, msg_r_lock, _ = verifier_ronde_precedente_terminee(tournoi, tour_courant, tour_num, m_id)

                            if not ronde_prete:
                                st.info(f"🔒 **Saisie verrouillée :** {msg_r_lock}")

                            col_s1, col_s2, col_s_btns = st.columns([1.1, 1.1, 1.3])

                            options_sc_m = list(range(int(m_race) + 1))

                            key_sc_a = f"sc_a_{key_prefix}{mode}_{m_id}"

                            key_sc_b = f"sc_b_{key_prefix}{mode}_{m_id}"

                            if key_sc_a not in st.session_state or st.session_state[key_sc_a] not in options_sc_m:

                                st.session_state[key_sc_a] = 0

                            if key_sc_b not in st.session_state or st.session_state[key_sc_b] not in options_sc_m:

                                st.session_state[key_sc_b] = 0

                            idx_sc_a = options_sc_m.index(st.session_state[key_sc_a])

                            idx_sc_b = options_sc_m.index(st.session_state[key_sc_b])

                            with col_s1:

                                sc_a_in = int(st.selectbox(

                                    f"🎱 {formater_nom_abrege_joueur(ea)}",

                                    options=options_sc_m,

                                    index=idx_sc_a,

                                    key=key_sc_a,

                                    format_func=lambda x: f"Score : {x}",

                                    help=f"Score de {ea} (0 à {m_race})",

                                    disabled=not ronde_prete

                                ))

                            with col_s2:

                                sc_b_in = int(st.selectbox(

                                    f"🎱 {formater_nom_abrege_joueur(eb)}",

                                    options=options_sc_m,

                                    index=idx_sc_b,

                                    key=key_sc_b,

                                    format_func=lambda x: f"Score : {x}",

                                    help=f"Score de {eb} (0 à {m_race})",

                                    disabled=not ronde_prete

                                ))

                            with col_s_btns:

                                st.write("")

                                peut_valider = (ea != "À déterminer" and eb != "À déterminer" and ronde_prete)

                                if st.button("✅ Valider", key=f"btn_v_{key_prefix}{mode}_{m_id}", type="primary", use_container_width=True, disabled=not peut_valider):

                                    if sc_a_in == sc_b_in:

                                        st.error("Match nul impossible.")

                                    elif sc_a_in < m_race and sc_b_in < m_race:

                                        st.warning(f"Un joueur/duo doit remporter {m_race} manches ({m_fmt}).")

                                    else:

                                        est_match_finale = (tour_num == tournoi.get("total_tours")) or (m_id == "GF_M1")

                                        actualiser_score_elimination(tournoi, tour_num, m_id, sc_a_in, sc_b_in)

                                        td_fresh = charger_tournois_data()

                                        if not key_prefix or (td_fresh.get(mode) and td_fresh[mode].get("id_archive") == tournoi.get("id_archive")):
                                            td_fresh[mode] = tournoi
                                            act_sv = "finale_terminee" if (est_match_finale or tournoi.get("statut") == "termine") else "sauvegarde"
                                            sauvegarder_tournois_data(td_fresh, action=act_sv)
                                        else:
                                            archiver_tournoi(tournoi, mode=mode, notifier_admin=est_match_finale)

                                        if est_match_finale or tournoi.get("statut") == "termine":
                                            st.session_state[f"msg_finale_{mode}"] = f"🏆 Finale validée ! Félicitations à {tournoi.get('vainqueur_final', 'Vainqueur')} pour sa victoire. Le tournoi a été automatiquement sauvegardé et la notification officielle a été transmise par courriel aux administrateurs."

                                        st.rerun()



                                candidats_pd = [p for p in [ea, eb] if p and p not in ["À déterminer", "Exempt (Passe-droit)"]]

                                # Dans le tableau des perdants (Loser Bracket) ou la Grande Finale d'un tournoi à double élimination,

                                # chaque joueur ou duo doit obligatoirement jouer son match (aucun passe-droit autorisé).

                                autoriser_pd_match = not (format_type == "double_elimination" and b_type in ("loser", "finale")) and ronde_prete

                                if candidats_pd and autoriser_pd_match:

                                    with st.popover("🎟️ Promotion", use_container_width=True, help="Promouvoir directement un participant au tour suivant (Passe-droit)"):

                                        st.markdown(f"##### 🎟️ Accorder une promotion")

                                        st.caption(f"Promouvoir au tour suivant pour la rencontre **{m_id}** :")

                                        choix_promo = st.radio(

                                            "Bénéficiaire de la promotion :",

                                            options=candidats_pd,

                                            format_func=lambda x: f"🚀 {x}",

                                            key=f"rad_pd_{key_prefix}{mode}_{m_id}"

                                        )

                                        if st.button("🚀 Promouvoir au tour suivant", type="primary", use_container_width=True, key=f"btn_apply_pd_{key_prefix}{mode}_{m_id}"):

                                            attribuer_passe_droit_elimination(tournoi, tour_num, m_id, choix_promo)

                                            td_fresh = charger_tournois_data()

                                            td_fresh[mode] = tournoi

                                            sauvegarder_tournois_data(td_fresh)

                                            st.success(f"🎟️ Passe-droit accordé ! {choix_promo} est promu au tour suivant.")

                                            st.rerun()

                        else:

                            st.caption("⏳ *Rencontre en attente de score (saisie réservée au marqueur)*")
                    else:
                        if est_editeur:
                            with st.popover("✏️ Reprendre / Corriger", use_container_width=True, help="Corriger le score ou reprendre la validation de ce match"):
                                st.markdown(f"###### ✏️ Correction du match **{m_id}**")
                                st.caption(f"Rencontre : **{ea}** vs **{eb}**")
                                if m.get("passe_droit"):
                                    st.info(f"🎟️ Validé par Passe-droit en faveur de **{vainq}**")
                                else:
                                    st.caption(f"Score enregistré : **{ea}** {sa} - {sb} **{eb}** (Vainqueur : **{vainq}**)")
                                
                                desc_termines = [d[0] for d in obtenir_matchs_descendants_termines(tournoi, m_id)]
                                chk_force = False
                                if desc_termines:
                                    ids_suiv = ", ".join([d.get("id", "") for d in desc_termines])
                                    st.warning(f"⚠️ **Attention :** Le match suivant **{ids_suiv}** a déjà été validé ou joué. Toute modification du vainqueur ou reprise réinitialisera ce(s) match(s).")
                                    chk_force = st.checkbox("Confirmer la réinitialisation des matchs suivants impactés", value=False, key=f"chk_f_{key_prefix}{mode}_{m_id}")
                                else:
                                    chk_force = True
                                
                                st.markdown("**1️⃣ Corriger le score :**")
                                col_corr_a, col_corr_b = st.columns(2)
                                options_corr_m = list(range(int(m_race) + 1))
                                idx_ca = options_corr_m.index(sa) if sa in options_corr_m else 0
                                idx_cb = options_corr_m.index(sb) if sb in options_corr_m else 0
                                with col_corr_a:
                                    sc_a_corr = int(st.selectbox(
                                        f"🎱 {formater_nom_abrege_joueur(ea)}",
                                        options=options_corr_m,
                                        index=idx_ca,
                                        key=f"corr_sc_a_{key_prefix}{mode}_{m_id}",
                                        format_func=lambda x: f"Score : {x}"
                                    ))
                                with col_corr_b:
                                    sc_b_corr = int(st.selectbox(
                                        f"🎱 {formater_nom_abrege_joueur(eb)}",
                                        options=options_corr_m,
                                        index=idx_cb,
                                        key=f"corr_sc_b_{key_prefix}{mode}_{m_id}",
                                        format_func=lambda x: f"Score : {x}"
                                    ))
                                
                                if st.button("💾 Enregistrer la correction", type="primary", use_container_width=True, key=f"btn_save_corr_{key_prefix}{mode}_{m_id}"):
                                    if sc_a_corr == sc_b_corr:
                                        st.error("Match nul impossible.")
                                    elif sc_a_corr < m_race and sc_b_corr < m_race:
                                        st.warning(f"Un joueur/duo doit remporter {m_race} manches ({m_fmt}).")
                                    else:
                                        nouveau_vainqueur = ea if sc_a_corr > sc_b_corr else eb
                                        if nouveau_vainqueur != vainq and desc_termines and not chk_force:
                                            st.error("Veuillez cocher la confirmation d'impact sur les matchs ultérieurs.")
                                        else:
                                            ok, msg = corriger_score_elimination(tournoi, m_id, sc_a_corr, sc_b_corr, forcer_cascade=chk_force)
                                            if ok:
                                                td_fresh = charger_tournois_data()
                                                if not key_prefix or (td_fresh.get(mode) and td_fresh[mode].get("id_archive") == tournoi.get("id_archive")):
                                                    td_fresh[mode] = tournoi
                                                    sauvegarder_tournois_data(td_fresh)
                                                else:
                                                    archiver_tournoi(tournoi, mode=mode, notifier_admin=False)
                                                st.success(f"✅ {msg}")
                                                time.sleep(0.5)
                                                st.rerun()
                                            else:
                                                st.error(msg)
                                
                                st.divider()
                                st.markdown("**2️⃣ Reprendre la validation :**")
                                st.caption("Annule la validation et remet la rencontre en attente de score.")
                                if st.button("🔄 Reprendre la validation (Remettre en jeu)", type="secondary", use_container_width=True, key=f"btn_reprendre_{key_prefix}{mode}_{m_id}"):
                                    if desc_termines and not chk_force:
                                        st.error("Veuillez cocher la confirmation d'impact sur les matchs ultérieurs.")
                                    else:
                                        ok, msg = reprendre_validation_match_elimination(tournoi, m_id, forcer_cascade=chk_force)
                                        if ok:
                                            st.session_state[f"sc_a_{key_prefix}{mode}_{m_id}"] = sa
                                            st.session_state[f"sc_b_{key_prefix}{mode}_{m_id}"] = sb
                                            td_fresh = charger_tournois_data()
                                            if not key_prefix or (td_fresh.get(mode) and td_fresh[mode].get("id_archive") == tournoi.get("id_archive")):
                                                td_fresh[mode] = tournoi
                                                sauvegarder_tournois_data(td_fresh)
                                            else:
                                                archiver_tournoi(tournoi, mode=mode, notifier_admin=False)
                                            st.success(f"🔄 {msg}")
                                            time.sleep(0.5)
                                            st.rerun()
                                        else:
                                            st.error(msg)
                        else:
                            st.caption("✅ *Rencontre terminée et validée*")



        tours = tournoi.get("tours", [])



        if format_type == "double_elimination":

            tours_winner = [t for t in tours if t.get("bracket") == "winner"]

            tours_loser = [t for t in tours if t.get("bracket") == "loser"]

            tours_finale = [t for t in tours if t.get("bracket") == "finale"]



            tab_w, tab_l, tab_f = st.tabs([

                f"🟦 Tableau des Gagnants ({len(tours_winner)} tours)",

                f"🟧 Seconde Chance — Repêchage ({len(tours_loser)} tours)",

                "🏆 Grande Finale"

            ])



            with tab_w:

                for tour_courant in tours_winner:

                    tour_num = tour_courant["numero"]

                    tour_race = tour_courant.get("race_to", 2)

                    tour_fmt = tour_courant.get("format_label", "2 de 3")

                    st.markdown(f"###### **{tour_courant['nom']}** — Format `{tour_fmt}` (premier à {tour_race} victoires)")

                    r_ok_w, r_msg_w, _ = verifier_ronde_precedente_terminee(tournoi, tour_courant, tour_num)
                    if not r_ok_w:
                        st.warning(f"🔒 **Ronde en attente :** {r_msg_w}")

                    for m in tour_courant.get("matchs", []):

                        afficher_carte_rencontre(m, tour_courant, tour_num, tour_race, tour_fmt)



            with tab_l:

                for tour_courant in tours_loser:

                    tour_num = tour_courant["numero"]

                    tour_race = tour_courant.get("race_to", 2)

                    tour_fmt = tour_courant.get("format_label", "2 de 3")

                    st.markdown(f"###### **{tour_courant['nom']}** — Format `{tour_fmt}` (premier à {tour_race} victoires)")

                    r_ok_l, r_msg_l, _ = verifier_ronde_precedente_terminee(tournoi, tour_courant, tour_num)
                    if not r_ok_l:
                        st.warning(f"🔒 **Ronde en attente :** {r_msg_l}")

                    for m in tour_courant.get("matchs", []):

                        afficher_carte_rencontre(m, tour_courant, tour_num, tour_race, tour_fmt)



            with tab_f:

                for tour_courant in tours_finale:

                    tour_num = tour_courant["numero"]

                    tour_race = tour_courant.get("race_to", 3)

                    tour_fmt = tour_courant.get("format_label", "3 de 5")

                    st.markdown(f"###### **{tour_courant['nom']}** — Format `{tour_fmt}` (premier à {tour_race} victoires)")

                    r_ok_f, r_msg_f, _ = verifier_ronde_precedente_terminee(tournoi, tour_courant, tour_num)
                    if not r_ok_f:
                        st.warning(f"🔒 **Ronde en attente :** {r_msg_f}")

                    for m in tour_courant.get("matchs", []):

                        afficher_carte_rencontre(m, tour_courant, tour_num, tour_race, tour_fmt)



        else:

            # Elimination directe simple

            tours_onglets = [t["nom"] for t in tours]

            if tours_onglets:

                tabs_t = st.tabs(tours_onglets)

                for t_idx, tab_tour in enumerate(tabs_t):

                    tour_courant = tours[t_idx]

                    tour_num = tour_courant["numero"]

                    tour_race = tour_courant.get("race_to", 3 if tour_num == tournoi.get("total_tours") else 2)

                    tour_fmt = tour_courant.get("format_label", "3 de 5" if tour_race == 3 else "2 de 3")

                    with tab_tour:

                        st.markdown(f"###### **{tour_courant['nom']}** — Format `{tour_fmt}` (premier à {tour_race} manches gagnantes)")

                        r_ok_s, r_msg_s, _ = verifier_ronde_precedente_terminee(tournoi, tour_courant, tour_num)
                        if not r_ok_s:
                            st.warning(f"🔒 **Ronde en attente :** {r_msg_s}")

                        for m in tour_courant.get("matchs", []):

                            afficher_carte_rencontre(m, tour_courant, tour_num, tour_race, tour_fmt)



    else:

        # FORMAT ROUND-ROBIN

        st.markdown("##### 📊 Classement en direct (Round-Robin)")

        classement_rr = calculer_classement_round_robin(tournoi)



        lignes_rr = []

        medailles_rr = {1: "🥇", 2: "🥈", 3: "🥉"}

        for rang, (part, s_data) in enumerate(classement_rr, start=1):

            badge_r = medailles_rr.get(rang, f"#{rang}")

            diff_str = f"+{s_data['diff']}" if s_data['diff'] > 0 else str(s_data['diff'])

            lignes_rr.append({

                "Rang": badge_r,

                "Participant": part,

                "PJ": s_data["pj"],

                "V": s_data["v"],

                "D": s_data["d"],

                "Manches Pour": s_data["pour"],

                "Manches Contre": s_data["contre"],

                "Différence": diff_str,

                "Points": s_data["pts"]

            })



        df_rr = pd.DataFrame(lignes_rr)

        afficher_tableau_html_compatible(df_rr)



        st.divider()

        st.markdown("##### 📋 Calendrier des rencontres")



        matchs_rr = tournoi.get("matchs", [])

        tous_termines = True

        for m in matchs_rr:

            m_id = m["id"]

            ea, eb = m["equipe_a"], m["equipe_b"]

            termine = m.get("termine", False)

            if not termine:

                tous_termines = False

            sa, sb = m.get("score_a", 0), m.get("score_b", 0)



            m_h = m.get("heure_estimee", "")

            m_tbl = m.get("table", "Table 1")

            badge_horaire_rr = f"<span style='background:#e8f0fe; color:#0b3c5d; padding:2px 8px; border-radius:10px; font-size:11px; font-weight:600;'>⏰ {m_h} • {m_tbl}</span>" if m_h else ""



            with st.container(border=True):

                col_rm1, col_rm2 = st.columns([1.15, 1.05])

                rr_race = tournoi.get("race_to", 2)

                rr_fmt = tournoi.get("format_label", "2 de 3")

                with col_rm1:

                    if termine:

                        st.markdown(f"**{m_id}** : **{ea}** ({sa}) vs ({sb}) **{eb}**", unsafe_allow_html=True)

                        if m.get("passe_droit"):

                            st.success(f"🎟️ **Passe-droit accordé :** {m['vainqueur']} remporte la rencontre !")

                        else:

                            st.success(f"🏆 Vainqueur : {m['vainqueur']} *(score final {sa}-{sb})*")

                    else:

                        st.markdown(f"**{m_id}** : 🎯 **{ea}** vs **{eb}**", unsafe_allow_html=True)

                        st.caption(f"Format officiel : **{rr_fmt}** (premier à {rr_race} victoires)")



                    if est_editeur:

                        btn_lbl_hrr = f"🕒 Horaire ({m_h} • {m_tbl})" if (m_h and m_h != "—") else "🕒 Définir horaire"

                        with st.popover(btn_lbl_hrr, use_container_width=False, help="Changer l'heure programmée pour ce match et mettre à jour le calendrier"):

                            st.markdown(f"###### ⏰ Horaire du match **{m_id}**")

                            st.caption(f"Rencontre : **{ea}** vs **{eb}**")

                            t_actuel = parse_heure_str_vers_time(m_h)

                            col_pop_h1, col_pop_h2 = st.columns(2)

                            with col_pop_h1:

                                nouv_t = st.time_input("Nouvelle heure :", value=t_actuel, key=f"rr_t_in_{key_prefix}{mode}_{m_id}", step=300)

                            with col_pop_h2:

                                opts_tables = ["Table 1", "Table 2", "Table 3", "Table 4", "Table finale"]

                                cur_tbl = m.get("table", "Table 1")

                                idx_t = opts_tables.index(cur_tbl) if cur_tbl in opts_tables else 0

                                nouv_tbl = st.selectbox("Table :", options=opts_tables, index=idx_t, key=f"rr_tbl_sel_{key_prefix}{mode}_{m_id}")



                            decaler_suivants = st.checkbox("Décaler aussi les matchs suivants de ce décalage", value=False, key=f"chk_shift_rr_{key_prefix}{mode}_{m_id}", help="Si coché, ajuste automatiquement l'horaire des matchs ultérieurs non terminés")



                            if st.button("💾 Mettre à jour le calendrier", type="primary", use_container_width=True, key=f"btn_save_hr_rr_{key_prefix}{mode}_{m_id}"):
                                str_h = nouv_t.strftime("%Hh%M")
                                old_h_prec = m.get("heure_estimee", "")
                                old_tbl_prec = m.get("table", "")

                                matchs_decales = []
                                if decaler_suivants and m_h and m_h != "—":
                                    old_t = parse_heure_str_vers_time(m_h)
                                    diff_min = (nouv_t.hour * 60 + nouv_t.minute) - (old_t.hour * 60 + old_t.minute)
                                    if diff_min != 0:
                                        matchs_decales = decaler_horaires_matchs_suivants(tournoi, m_id, diff_min)

                                m["heure_estimee"] = str_h
                                m["table"] = nouv_tbl
                                m["table_courte"] = "T" + nouv_tbl.split(" ")[-1] if " " in nouv_tbl else nouv_tbl[:2].upper()
                                recalculer_heure_fin_tournoi(tournoi)

                                msg_sms_extra = ""
                                if str_h != old_h_prec or nouv_tbl != old_tbl_prec:
                                    nb_av, list_av = envoyer_convocations_changement_heure_match(
                                        tournoi, m, str_h, nouv_tbl, matchs_suivants_decales=matchs_decales
                                    )
                                    if nb_av > 0:
                                        msg_sms_extra = f" et {nb_av} convocation(s) SMS envoyée(s) 📲 !"
                                        st.session_state[f"msg_act_sms_{mode}"] = f"🔔 Convocations SMS envoyées suite au changement d'horaire ({', '.join(list_av)}) !"

                                sauvegarder_tournois_data(tournois_data)
                                st.success(f"✅ Rencontre {m_id} reprogrammée à {str_h} ({nouv_tbl}){msg_sms_extra} et calendrier actualisé !")
                                time.sleep(0.5)
                                st.rerun()



                with col_rm2:

                    if not termine:

                        if est_editeur:

                            col_s1, col_s2, col_s_btns = st.columns([1.1, 1.1, 1.3])

                            options_rr_m = list(range(int(rr_race) + 1))

                            key_rr_a = f"rr_a_{mode}_{m_id}"

                            key_rr_b = f"rr_b_{mode}_{m_id}"

                            if key_rr_a not in st.session_state or st.session_state[key_rr_a] not in options_rr_m:

                                st.session_state[key_rr_a] = 0

                            if key_rr_b not in st.session_state or st.session_state[key_rr_b] not in options_rr_m:

                                st.session_state[key_rr_b] = 0

                            idx_rr_a = options_rr_m.index(st.session_state[key_rr_a])

                            idx_rr_b = options_rr_m.index(st.session_state[key_rr_b])

                            with col_s1:

                                sc_a_in = int(st.selectbox(

                                    f"🎱 {formater_nom_abrege_joueur(ea)}",

                                    options=options_rr_m,

                                    index=idx_rr_a,

                                    key=key_rr_a,

                                    format_func=lambda x: f"Score : {x}",

                                    help=f"Score de {ea} (0 à {rr_race})"

                                ))

                            with col_s2:

                                sc_b_in = int(st.selectbox(

                                    f"🎱 {formater_nom_abrege_joueur(eb)}",

                                    options=options_rr_m,

                                    index=idx_rr_b,

                                    key=key_rr_b,

                                    format_func=lambda x: f"Score : {x}",

                                    help=f"Score de {eb} (0 à {rr_race})"

                                ))

                            with col_s_btns:

                                st.write("")

                                if st.button("✅ Valider", key=f"btn_rr_{key_prefix}{mode}_{m_id}", type="primary", use_container_width=True):

                                    if sc_a_in == sc_b_in:

                                        st.error("Match nul impossible.")

                                    elif sc_a_in < rr_race and sc_b_in < rr_race:

                                        st.warning(f"Un joueur/duo doit remporter {rr_race} manches ({rr_fmt}).")

                                    else:

                                        m["score_a"] = sc_a_in

                                        m["score_b"] = sc_b_in

                                        m["vainqueur"] = ea if sc_a_in > sc_b_in else eb

                                        m["termine"] = True

                                        sauvegarder_tournois_data(tournois_data)

                                        st.rerun()



                                with st.popover("🎟️ Promotion", use_container_width=True, help="Accorder une victoire par promotion / passe-droit"):

                                    st.markdown("##### 🎟️ Victoire par promotion")

                                    st.caption(f"Rencontre **{m_id}** :")

                                    choix_promo_rr = st.radio(

                                        "Bénéficiaire de la promotion :",

                                        options=[ea, eb],

                                        format_func=lambda x: f"🚀 {x}",

                                        key=f"rad_pd_rr_{key_prefix}{mode}_{m_id}"

                                    )

                                    if st.button("🚀 Promouvoir / Victoire", type="primary", use_container_width=True, key=f"btn_apply_pd_rr_{key_prefix}{mode}_{m_id}"):

                                        attribuer_passe_droit_round_robin(tournoi, m_id, choix_promo_rr)

                                        sauvegarder_tournois_data(tournois_data)

                                        st.success(f"🎟️ Passe-droit accordé à {choix_promo_rr} !")

                                        st.rerun()

                        else:

                            st.caption("⏳ *Rencontre en attente de score (saisie réservée au marqueur)*")
                    else:
                        if est_editeur:
                            with st.popover("✏️ Reprendre / Corriger", use_container_width=True, help="Corriger le score ou reprendre la validation de ce match"):
                                st.markdown(f"###### ✏️ Correction du match **{m_id}**")
                                st.caption(f"Rencontre : **{ea}** vs **{eb}**")
                                if m.get("passe_droit"):
                                    st.info(f"🎟️ Validé par Passe-droit en faveur de **{m.get('vainqueur')}**")
                                else:
                                    st.caption(f"Score enregistré : **{ea}** {sa} - {sb} **{eb}** (Vainqueur : **{m.get('vainqueur')}**)")
                                
                                st.markdown("**1️⃣ Corriger le score :**")
                                col_corr_a, col_corr_b = st.columns(2)
                                options_corr_rr = list(range(int(rr_race) + 1))
                                idx_rca = options_corr_rr.index(sa) if sa in options_corr_rr else 0
                                idx_rcb = options_corr_rr.index(sb) if sb in options_corr_rr else 0
                                with col_corr_a:
                                    sc_a_corr = int(st.selectbox(
                                        f"🎱 {formater_nom_abrege_joueur(ea)}",
                                        options=options_corr_rr,
                                        index=idx_rca,
                                        key=f"corr_rr_a_{key_prefix}{mode}_{m_id}",
                                        format_func=lambda x: f"Score : {x}"
                                    ))
                                with col_corr_b:
                                    sc_b_corr = int(st.selectbox(
                                        f"🎱 {formater_nom_abrege_joueur(eb)}",
                                        options=options_corr_rr,
                                        index=idx_rcb,
                                        key=f"corr_rr_b_{key_prefix}{mode}_{m_id}",
                                        format_func=lambda x: f"Score : {x}"
                                    ))
                                
                                if st.button("💾 Enregistrer la correction", type="primary", use_container_width=True, key=f"btn_save_corr_rr_{key_prefix}{mode}_{m_id}"):
                                    if sc_a_corr == sc_b_corr:
                                        st.error("Match nul impossible.")
                                    elif sc_a_corr < rr_race and sc_b_corr < rr_race:
                                        st.warning(f"Un joueur/duo doit remporter {rr_race} manches ({rr_fmt}).")
                                    else:
                                        ok, msg = corriger_score_round_robin(tournoi, m_id, sc_a_corr, sc_b_corr)
                                        if ok:
                                            sauvegarder_tournois_data(tournois_data)
                                            st.success(f"✅ {msg}")
                                            time.sleep(0.5)
                                            st.rerun()
                                        else:
                                            st.error(msg)
                                
                                st.divider()
                                st.markdown("**2️⃣ Reprendre la validation :**")
                                st.caption("Annule la validation et remet la rencontre en attente de score.")
                                if st.button("🔄 Reprendre la validation (Remettre en jeu)", type="secondary", use_container_width=True, key=f"btn_reprendre_rr_{key_prefix}{mode}_{m_id}"):
                                    ok, msg = reprendre_validation_round_robin(tournoi, m_id)
                                    if ok:
                                        st.session_state[f"rr_a_{mode}_{m_id}"] = sa
                                        st.session_state[f"rr_b_{mode}_{m_id}"] = sb
                                        sauvegarder_tournois_data(tournois_data)
                                        st.success(f"🔄 {msg}")
                                        time.sleep(0.5)
                                        st.rerun()
                                    else:
                                        st.error(msg)
                        else:
                            st.caption("✅ *Rencontre terminée et validée*")



        if tous_termines and statut != "termine" and classement_rr:

            tournoi["statut"] = "termine"

            tournoi["vainqueur_final"] = classement_rr[0][0]

            if len(classement_rr) > 1:

                tournoi["finaliste"] = classement_rr[1][0]

            archiver_tournoi(tournoi, mode=mode, notifier_admin=True)

            sauvegarder_tournois_data(tournois_data)

            st.rerun()


def afficher_section_tournoi(mode="simple"):

    """Affiche l'interface complète de configuration ou de déroulement d'un tournoi (Simple ou Double)."""

    if f"msg_finale_{mode}" in st.session_state:

        st.success(st.session_state.pop(f"msg_finale_{mode}"))

    if f"msg_recup_{mode}" in st.session_state:

        st.success(st.session_state.pop(f"msg_recup_{mode}"))

    if f"msg_annulation_{mode}" in st.session_state:

        st.info(st.session_state.pop(f"msg_annulation_{mode}"))



    # Actualisation systématique si mise à jour du marqueur détectée

    if not (st.session_state.get("est_spectateur", False) or not st.session_state.get("authentifie", False)):

        my_sid = st.session_state.get("user_session_id", "")

        veut_ed = not st.session_state.get("mode_consultation", False)

        is_ed, _, _ = gerer_verrou_session(my_sid, veut_etre_editeur=veut_ed)

    else:

        is_ed = False



    if not is_ed and os.path.exists(TOURNOIS_FILE):

        try:

            mtime_t = os.path.getmtime(TOURNOIS_FILE)

            cle_t = "dernier_mtime_tournois_vu"

            if cle_t in st.session_state and mtime_t > st.session_state[cle_t]:

                st.session_state[cle_t] = mtime_t

                actualiser_resultats_tournoi("🔔 Le marqueur a mis à jour le tournoi ! Actualisation systématique des résultats.")

        except Exception:

            pass



    est_spectateur = st.session_state.get("est_spectateur", False) or not st.session_state.get("authentifie", False)

    if est_spectateur:

        est_editeur = False

    else:

        my_session_id = st.session_state.get("user_session_id", "")

        veut_editer = not st.session_state.get("mode_consultation", False)

        est_editeur, _, _ = gerer_verrou_session(my_session_id, veut_etre_editeur=veut_editer)



    tournois_data = charger_tournois_data()

    tournoi = tournois_data.get(mode)



    libelle_mode = "Tournoi en Simple (1 contre 1)" if mode == "simple" else "Tournoi en Double / Équipes (2 contre 2)"

    st.markdown(f"### {'👤' if mode == 'simple' else '👥'} {libelle_mode}")



    # 1. CAS OÙ AUCUN TOURNOI N'EST EN COURS : FORMULAIRE DE CRÉATION OU CONSULTATION

    if not tournoi:

        if not est_editeur:

            with st.container(border=True):

                st.markdown(f"#### 👁️ **{libelle_mode} — Mode Consultation**")

                st.info(

                    "🔒 **La création et la configuration des tournois sont réservées au marqueur officiel.**\n\n"

                    "Aucun tournoi n'est actuellement en cours. "

                    "Dès que le marqueur officiel lancera la compétition, "

                    "vous pourrez consulter ici en direct l'arborescence des rencontres, les résultats des matchs et le classement."

                )

                if not est_spectateur:

                    if st.button("⚡ Prendre la main pour créer un tournoi", key=f"btn_take_sec_{mode}", type="primary", use_container_width=True):

                        prendre_la_main_avec_rechargement(my_session_id)

                        st.rerun()

                else:

                    if st.button("🔑 Connexion éditeur", key=f"btn_login_sec_{mode}", type="primary", use_container_width=True):

                        st.session_state["est_spectateur"] = False

                        st.session_state["authentifie"] = False

                        st.rerun()

                if st.button("🔄 Vérifier si un tournoi a été lancé", key=f"btn_check_launch_{mode}", use_container_width=True, help="Vérifie si le marqueur a débuté un nouveau tournoi"):

                    st.rerun()

            return



        recup_liste_sec = obtenir_tournois_recuperables(mode=mode)
        if not recup_liste_sec:
            recup_liste_sec = obtenir_tournois_recuperables(mode=None)

        if recup_liste_sec:
            with st.container(border=True):
                st.markdown(f"#### ⚡ Reprendre un tournoi en cours")
                st.caption("Un ou plusieurs tournois non terminés sont disponibles dans l'historique. Vous pouvez en reprendre un directement :")
                for t_r in recup_liste_sec:
                    t_id = t_r.get("id_archive")
                    titre_r = t_r.get("titre", "Tournoi")
                    m_r = t_r.get("mode", "simple")
                    prog_r = calculer_progression_tournoi(t_r)
                    col_rc1, col_rc2 = st.columns([3, 1.2])
                    with col_rc1:
                        badge_m = "👤 Simple" if m_r == "simple" else "👥 Double"
                        st.write(f"**{titre_r}** — `{badge_m}` • *{t_r.get('date_creation', '')}*")
                        st.caption(f"Avancement : **{prog_r}** • Format : {t_r.get('format', 'elimination')}")
                    with col_rc2:
                        if st.button("⚡ Reprendre ce tournoi", key=f"btn_recup_grid_{mode}_{t_id}", type="primary", use_container_width=True):
                            recuperer_tournoi_en_cours(t_id, mode_cible=m_r)

        afficher_formulaire_creation_tournoi(mode=mode, key_suffix=f"_sec_{mode}", est_editeur=est_editeur)

        return



    # 2. CAS OÙ UN TOURNOI EST EN COURS OU TERMINÉ

    else:

        titre_t = tournoi.get("titre", "Tournoi officiel")

        format_type = tournoi.get("format", "elimination")

        race_to = tournoi.get("race_to", 2)

        statut = tournoi.get("statut", "en_cours")



        if st.session_state.pop(f"ouvrir_arborescence_auto_{mode}", False):

            modal_arborescence_tournoi(tournoi, mode_str=mode)



        html_tournoi = generer_html_tournoi(tournoi, mode=mode)

        html_t_json = json.dumps(html_tournoi)



        if est_editeur:

            col_top1, col_top2, col_top_tv, col_top3, col_top_mail, col_top_recup, col_top_new, col_top4, col_top5 = st.columns([1.3, 0.85, 0.8, 0.8, 0.9, 0.85, 0.8, 0.95, 0.95])

        else:

            col_top1, col_top2, col_top_tv, col_top3, col_top_mail, col_top4 = st.columns([1.5, 0.95, 0.95, 0.95, 1.1, 1.1])



        with col_top1:

            st.markdown(f"#### 🏆 **{titre_t}**")

            badge_statut = "🟢 **En cours**" if statut == "en_cours" else "🏆 **Tournoi Terminé**"

            if format_type == "double_elimination":

                format_nom = "Double élimination (Gagnants & Seconde chance 2 de 3 • Grande Finale 3 de 5)"

            elif format_type == "elimination":

                format_nom = "Élimination directe (Préliminaires 2 de 3 • Finale 3 de 5)"

            else:

                format_nom = "Championnat Round-Robin (2 de 3)"



            h_deb = tournoi.get("heure_debut", "09:00")

            h_fin = tournoi.get("heure_fin_estimee", "")

            nb_t = tournoi.get("nb_tables", 2)

            duree_m = tournoi.get("duree_match_min", 30)

            tables_txt = f"{nb_t} table{'s' if nb_t > 1 else ''}"

            mention_pause = " *(Pause 12h-13h)*" if (h_fin and (h_deb < "12:00" and h_fin > "12h00")) else ""

            horaire_txt = f" &nbsp;|&nbsp; ⏰ <strong>Horaire :</strong> {h_deb} à ~{h_fin}{mention_pause}" if h_fin else f" &nbsp;|&nbsp; ⏰ <strong>Début :</strong> {h_deb}"

