def afficher_onglet_tournois():

    """Onglet principal Tournois avec bandeau de verrou, prise/cession de main, Création de nouveau tournoi, Simple, Double et Historique."""

    afficher_bandeau_verrou_tournoi()



    td = charger_tournois_data()

    t_simple = td.get("simple")

    t_double = td.get("double")

    simple_actif = bool(t_simple and isinstance(t_simple, dict) and t_simple.get("statut") == "en_cours" and (t_simple.get("tours") or t_simple.get("matchs")))
    simple_termine = bool(t_simple and isinstance(t_simple, dict) and t_simple.get("statut") == "termine")

    double_actif = bool(t_double and isinstance(t_double, dict) and t_double.get("statut") == "en_cours" and (t_double.get("tours") or t_double.get("matchs")))
    double_termine = bool(t_double and isinstance(t_double, dict) and t_double.get("statut") == "termine")

    if simple_actif:
        lbl_simple = "👤 Tournoi Simple 🟢 (Actif)"
    elif simple_termine:
        lbl_simple = "👤 Tournoi Simple 🏆 (Terminé)"
    else:
        lbl_simple = "👤 Tournoi Simple"

    if double_actif:
        lbl_double = "👥 Tournoi Double 🟢 (Actif)"
    elif double_termine:
        lbl_double = "👥 Tournoi Double 🏆 (Terminé)"
    else:
        lbl_double = "👥 Tournoi Double"



    # Disposition stable et constante des onglets pour garantir une navigation fluide sans permutation d'index
    tabs = st.tabs([

        lbl_simple,

        lbl_double,

        "➕ Créer un nouveau tournoi",

        "📜 Liste des tournois sauvegardés & Historique"

    ])

    with tabs[0]:

        afficher_section_tournoi(mode="simple")

    with tabs[1]:

        afficher_section_tournoi(mode="double")

    with tabs[2]:

        afficher_onglet_nouveau_tournoi()

    with tabs[3]:

        afficher_section_historique_tournois()





