def afficher_configuration_debut_saison(key_prefix="cfg_saison", afficher_reset_historique=False):
    """Affiche et édite les prérequis pour démarrer une saison :
    1. Date de début de la saison (pour l'horaire)
    2. Liste des joueurs inscrits et contraintes des joueurs pour jouer
    3. Liste des équipes
    Permet de générer automatiquement l'horaire de la saison en respectant ces prérequis.
    """
    cfg_s = charger_config_saison()
    equipes_actuelles = charger_equipes_csv()
    joueurs_inscrits = cfg_s.get("joueurs_inscrits", [])

    try:
        date_deb_init = datetime.strptime(str(cfg_s.get("date_debut_saison", "2026-09-07")).strip(), "%Y-%m-%d").date()
    except Exception:
        date_deb_init = deduire_date_debut_saison_depuis_horaire()

    nb_sem_init = int(cfg_s.get("nb_semaines", 14) or 14)

    # Validation des prérequis
    ok_date = isinstance(date_deb_init, date)
    nb_joueurs_valides = len([j for j in joueurs_inscrits if isinstance(j, dict) and str(j.get("joueur", "")).strip()])
    ok_joueurs = nb_joueurs_valides >= 6
    nb_equipes_valides = len([eq for eq, jl in (equipes_actuelles or {}).items() if str(eq).strip() and len(jl) >= 1])
    ok_equipes = nb_equipes_valides >= 2
    nb_contraintes = len([
        j for j in joueurs_inscrits
        if isinstance(j, dict) and (
            not bool(j.get("lundi", True))
            or not bool(j.get("mardi", True))
            or not bool(j.get("mercredi", True))
            or not bool(j.get("jeudi", True))
            or bool(str(j.get("contraintes", "") or "").strip())
        )
    ])

    mois_fr_map = {
        1: "janvier", 2: "février", 3: "mars", 4: "avril", 5: "mai", 6: "juin",
        7: "juillet", 8: "août", 9: "septembre", 10: "octobre", 11: "novembre", 12: "décembre"
    }
    date_fin_calc = date_deb_init + timedelta(days=(nb_sem_init - 1) * 7 + 3)
    txt_deb_fr = f"{date_deb_init.day} {mois_fr_map.get(date_deb_init.month, '')} {date_deb_init.year}"
    txt_fin_fr = f"{date_fin_calc.day} {mois_fr_map.get(date_fin_calc.month, '')} {date_fin_calc.year}"

    st.markdown("#### 🚀 Prérequis pour démarrer une saison & Configuration de l'horaire")
    c_pr1, c_pr2, c_pr3, c_pr4 = st.columns(4)
    c_pr1.metric("1️⃣ Début de saison", txt_deb_fr, f"Fin : {txt_fin_fr} ({nb_sem_init} sem.)")
    c_pr2.metric("2️⃣ Joueurs inscrits", f"{nb_joueurs_valides} joueur(s)", "✅ Prêt" if ok_joueurs else "⚠️ Min. 6 requis")
    c_pr3.metric("3️⃣ Liste des équipes", f"{nb_equipes_valides} équipe(s)", "✅ Prêt" if ok_equipes else "⚠️ Min. 2 requises")
    c_pr4.metric("4️⃣ Contraintes joueurs", f"{nb_contraintes} joueur(s)", "Prises en compte dans l'horaire")

    sub_tab_date, sub_tab_joueurs, sub_tab_equipes = st.tabs([
        "1️⃣ Date de début de la saison",
        "2️⃣ Joueurs inscrits & Contraintes pour jouer",
        "3️⃣ Liste des équipes & Disponibilités"
    ])

    with sub_tab_date:
        st.markdown("##### 📅 Définir la date de début de la saison pour l'horaire")
        st.caption("Choisissez la date du premier jour (Lundi de la Semaine 1). Les dates des 14 semaines de l'horaire (`Lundi` à `Jeudi`) sont calculées à partir de cette date.")
        col_d1, col_d2, col_d3 = st.columns([1.4, 1.0, 1.6])
        with col_d1:
            nouv_date_deb = st.date_input(
                "Date de début de la saison (Semaine 1) :",
                value=date_deb_init,
                key=f"{key_prefix}_date_debut_input"
            )
        with col_d2:
            nouv_nb_sem = st.number_input(
                "Nombre de semaines :",
                min_value=1,
                max_value=30,
                value=nb_sem_init,
                step=1,
                key=f"{key_prefix}_nb_sem_input"
            )
        with col_d3:
            st.write("")
            if st.button("💾 Enregistrer le début de saison & recalculer les dates", type="primary", use_container_width=True, key=f"{key_prefix}_btn_save_date_deb"):
                cfg_s["date_debut_saison"] = nouv_date_deb.strftime("%Y-%m-%d")
                cfg_s["nb_semaines"] = int(nouv_nb_sem)
                sauvegarder_config_saison(cfg_s)
                lignes_recalc = recalculer_dates_horaire_depuis_debut(nouv_date_deb, charger_horaire_json(), int(nouv_nb_sem))
                sauvegarder_horaire_json(lignes_recalc)
                st.success(f"✅ Date de début enregistrée ({nouv_date_deb.strftime('%d/%m/%Y')}) et dates de l'horaire mises à jour sur {int(nouv_nb_sem)} semaines !")
                time.sleep(0.7)
                st.rerun()

    with sub_tab_joueurs:
        st.markdown("##### 👥 Liste des joueurs inscrits et contraintes des joueurs pour jouer")
        st.caption(
            "Inscrivez les joueurs de la saison, leur équipe et cochez/décochez leurs jours de disponibilité (`Lundi`, `Mardi`, `Mercredi`, `Jeudi`) "
            "ou ajoutez une note de contrainte. Lors de la génération de l'horaire, une équipe ne sera pas programmée un soir où l'un de ses joueurs est indisponible."
        )
        lignes_j_df = []
        for j_it in joueurs_inscrits:
            if not isinstance(j_it, dict):
                continue
            lignes_j_df.append({
                "Joueur": str(j_it.get("joueur", "")).strip(),
                "Équipe": str(j_it.get("equipe", "")).strip(),
                "Dispo Lundi": bool(j_it.get("lundi", True)),
                "Dispo Mardi": bool(j_it.get("mardi", True)),
                "Dispo Mercredi": bool(j_it.get("mercredi", True)),
                "Dispo Jeudi": bool(j_it.get("jeudi", True)),
                "Contraintes / Notes": str(j_it.get("contraintes", "") or "").strip(),
            })
        if not lignes_j_df:
            lignes_j_df.append({
                "Joueur": "Joueur 1",
                "Équipe": "Alpha",
                "Dispo Lundi": True,
                "Dispo Mardi": True,
                "Dispo Mercredi": True,
                "Dispo Jeudi": True,
                "Contraintes / Notes": "",
            })

        df_j_edit = st.data_editor(
            pd.DataFrame(lignes_j_df),
            num_rows="dynamic",
            use_container_width=True,
            hide_index=True,
            key=f"{key_prefix}_editor_joueurs_contraintes",
            column_config={
                "Joueur": st.column_config.TextColumn("Joueur inscrit", required=True, width="medium"),
                "Équipe": st.column_config.TextColumn("Équipe", required=True, width="small"),
                "Dispo Lundi": st.column_config.CheckboxColumn("Dispo Lundi", default=True),
                "Dispo Mardi": st.column_config.CheckboxColumn("Dispo Mardi", default=True),
                "Dispo Mercredi": st.column_config.CheckboxColumn("Dispo Mercredi", default=True),
                "Dispo Jeudi": st.column_config.CheckboxColumn("Dispo Jeudi", default=True),
                "Contraintes / Notes": st.column_config.TextColumn("Contraintes pour jouer (ex: Pas lundi)", width="medium"),
            }
        )

        if st.button("💾 Enregistrer la liste des joueurs inscrits et leurs contraintes", type="primary", use_container_width=True, key=f"{key_prefix}_btn_save_joueurs"):
            nouv_joueurs = []
            eq_grouped = {}
            for _, r_j in df_j_edit.iterrows():
                nom_j = str(r_j.get("Joueur", "") or "").strip()
                if not nom_j or nom_j.lower() == "nan":
                    continue
                eq_j = str(r_j.get("Équipe", "") or "").strip()
                if eq_j.lower() == "nan":
                    eq_j = ""
                nouv_joueurs.append({
                    "joueur": nom_j,
                    "equipe": eq_j,
                    "lundi": bool(r_j.get("Dispo Lundi", True)),
                    "mardi": bool(r_j.get("Dispo Mardi", True)),
                    "mercredi": bool(r_j.get("Dispo Mercredi", True)),
                    "jeudi": bool(r_j.get("Dispo Jeudi", True)),
                    "contraintes": "" if str(r_j.get("Contraintes / Notes", "") or "").strip().lower() == "nan" else str(r_j.get("Contraintes / Notes", "") or "").strip(),
                })
                if eq_j:
                    eq_grouped.setdefault(eq_j, []).append(nom_j)

            cfg_s["joueurs_inscrits"] = nouv_joueurs
            # Mettre aussi à jour equipes-saphir.csv si des équipes ont été modifiées
            if eq_grouped:
                eq_maj = dict(equipes_actuelles)
                for eq_k, jl_k in eq_grouped.items():
                    while len(jl_k) < 3:
                        jl_k.append(f"Joueur {len(jl_k) + 1}")
                    eq_maj[eq_k] = jl_k[:3]
                sauvegarder_equipes_csv(eq_maj)
                cfg_s["equipes"] = eq_maj
            sauvegarder_config_saison(cfg_s)
            st.success(f"✅ {len(nouv_joueurs)} joueur(s) inscrit(s) et leurs contraintes ont été enregistrés !")
            time.sleep(0.7)
            st.rerun()

    with sub_tab_equipes:
        st.markdown("##### 🛡️ Liste des équipes et synthèse des disponibilités")
        st.caption("Vérifiez ou modifiez la composition des équipes (`equipes-saphir.csv`). Les jours disponibles de chaque équipe sont automatiquement déduits des contraintes de ses joueurs.")
        dispo_par_eq = obtenir_jours_disponibles_equipes(equipes_actuelles, joueurs_inscrits)
        noms_jours_map = {0: "Lun", 1: "Mar", 2: "Mer", 3: "Jeu"}
        lignes_eq_df = []
        for eq_nom, j_liste in (equipes_actuelles or {}).items():
            jours_ok = sorted(list(dispo_par_eq.get(eq_nom, {0, 1, 2, 3})))
            resume_dispo = ", ".join(noms_jours_map[d] for d in jours_ok) if jours_ok else "⚠️ Aucun jour"
            lignes_eq_df.append({
                "Équipe": eq_nom,
                "Joueur 1": j_liste[0] if len(j_liste) > 0 else "",
                "Joueur 2": j_liste[1] if len(j_liste) > 1 else "",
                "Joueur 3": j_liste[2] if len(j_liste) > 2 else "",
                "Jours possibles (selon contraintes)": resume_dispo,
            })

        df_eq_edit = st.data_editor(
            pd.DataFrame(lignes_eq_df),
            num_rows="dynamic",
            use_container_width=True,
            hide_index=True,
            key=f"{key_prefix}_editor_equipes_saison",
             disabled=["Jours possibles (selon contraintes)"],
            column_config={
                "Équipe": st.column_config.TextColumn("Équipe", required=True, width="small"),
                "Joueur 1": st.column_config.TextColumn("Joueur 1", required=True, width="medium"),
                "Joueur 2": st.column_config.TextColumn("Joueur 2", required=True, width="medium"),
                "Joueur 3": st.column_config.TextColumn("Joueur 3", required=True, width="medium"),
                "Jours possibles (selon contraintes)": st.column_config.TextColumn("Jours disponibles (auto)", width="medium"),
            }
        )

        if st.button("💾 Enregistrer la liste des équipes", type="primary", use_container_width=True, key=f"{key_prefix}_btn_save_equipes"):
            nouv_eq_dict = {}
            for _, r_eq in df_eq_edit.iterrows():
                enom = str(r_eq.get("Équipe", "") or "").strip()
                if not enom or enom.lower() == "nan":
                    continue
                j1 = str(r_eq.get("Joueur 1", "") or "Joueur 1").strip()
                j2 = str(r_eq.get("Joueur 2", "") or "Joueur 2").strip()
                j3 = str(r_eq.get("Joueur 3", "") or "Joueur 3").strip()
                nouv_eq_dict[enom] = [j1, j2, j3]
            if nouv_eq_dict:
                sauvegarder_equipes_csv(nouv_eq_dict)
                cfg_s["equipes"] = nouv_eq_dict
                sauvegarder_config_saison(cfg_s)
                st.success(f"✅ {len(nouv_eq_dict)} équipe(s) enregistrée(s) et synchronisée(s) !")
                time.sleep(0.7)
                st.rerun()

    st.divider()
    if len(equipes_actuelles) % 2 == 1:
        nb_eq_act = len(equipes_actuelles)
        st.info(
            f"ℹ️ **Saison à nombre impair d'équipes ({nb_eq_act} équipes) :** la génération produira un calendrier équilibré "
            f"qui inclut des semaines vacantes (BYE) réparties de manière à ce que **toutes les équipes jouent exactement le même nombre de matchs** "
            f"({2 * (nb_eq_act - 1)} matchs pour 2 cycles aller-retour, avec 2 semaines de repos par équipe)."
        )

    col_gen1, col_gen2 = st.columns([1.6, 1.4] if afficher_reset_historique else [1, 0.01])
    with col_gen1:
        if st.button(
            f"⚡ Générer l'horaire de la saison ({nb_sem_init} semaines) en minimisant les absences",
            type="primary",
            use_container_width=True,
            key=f"{key_prefix}_btn_gen_horaire_complet",
            disabled=not (ok_date and ok_joueurs and ok_equipes)
        ):
            d_cible = st.session_state.get(f"{key_prefix}_date_debut_input", date_deb_init)
            n_sem_cible = int(st.session_state.get(f"{key_prefix}_nb_sem_input", nb_sem_init))
            nouvelles_lignes_gen, conflits_gen = generer_horaire_saison_selon_prerequis(
                d_cible, equipes_actuelles, joueurs_inscrits, n_sem_cible
            )
            n_sem_reelles = len(nouvelles_lignes_gen)
            cfg_s["date_debut_saison"] = d_cible.strftime("%Y-%m-%d")
            cfg_s["nb_semaines"] = n_sem_reelles
            sauvegarder_config_saison(cfg_s)
            if sauvegarder_horaire_json(nouvelles_lignes_gen):
                if conflits_gen:
                    st.warning(
                        f"⚠️ Horaire optimisé généré ({n_sem_reelles} semaines) :\n- "
                        + "\n- ".join(conflits_gen[:6])
                    )
                else:
                    st.success(f"✅ Horaire complet et équilibré de {n_sem_reelles} semaines généré avec succès !")
                time.sleep(0.9)
                st.rerun()

    if afficher_reset_historique:
        with col_gen2:
            with st.popover("🚨 Démarrer une nouvelle saison (Générer l'horaire + Réinitialiser les scores)", use_container_width=True):
                st.markdown("### ⚠️ Démarrer une nouvelle saison officielle")
                if not (ok_date and ok_joueurs and ok_equipes):
                    st.error("❌ Veuillez d'abord compléter les 3 prérequis (Date de début, Liste des joueurs inscrits, Liste des équipes).")
                else:
                    st.write(
                        f"Cette action va :\n"
                        f"1. Enregistrer la date de début de saison (**{txt_deb_fr}**)\n"
                        f"2. Générer le nouvel horaire de **{nb_sem_init} semaines** selon les équipes et les contraintes des joueurs\n"
                        f"3. Réinitialiser l'historique des matchs (`historique_matchs.json`) à zéro."
                    )
                    if st.button("🔴 Confirmer et démarrer la nouvelle saison", type="primary", use_container_width=True, key=f"{key_prefix}_btn_confirm_new_season"):
                        d_cible = st.session_state.get(f"{key_prefix}_date_debut_input", date_deb_init)
                        n_sem_cible = int(st.session_state.get(f"{key_prefix}_nb_sem_input", nb_sem_init))
                        nouvelles_lignes_gen, _ = generer_horaire_saison_selon_prerequis(
                            d_cible, equipes_actuelles, joueurs_inscrits, n_sem_cible
                        )
                        n_sem_reelles = len(nouvelles_lignes_gen)
                        cfg_s["date_debut_saison"] = d_cible.strftime("%Y-%m-%d")
                        cfg_s["nb_semaines"] = n_sem_reelles
                        sauvegarder_config_saison(cfg_s)
                        sauvegarder_horaire_json(nouvelles_lignes_gen)
                        sauvegarder_historique_matchs([])
                        st.success(f"✅ Nouvelle saison démarrée, horaire généré ({n_sem_reelles} semaines) et historique réinitialisé !")
                        time.sleep(0.9)
                        st.rerun()


def afficher_section_horaire_saison(est_spectateur=False, key_prefix="horaire_main", editeur_ouvert=False):
    """Affiche l'horaire complet de la saison en mode consultation sur la page principale en soulignant la semaine courante."""
    import html as _html
    lignes_horaire = charger_horaire_json()
    if not isinstance(lignes_horaire, list):
        lignes_horaire = []

    cfg_saison_h = charger_config_saison()
    try:
        d_deb_horaire = datetime.strptime(str(cfg_saison_h.get("date_debut_saison", "2026-09-07")).strip(), "%Y-%m-%d").date()
    except Exception:
        d_deb_horaire = deduire_date_debut_saison_depuis_horaire(lignes_horaire)
    nb_sem_horaire = int(cfg_saison_h.get("nb_semaines", 14) or 14)

    mois_fr_map = {
        1: "janvier", 2: "février", 3: "mars", 4: "avril", 5: "mai", 6: "juin",
        7: "juillet", 8: "août", 9: "septembre", 10: "octobre", 11: "novembre", 12: "décembre"
    }
    d_fin_horaire = d_deb_horaire + timedelta(days=(nb_sem_horaire - 1) * 7 + 3)

    rencontre_jour = determiner_match_du_jour(lignes_horaire)
    semaine_courante = ""
    match_courant_txt = ""
    if rencontre_jour and str(rencontre_jour.get("semaine", "")).strip():
        semaine_courante = str(rencontre_jour.get("semaine", "")).strip()
        match_courant_txt = str(rencontre_jour.get("texte", "")).strip()
    else:
        semaine_courante = f"Semaine {calculer_semaine_saison(datetime.today())}"

    # Détecter si une équipe est en semaine vacante pour la semaine courante
    equipe_vacante_semaine = ""
    for r_check in (lignes_horaire or []):
        if isinstance(r_check, list) and len(r_check) > 0 and str(r_check[0]).strip().lower() == semaine_courante.lower():
            for c_chk in r_check[1:]:
                c_chk_str = str(c_chk or "").strip()
                if "vacant" in c_chk_str.lower() or "exempt" in c_chk_str.lower() or "bye" in c_chk_str.lower():
                    m_eq_v = re.search(r'(?:vacante|exempt|bye)\s*:\s*([a-zA-ZÀ-ſ0-9_\- ]+)', c_chk_str, re.IGNORECASE)
                    equipe_vacante_semaine = m_eq_v.group(1).strip() if m_eq_v else c_chk_str.replace("Semaine vacante", "").replace(":", "").strip()
                    break
            if equipe_vacante_semaine:
                break

    st.markdown("### 📅 Horaire officiel de la saison")
    txt_vac_cap = f" • ⏸️ **Semaine vacante :** `{equipe_vacante_semaine}`" if equipe_vacante_semaine else ""
    st.caption(
        f"🗓️ **Début de la saison :** {d_deb_horaire.day} {mois_fr_map.get(d_deb_horaire.month, '')} {d_deb_horaire.year} • "
        f"**Fin prévue :** {d_fin_horaire.day} {mois_fr_map.get(d_fin_horaire.month, '')} {d_fin_horaire.year} • "
        f"**Semaine courante :** `{semaine_courante}`{txt_vac_cap} *(La création et l'édition de l'horaire s'effectuent dans **⚙️ Administration → 🗓️ Saison**)*"
    )

    if rencontre_jour:
        statut_j = "🟢 **Match programmé aujourd'hui**" if rencontre_jour.get("est_aujourdhui") else "🔜 **Prochain match au calendrier**"
        info_vac_txt = f" • ⏸️ *Équipe vacante (exemptée) :* **{equipe_vacante_semaine}**" if equipe_vacante_semaine else ""
        st.info(
            f"{statut_j} (**{semaine_courante}** — {rencontre_jour.get('date_texte', '')}) : "
            f"**{rencontre_jour.get('receveur', '')}** (Receveur) vs **{rencontre_jour.get('visiteur', '')}** (Visiteur){info_vac_txt}"
        )

    if not lignes_horaire:
        st.warning("Aucune semaine n'est actuellement définie dans l'horaire de la saison.")
        return

    # Construction du tableau HTML avec soulignement et mise en évidence de la semaine courante
    a_match_5 = any(isinstance(r, list) and len(r) > 5 and str(r[5]).strip() not in ("", "—", "-") for r in lignes_horaire)
    a_match_6 = any(isinstance(r, list) and len(r) > 6 and str(r[6]).strip() not in ("", "—", "-") for r in lignes_horaire)

    # Détecter si la colonne 5 contient des semaines vacantes (nombre impair d'équipes)
    a_semaine_vacante = any(
        isinstance(r, list) and len(r) > 5 and ("vacant" in str(r[5]).lower() or "exempt" in str(r[5]).lower() or "bye" in str(r[5]).lower())
        for r in lignes_horaire
    )

    colonnes_h = ["Semaine", "Match 1 (Lundi)", "Match 2 (Mardi)", "Match 3 (Mercredi)", "Match 4 (Jeudi)"]
    if a_match_5:
        if a_semaine_vacante:
            colonnes_h.append("Semaine vacante")
        else:
            colonnes_h.append("Match 5")
    if a_match_6:
        colonnes_h.append("Match 6")

    ths_html = "".join(
        f'<th style="background-color:#0b3c5d; color:#ffffff; font-weight:700; padding:9px 10px; border:1px solid #334155; text-align:left; font-size:13.5px;">{_html.escape(c)}</th>'
        for c in colonnes_h
    )

    trs_html = []
    for idx_r, row in enumerate(lignes_horaire):
        if not isinstance(row, list) or not row:
            continue
        sem_lbl = str(row[0]).strip() if len(row) > 0 else f"Semaine {idx_r + 1}"
        est_sem_courante = (sem_lbl.strip().lower() == semaine_courante.strip().lower())

        bg_row = "linear-gradient(90deg, rgba(14,165,233,0.30), rgba(30,58,138,0.45))" if est_sem_courante else ("#0f172a" if idx_r % 2 == 0 else "#1e293b")
        border_row = "2px solid #38bdf8" if est_sem_courante else "1px solid #334155"

        valeurs_cells = [
            sem_lbl,
            str(row[1]).strip() if len(row) > 1 and str(row[1]).strip() else "—",
            str(row[2]).strip() if len(row) > 2 and str(row[2]).strip() else "—",
            str(row[3]).strip() if len(row) > 3 and str(row[3]).strip() else "—",
            str(row[4]).strip() if len(row) > 4 and str(row[4]).strip() else "—",
        ]
        if a_match_5:
            valeurs_cells.append(str(row[5]).strip() if len(row) > 5 and str(row[5]).strip() else "—")
        if a_match_6:
            valeurs_cells.append(str(row[6]).strip() if len(row) > 6 and str(row[6]).strip() else "—")

        tds_row = []
        for c_i, val_c in enumerate(valeurs_cells):
            val_esc = _html.escape(val_c)
            if c_i == 0:
                if est_sem_courante:
                    contenu_td = (
                        f'<div style="text-decoration:underline; text-decoration-thickness:2px; text-underline-offset:3px; font-weight:800; color:#7dd3fc;">'
                        f'👉 {val_esc}</div>'
                        f'<div style="margin-top:4px;"><span style="display:inline-block; background:#0284c7; color:#ffffff; font-size:11px; font-weight:700; padding:1px 6px; border-radius:99px;">En cours</span></div>'
                    )
                else:
                    contenu_td = f'<div style="font-weight:700; color:#e2e8f0; font-size:13.5px;">{val_esc}</div>'
            else:
                # Séparer la date et les équipes si la cellule correspond à un match
                parsed_cell = parser_ligne_horaire_match(val_c)
                if parsed_cell and parsed_cell.get("receveur") and parsed_cell.get("visiteur"):
                    # Extraire la date textuelle (ex: '26 octobre' ou '1 décembre')
                    m_date_txt = re.search(r'^(\d{1,2}\s+[a-zA-ZÀ-ſ]+)', val_c.strip())
                    date_part = m_date_txt.group(1).strip() if m_date_txt else f"{parsed_cell.get('jour')} {mois_fr_map.get(parsed_cell.get('mois'), '')}"
                    rec_nom = parsed_cell["receveur"]
                    vis_nom = parsed_cell["visiteur"]

                    if est_sem_courante:
                        est_match_jour = bool(match_courant_txt and val_c.strip().lower() == match_courant_txt.lower())
                        couleur_eq = "#fde047" if est_match_jour else "#38bdf8"
                        couleur_dt = "#fef08a" if est_match_jour else "#e2e8f0"
                        badge_direct = ' <span style="background:#eab308; color:#0f172a; font-size:10.5px; font-weight:800; padding:1px 5px; border-radius:4px; margin-left:3px;">Aujourd\'hui</span>' if est_match_jour else ''
                        contenu_td = (
                            f'<div style="font-size:12.5px; font-weight:700; color:{couleur_dt}; margin-bottom:3px; text-decoration:underline; text-decoration-thickness:1.5px; text-underline-offset:2px;">'
                            f'📅 { _html.escape(date_part) }{badge_direct}</div>'
                            f'<div style="font-size:13.5px; font-weight:800; color:{couleur_eq}; text-decoration:underline; text-decoration-thickness:2px; text-underline-offset:3px;">'
                            f'{_html.escape(rec_nom)} <span style="font-size:11px; font-weight:600; color:#94a3b8; text-decoration:none;">vs</span> {_html.escape(vis_nom)}</div>'
                        )
                    else:
                        contenu_td = (
                            f'<div style="font-size:12px; font-weight:600; color:#94a3b8; margin-bottom:2px;">'
                            f'📅 {_html.escape(date_part)}</div>'
                            f'<div style="font-size:13.5px; font-weight:700; color:#f8fafc;">'
                            f'{_html.escape(rec_nom)} <span style="font-size:11px; font-weight:500; color:#64748b;">vs</span> {_html.escape(vis_nom)}</div>'
                        )
                elif "vacant" in val_c.lower() or "exempt" in val_c.lower() or "bye" in val_c.lower():
                    # Semaine vacante / équipe exemptée
                    m_eq_val = re.search(r'(?:vacante|exempt|bye)\s*:\s*([a-zA-ZÀ-ſ0-9_\- ]+)', val_c, re.IGNORECASE)
                    nom_vac_cell = m_eq_val.group(1).strip() if m_eq_val else val_c.replace("Semaine vacante", "").replace(":", "").strip()
                    if est_sem_courante:
                        contenu_td = (
                            f'<div style="font-size:12px; font-weight:700; color:#fde047; background:rgba(234,179,8,0.20); border:1.5px solid #eab308; border-radius:6px; padding:4px 6px; text-align:center;">'
                            f'⏸️ Semaine vacante en cours<br><span style="color:#ffffff; font-weight:800; font-size:13.5px;">{_html.escape(nom_vac_cell)}</span></div>'
                        )
                    else:
                        contenu_td = (
                            f'<div style="font-size:12px; font-weight:600; color:#fbbf24; background:rgba(245,158,11,0.10); border:1px dashed #d97706; border-radius:6px; padding:4px 6px; text-align:center;">'
                            f'⏸️ Semaine vacante<br><span style="color:#e2e8f0; font-weight:700; font-size:13px;">{_html.escape(nom_vac_cell)}</span></div>'
                        )
                elif val_c in ("—", "-", ""):
                    contenu_td = '<div style="color:#64748b; font-size:13px; text-align:center;">—</div>'
                else:
                    contenu_td = f'<div style="font-size:13px; color:#cbd5e1;">{val_esc}</div>'

            if est_sem_courante:
                tds_row.append(
                    f'<td style="padding:9px 10px; border-top:{border_row}; border-bottom:{border_row}; border-left:1px solid #38bdf8; border-right:1px solid #38bdf8; vertical-align:middle;">{contenu_td}</td>'
                )
            else:
                tds_row.append(
                    f'<td style="padding:8px 10px; border:1px solid #334155; vertical-align:middle;">{contenu_td}</td>'
                )

        trs_html.append(f'<tr style="background:{bg_row};">{"".join(tds_row)}</tr>')

    html_table_horaire = (
        '<div style="width:100%; overflow-x:auto; margin:6px 0 12px 0;">'
        '<table style="width:100%; border-collapse:collapse; font-family:inherit; background-color:#0f172a; border-radius:8px; overflow:hidden;">'
        f'<thead><tr>{ths_html}</tr></thead>'
        f'<tbody>{"".join(trs_html)}</tbody>'
        '</table></div>'
    )
    st.markdown(html_table_horaire, unsafe_allow_html=True)


def afficher_selecteur_horaires_disponibles(key_prefix="admin_sel_horaires"):
    """Permet aux administrateurs de consulter, prévisualiser et charger n'importe quel horaire par saison."""
    liste_horaires = lister_horaires_saisons_disponibles()
    if not liste_horaires:
        st.info("Aucun fichier d'horaire spécifique détecté.")
        return

    st.markdown("##### 📚 Horaires disponibles par saison")
    st.caption("Consultez les horaires archivés ou basculez sur l'horaire d'une saison spécifique pour la visualisation ou l'édition.")

    options_lbl = [h["label"] for h in liste_horaires]
    cur_sel_idx = 0
    if "saison_active_selectionnee" in st.session_state:
        for i_h, h_it in enumerate(liste_horaires):
            if h_it["num"] == st.session_state["saison_active_selectionnee"]:
                cur_sel_idx = i_h
                break

    c_sh1, c_sh2 = st.columns([3, 1.2])
    with c_sh1:
        choix_h_lbl = st.selectbox(
            "Sélectionner un horaire de saison :",
            options_lbl,
            index=cur_sel_idx,
            key=f"{key_prefix}_select_horaire"
        )
    h_choisi = next((h for h in liste_horaires if h["label"] == choix_h_lbl), liste_horaires[0])

    with c_sh2:
        st.write("")
        if st.button("🔄 Charger cet horaire", use_container_width=True, key=f"{key_prefix}_btn_load_h"):
            st.session_state["saison_active_selectionnee"] = h_choisi["num"]
            # Réinitialiser cache pour affichage immédiat
            st.success(f"✅ {h_choisi['label']} chargé pour la session !")
            time.sleep(0.6)
            st.rerun()

    with st.expander(f"👁️ Prévisualiser l'horaire sélectionné ({h_choisi['label']})", expanded=False):
        lignes_preview = []
        try:
            with open(h_choisi["chemin"], "r", encoding="utf-8") as f_prev:
                lignes_preview = json.load(f_prev)
        except Exception:
            lignes_preview = []

        if lignes_preview and isinstance(lignes_preview, list):
            df_prev_list = []
            for r_p in lignes_preview:
                if isinstance(r_p, list) and r_p:
                    df_prev_list.append({
                        "Semaine": str(r_p[0]),
                        "Match 1": str(r_p[1]) if len(r_p) > 1 else "—",
                        "Match 2": str(r_p[2]) if len(r_p) > 2 else "—",
                        "Match 3": str(r_p[3]) if len(r_p) > 3 else "—",
                        "Match 4": str(r_p[4]) if len(r_p) > 4 else "—",
                    })
            if df_prev_list:
                st.dataframe(pd.DataFrame(df_prev_list), use_container_width=True, hide_index=True)
        else:
            st.caption("Fichier d'horaire vide ou invalide.")


def afficher_editeur_horaire_saison(key_prefix="admin_horaire", editeur_ouvert=True):
    """Affiche les outils de création et d'édition manuelle de l'horaire de la saison (réservé au volet Administration -> Saison)."""
    # Affichage du sélecteur de tous les horaires de saison disponibles
    afficher_selecteur_horaires_disponibles(key_prefix=f"{key_prefix}_bibliotheque")
    st.divider()

    num_saison_en_cours = st.session_state.get("saison_active_selectionnee", 1)
    lignes_horaire = charger_horaire_json(num_saison_en_cours)
    if not isinstance(lignes_horaire, list):
        lignes_horaire = []

    mois_fr_map = {
        1: "janvier", 2: "février", 3: "mars", 4: "avril", 5: "mai", 6: "juin",
        7: "juillet", 8: "août", 9: "septembre", 10: "octobre", 11: "novembre", 12: "décembre"
    }

    with st.expander(f"✏️ Éditer manuellement l'horaire (Saison {num_saison_en_cours})", expanded=editeur_ouvert):
        st.caption(
            f"Modifiez directement les cellules de la **Saison {num_saison_en_cours}** ci-dessous (format recommandé : `JJ mois Receveur Visiteur`), "
            "ajoutez une semaine avec le bouton `+` en bas du tableau ou utilisez l'assistant rapide, puis cliquez sur **💾 Enregistrer l'horaire de la saison**."
        )

        # Assistant rapide pour composer ou modifier un match précis
        equipes_dispo_h = charger_equipes_csv()
        liste_eq_h = list(equipes_dispo_h.keys()) if equipes_dispo_h else ["Alpha", "Bravo", "Charlie", "Delta", "Echo", "Foxtrot", "Golf", "Hotel"]
        semaines_existantes = [str(r[0]).strip() for r in lignes_horaire if isinstance(r, list) and len(r) > 0]
        if not semaines_existantes:
            semaines_existantes = [f"Semaine {i}" for i in range(1, 15)]
        options_sem_assist = semaines_existantes + ["➕ Nouvelle semaine..."]

        a_semaine_vacante = any(
            isinstance(r, list) and len(r) > 5 and ("vacant" in str(r[5]).lower() or "exempt" in str(r[5]).lower() or "bye" in str(r[5]).lower())
            for r in lignes_horaire
        )
        a_match_5 = any(isinstance(r, list) and len(r) > 5 and str(r[5]).strip() not in ("", "—", "-") for r in lignes_horaire)

        with st.container(border=True):
            st.markdown("##### 🛠️ Assistant rapide : insérer ou modifier un match ou une semaine vacante")
            c_as1, c_as2, c_as3, c_as4, c_as5 = st.columns([1.2, 1.2, 1.1, 1.1, 1.1])
            with c_as1:
                sem_choisie = st.selectbox("Semaine :", options_sem_assist, key=f"{key_prefix}_as_sem")
                if sem_choisie == "➕ Nouvelle semaine...":
                    sem_cible_finale = st.text_input("Nom de la semaine :", value=f"Semaine {len(semaines_existantes) + 1}", key=f"{key_prefix}_as_new_sem").strip()
                else:
                    sem_cible_finale = sem_choisie
            with c_as2:
                slot_choisi = st.selectbox(
                    "Emplacement :",
                    ["Match 1 (Lundi)", "Match 2 (Mardi)", "Match 3 (Mercredi)", "Match 4 (Jeudi)", "Semaine vacante (Exempt)"],
                    key=f"{key_prefix}_as_slot"
                )
            est_slot_vacant = (slot_choisi == "Semaine vacante (Exempt)")
            with c_as3:
                date_choisie = st.date_input("Date du match :", value=datetime.today(), key=f"{key_prefix}_as_date", disabled=est_slot_vacant)
            with c_as4:
                lbl_rec = "⏸️ Équipe vacante :" if est_slot_vacant else "🏠 Receveur :"
                rec_choisi = st.selectbox(lbl_rec, liste_eq_h, index=0, key=f"{key_prefix}_as_rec")
            with c_as5:
                idx_vis_def = 1 if len(liste_eq_h) > 1 else 0
                vis_choisi = st.selectbox("🚗 Visiteur :", liste_eq_h, index=idx_vis_def, key=f"{key_prefix}_as_vis", disabled=est_slot_vacant)

            if est_slot_vacant:
                texte_compose = f"Semaine vacante : {rec_choisi}"
            else:
                texte_compose = f"{date_choisie.day} {mois_fr_map.get(date_choisie.month, 'janvier')} {rec_choisi} {vis_choisi}"

            col_ap1, col_ap2 = st.columns([2.5, 1.5])
            with col_ap1:
                st.caption(f"Aperçu de la cellule : **`{texte_compose}`** ({sem_cible_finale} • {slot_choisi})")
            with col_ap2:
                if st.button("➕ Appliquer à l'horaire", use_container_width=True, key=f"{key_prefix}_btn_apply_assist"):
                    nouvelles_lignes_as = [list(r) for r in lignes_horaire if isinstance(r, list) and r]
                    trouve_sem = False
                    for r_item in nouvelles_lignes_as:
                        while len(r_item) < 7:
                            r_item.append("—")
                        if str(r_item[0]).strip().lower() == sem_cible_finale.lower():
                            if est_slot_vacant:
                                r_item[5] = texte_compose
                            else:
                                slot_idx = ["Match 1 (Lundi)", "Match 2 (Mardi)", "Match 3 (Mercredi)", "Match 4 (Jeudi)"].index(slot_choisi) + 1
                                r_item[slot_idx] = texte_compose
                            trouve_sem = True
                            break
                    if not trouve_sem:
                        nouv_row = [sem_cible_finale, "—", "—", "—", "—", "—", "—"]
                        if est_slot_vacant:
                            nouv_row[5] = texte_compose
                        else:
                            slot_idx = ["Match 1 (Lundi)", "Match 2 (Mardi)", "Match 3 (Mercredi)", "Match 4 (Jeudi)"].index(slot_choisi) + 1
                            nouv_row[slot_idx] = texte_compose
                        nouvelles_lignes_as.append(nouv_row)
                    if sauvegarder_horaire_json(nouvelles_lignes_as):
                        st.success(f"✅ `{texte_compose}` enregistré dans {sem_cible_finale} !")
                        time.sleep(0.6)
                        st.rerun()
                    else:
                        st.error("❌ Erreur lors de la sauvegarde de l'horaire.")

        # Tableau interactif complet st.data_editor
        lignes_edit_init = []
        for idx_r, row in enumerate(lignes_horaire):
            if not isinstance(row, list) or not row:
                continue
            item = {
                "Semaine": str(row[0]).strip() if len(row) > 0 else f"Semaine {idx_r + 1}",
                "Match 1": str(row[1]).strip() if len(row) > 1 and str(row[1]).strip() else "—",
                "Match 2": str(row[2]).strip() if len(row) > 2 and str(row[2]).strip() else "—",
                "Match 3": str(row[3]).strip() if len(row) > 3 and str(row[3]).strip() else "—",
                "Match 4": str(row[4]).strip() if len(row) > 4 and str(row[4]).strip() else "—",
            }
            if a_semaine_vacante:
                item["Semaine vacante"] = str(row[5]).strip() if len(row) > 5 and str(row[5]).strip() else "—"
            elif a_match_5:
                item["Match 5"] = str(row[5]).strip() if len(row) > 5 and str(row[5]).strip() else "—"
            lignes_edit_init.append(item)

        if not lignes_edit_init:
            for i_s in range(1, 15):
                lignes_edit_init.append({
                    "Semaine": f"Semaine {i_s}",
                    "Match 1": "—",
                    "Match 2": "—",
                    "Match 3": "—",
                    "Match 4": "—",
                })

        df_edit_init = pd.DataFrame(lignes_edit_init)
        col_cfg_editor = {
            "Semaine": st.column_config.TextColumn("Semaine", required=True, width="small"),
            "Match 1": st.column_config.TextColumn("Match 1 (Lundi)", width="medium"),
            "Match 2": st.column_config.TextColumn("Match 2 (Mardi)", width="medium"),
            "Match 3": st.column_config.TextColumn("Match 3 (Mercredi)", width="medium"),
            "Match 4": st.column_config.TextColumn("Match 4 (Jeudi)", width="medium"),
        }
        if a_semaine_vacante:
            col_cfg_editor["Semaine vacante"] = st.column_config.TextColumn("Semaine vacante (Exempt)", width="medium")
        elif a_match_5:
            col_cfg_editor["Match 5"] = st.column_config.TextColumn("Match 5", width="medium")

        df_horaire_modifie = st.data_editor(
            df_edit_init,
            num_rows="dynamic",
            use_container_width=True,
            hide_index=True,
            key=f"{key_prefix}_data_editor",
            column_config=col_cfg_editor
        )

        col_sv1, col_sv2 = st.columns([2, 1])
        with col_sv1:
            if st.button("💾 Enregistrer l'horaire de la saison", type="primary", use_container_width=True, key=f"{key_prefix}_btn_save_table"):
                nouvelles_lignes_horaire = []
                for idx_row, r_ed in df_horaire_modifie.iterrows():
                    sem_val = str(r_ed.get("Semaine", "") or "").strip()
                    if not sem_val or sem_val.lower() == "nan":
                        sem_val = f"Semaine {len(nouvelles_lignes_horaire) + 1}"
                    m1_val = str(r_ed.get("Match 1", "—") or "—").strip()
                    m2_val = str(r_ed.get("Match 2", "—") or "—").strip()
                    m3_val = str(r_ed.get("Match 3", "—") or "—").strip()
                    m4_val = str(r_ed.get("Match 4", "—") or "—").strip()
                    m1_val = "—" if not m1_val or m1_val.lower() == "nan" else m1_val
                    m2_val = "—" if not m2_val or m2_val.lower() == "nan" else m2_val
                    m3_val = "—" if not m3_val or m3_val.lower() == "nan" else m3_val
                    m4_val = "—" if not m4_val or m4_val.lower() == "nan" else m4_val
                    m5_val = "—"
                    m6_val = "—"
                    if "Semaine vacante" in r_ed:
                        m5_val = str(r_ed.get("Semaine vacante", "—") or "—").strip()
                    elif "Match 5" in r_ed:
                        m5_val = str(r_ed.get("Match 5", "—") or "—").strip()
                    elif idx_row < len(lignes_horaire) and isinstance(lignes_horaire[idx_row], list) and len(lignes_horaire[idx_row]) > 5:
                        m5_val = str(lignes_horaire[idx_row][5] or "—")
                    m5_val = "—" if not m5_val or m5_val.lower() == "nan" else m5_val
                    if idx_row < len(lignes_horaire) and isinstance(lignes_horaire[idx_row], list) and len(lignes_horaire[idx_row]) > 6:
                        m6_val = str(lignes_horaire[idx_row][6] or "—")
                    m6_val = "—" if not m6_val or m6_val.lower() == "nan" else m6_val
                    nouvelles_lignes_horaire.append([sem_val, m1_val, m2_val, m3_val, m4_val, m5_val, m6_val])

                if not nouvelles_lignes_horaire:
                    st.error("❌ L'horaire doit contenir au moins une semaine.")
                else:
                    if sauvegarder_horaire_json(nouvelles_lignes_horaire):
                        st.success(f"✅ Horaire de la saison enregistré avec succès ({len(nouvelles_lignes_horaire)} semaines) et synchronisé sur GitHub !")
                        time.sleep(0.8)
                        st.rerun()
                    else:
                        st.error("❌ Erreur lors de l'enregistrement de `horaire_saphir.json`.")
        with col_sv2:
            if st.button("➕ Ajouter une semaine (fin)", use_container_width=True, key=f"{key_prefix}_btn_add_week"):
                nouvelles_lignes_add = [list(r) for r in lignes_horaire if isinstance(r, list) and r]
                prochain_num = len(nouvelles_lignes_add) + 1
                nouvelles_lignes_add.append([f"Semaine {prochain_num}", "—", "—", "—", "—", "—", "—"])
                if sauvegarder_horaire_json(nouvelles_lignes_add):
                    st.success(f"✅ Semaine {prochain_num} ajoutée à l'horaire !")
                    time.sleep(0.6)
                    st.rerun()



# ==============================================================================

