                with col_app_v:

                    app_vis_ant = st.selectbox("Approbateur officiel (Visiteur) :", [dict_joueurs_ant[k]["nom"] for k in ["j1_vis", "j2_vis", "j3_vis"]], key="ant_app_vis")



